/*
  READY LESSONS: a lesson for every area of the Curriculum for Excellence literacy and numeracy
  benchmarks, at Early to Fourth level, and for England's national curriculum from Reception to key
  stage 4, so a tutor can support any gap straight away.

  WRITTEN BY tools/build.mjs (npm run build) from content/lessons/*.json: edit those files, not this one.

  Each lesson is built from the official guidance only (Education Scotland's Experiences and
  Outcomes and Benchmarks, June 2017; the Department for Education's programmes of study): the
  success criteria are the benchmark statements for that area, in "I can" form. A lesson is about
  30 minutes: start (5), teach (10), practise (10), check (5). It links to PopSpell's online work and
  printable sheets where they fit ("use"), ends with something to do at home, and has a question to
  check understanding ("understand", with what to look for in "lookFor").

    level      Early | First | Second | Third | Fourth
    subject    Literacy | Maths
    strand     the library strand it appears under
    codes      the CfE Experiences and Outcomes it covers (England's statements are in england.js)
    use        PopSpell activity, spelling list or paper sheet ids for the practice
    england    true for lessons written from England's curriculum; "cfe" is their Scottish version, if any
*/
window.PopLessons = (() => {
  "use strict";
  const lessons = [
    {"id":"lesson-early-estimate-then-count","level":"Early","subject":"Maths","strand":"Number","codes":["MNU 0-01a"],"title":"Estimate, then count","intention":"We are learning to estimate how many, then count to check.","criteria":["I can say how many are in a small group without counting.","I can estimate how many, then count to check.","I can use the words more than, less than and the same."],"steps":{"start":"Flash a dice pattern or a few counters for two seconds. How many? How did you know without counting?","teach":"Put up to 20 objects in a clear tub. Ask for an estimate, then count together, touching and moving each one. Compare: was it more than, less than or the same as the guess?","practise":"Play the firefly game: say how many lit up without counting.","check":"Scatter 4 or 5 counters, cover after two seconds: how many? Then estimate a bigger group and check by counting."},"use":["g-canopy-flash"],"home":"Guess how many grapes, pegs or spoons, then count to check.","vocab":"estimate, guess, count, more than, less than, the same","understand":"Why is it fine if your guess wasn't exactly right?","lookFor":"Knows a guess is a sensible estimate, then counting checks it; can say if the count was more or less than the guess."},
    {"id":"lesson-early-counting-to-20-and-beyond","level":"Early","subject":"Maths","strand":"Number","codes":["MNU 0-02a"],"title":"Counting to 20 and beyond","intention":"We are learning to count objects and say the number sequence forwards and backwards.","criteria":["I can count forwards to 30 from any number.","I can count backwards from 20.","I can touch and count objects to 20, and the last number tells me how many.","I know zero means none."],"steps":{"start":"Count forwards together from 0 to 30, then start from a different number (7, 12, 18).","teach":"Count a set of up to 20 objects, touching and moving each one. Ask: how many altogether? Show that counting in a different order gives the same total. Count back from 20 to 0, and talk about 0 meaning none.","practise":"Build the bridge in the Counting Canopy, counting each piece.","check":"Give a pile of 14 objects: count them. Then count back from 15."},"use":["g-canopy-make"],"home":"Count stairs, steps or socks together, forwards and backwards.","vocab":"count, how many, altogether, zero, none, forwards, backwards","understand":"If I count these again starting from a different one, will I get the same number? Why?","lookFor":"Knows the total doesn't change with the order, and that the last number counted tells how many."},
    {"id":"lesson-early-before-after-and-in-between","level":"Early","subject":"Maths","strand":"Number","codes":["MNU 0-02a"],"title":"Before, after and in between","intention":"We are learning to read, order and find numbers to 20.","criteria":["I can recognise numbers from 0 to 20.","I can say the number before, after and in between.","I can put numbers to 20 in order and find missing numbers.","I can use first, second and third."],"steps":{"start":"Hold up number cards 0–20 in a muddle. Which do you know?","teach":"Peg numbers on a line to 20. Hide one: which is missing? Ask: what comes after 9? before 14? between 11 and 13? Line toys up and use first, second, third.","practise":"Bigger or smaller: compare two numbers.","check":"Give five number cards to put in order, then ask for the number before and after one of them."},"use":["n-compare"],"home":"Find house or bus numbers: what comes before and after?","vocab":"before, after, between, first, second, third, order","understand":"How do you know 14 comes after 13 and not before?","lookFor":"Uses the counting order or a number line: after means one more."},
    {"id":"lesson-early-adding-and-taking-away-within-10","level":"Early","subject":"Maths","strand":"Number","codes":["MNU 0-03a"],"title":"Adding and taking away within 10","intention":"We are learning to add and take away by counting on and back.","criteria":["I can count on to add and count back to take away.","I can use the signs +, − and =.","I can add and take away in my head to 10.","I can solve a simple missing number problem."],"steps":{"start":"Five frame flash: show 3, add 2 more. How many now?","teach":"Use counters and a ten frame. Model 4 + 3 by counting on from 4. Model 7 − 2 by counting back. Write each as a number sentence with + − =. Try 5 + ? = 8 with counters hidden under a cup.","practise":"Adding within 10, then Taking away within 10.","check":"Ask 6 + 3, 9 − 4 and 2 + ? = 7, with counters if needed."},"use":["n-add-10","n-sub-10"],"home":"Make up number stories with toys: 3 cars park, 2 more arrive.","vocab":"add, plus, take away, minus, equals, makes, how many left","understand":"Here is 6 + 2. Can you tell me a story that matches it?","lookFor":"Makes up a sensible story: something is added to a group, and the total is bigger."},
    {"id":"lesson-early-doubles-and-splitting-numbers-to-10","level":"Early","subject":"Maths","strand":"Number","codes":["MNU 0-03a"],"title":"Doubles and splitting numbers to 10","intention":"We are learning that numbers can be split into parts, and to double.","criteria":["I can split 10 into two parts in different ways.","I can double numbers to make up to 10.","I know the total stays the same when I move the parts."],"steps":{"start":"Show 5 fingers on one hand and 2 on the other: how many? Do it with different numbers.","teach":"Take 10 counters and split them into two groups in every way you can (7 and 3, 6 and 4…). Record them. Then use a mirror or both hands to double 1 to 5.","practise":"Hidden fireflies: work out how many are hiding.","check":"Ask: 10 is 6 and how many? What is double 4?"},"use":["g-canopy-hidden","n-bonds-10"],"home":"Share 10 pasta pieces between two plates in different ways.","vocab":"double, split, part, whole, altogether","understand":"Can 7 be split another way? How many ways can you find?","lookFor":"Finds more than one split (5 and 2, 4 and 3) and sees both parts together make 7."},
    {"id":"lesson-early-sharing-equally-and-halves","level":"Early","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MNU 0-07a"],"title":"Sharing equally and halves","intention":"We are learning to share equally and find half.","criteria":["I can share a group of things out equally.","I can split a whole into parts and know equal parts are the same size.","I can find half of a shape or a group."],"steps":{"start":"Two teddies want to share 6 sweets. Is it fair if one gets 4?","teach":"Share objects one at a time onto two plates. Fold a paper shape in half and check the parts match. Show a sandwich cut fairly and unfairly: which is halves?","practise":"Share sets of 4, 6, 8 and 10 between two, then between three or four.","check":"Show a shape cut into two unequal pieces: is it halves? Why not?"},"use":[],"home":"Cut toast or fruit in half at snack time: are the halves the same size?","vocab":"share, equal, fair, half, halves, whole","understand":"Is this half? How do you know?","lookFor":"Checks both parts are the same size or the same number, not just that there are two parts."},
    {"id":"lesson-early-coins-and-paying-up-to-10p","level":"Early","subject":"Maths","strand":"Money","codes":["MNU 0-09a"],"title":"Coins and paying up to 10p","intention":"We are learning to know our coins and pay for things up to 10p.","criteria":["I can name all the coins to £2.","I can pay the exact amount up to 10p using 1p, 2p, 5p and 10p coins.","I can say if I have given too much, not enough or the right amount."],"steps":{"start":"Tip out real or toy coins. Sort them. Which do you know?","teach":"Name each coin up to £2. Set up a shop with prices up to 10p. Show paying 7p as 5p and 2p, or seven 1p coins. Talk about giving too much and getting change.","practise":"Counting money: add up the coins.","check":"Price a toy at 8p: pay for it two different ways."},"use":["n-money-10"],"home":"Let your child pay for something small and talk about the coins.","vocab":"coin, pence, pound, pay, price, change, enough","understand":"Which is worth more, one 5p coin or three 1p coins? Why?","lookFor":"Knows a coin's value isn't how many coins there are: 5p is worth more than 3p."},
    {"id":"lesson-early-days-routines-and-o-clock","level":"Early","subject":"Maths","strand":"Time","codes":["MNU 0-10a"],"title":"Days, routines and o'clock","intention":"We are learning about the order of our day, the days of the week and o'clock.","criteria":["I can put the events of my day in order.","I can say the days of the week in order and know the months and seasons.","I can read o'clock times on a clock and a digital display.","I know the hour hand and the minute hand."],"steps":{"start":"What did you do first today? What happens next? What happens at night?","teach":"Order picture cards of a day (wake up, breakfast, school, tea, bed). Say the days of the week and talk about the seasons. On a clock, show the minute hand pointing to 12 for o'clock and move the hour hand.","practise":"Telling the time: the o'clock questions.","check":"Set 3 o'clock on a clock: what time is it? What day comes after Tuesday?"},"use":["n-time-oclock"],"home":"Point out o'clock times at home and talk about tomorrow's day.","vocab":"o'clock, hour hand, minute hand, morning, afternoon, night, days, months, seasons","understand":"The long hand is on 12 and the short hand is on 3. Is it o'clock? What might you be doing at 3 o'clock in the afternoon?","lookFor":"Explains that the long hand on 12 means o'clock and the short hand shows the hour, and links the time to a real part of their own day."},
    {"id":"lesson-early-longer-heavier-and-holds-more","level":"Early","subject":"Maths","strand":"Measurement","codes":["MNU 0-11a"],"title":"Longer, heavier and holds more","intention":"We are learning to compare sizes and measure with everyday things.","criteria":["I can compare length, height, weight and how much things hold.","I can use longer, shorter, taller, heavier, lighter, more and less.","I can estimate and then measure with things like cubes or hand spans."],"steps":{"start":"Which is taller, you or the door? Which is heavier, a book or a feather?","teach":"Compare two pencils (longer/shorter), two bags (heavier/lighter using hands as a balance), and two cups of water (holds more/less). Estimate how many cubes long a book is, then measure.","practise":"Measure three objects in cubes or hand spans and put them in order.","check":"Give two objects: which is longer? How many cubes long is it?"},"use":[],"home":"Baking: talk about full, empty, more and less when measuring.","vocab":"long, short, tall, heavy, light, full, empty, more, less, measure","understand":"How could we check which is longer fairly?","lookFor":"Lines the ends up together, or uses the same thing to measure both."},
    {"id":"lesson-early-copying-and-continuing-patterns","level":"Early","subject":"Maths","strand":"Patterns and missing numbers","codes":["MTH 0-13a"],"title":"Copying and continuing patterns","intention":"We are learning to copy, continue and make patterns.","criteria":["I can copy and continue a pattern with objects, shapes or numbers.","I can make my own pattern.","I can find missing numbers on a number line to 20."],"steps":{"start":"Clap–stamp–clap–stamp: what comes next?","teach":"Make a red–blue–red–blue bead pattern. Continue it, then make AAB patterns. Count in ones along a number line and find gaps.","practise":"Number patterns: find the next number.","check":"Show a pattern with a gap: what is missing?"},"use":["m-patterns-early"],"home":"Spot patterns on clothes, tiles and fences.","vocab":"pattern, repeat, next, missing","understand":"What comes next? How do you know?","lookFor":"Names the part that repeats and uses it to say what comes next."},
    {"id":"lesson-early-sorting-2d-shapes-and-3d-objects","level":"Early","subject":"Maths","strand":"Shape and angles","codes":["MTH 0-16a"],"title":"Sorting 2D shapes and 3D objects","intention":"We are learning to name, describe and sort shapes.","criteria":["I can name common 2D shapes and 3D objects.","I can describe them as straight, round, flat or curved.","I can sort shapes in different ways."],"steps":{"start":"Feely bag: describe a shape you can feel without looking.","teach":"Name circle, square, triangle, rectangle; cube, sphere, cone, cylinder. Sort them: flat or not, rolls or not, straight or curved sides.","practise":"2D shapes: name the shape and count the sides.","check":"Give three shapes to name and say one thing about each."},"use":["m-shapes-2d"],"home":"Go on a shape hunt in the kitchen or on a walk.","vocab":"circle, square, triangle, rectangle, cube, sphere, cone, cylinder, flat, curved","understand":"Is this still a triangle if I turn it round? Why?","lookFor":"Knows turning a shape doesn't change it: it still has 3 sides and 3 corners."},
    {"id":"lesson-early-position-direction-and-symmetry","level":"Early","subject":"Maths","strand":"Shape and angles","codes":["MTH 0-17a","MTH 0-19a"],"title":"Position, direction and symmetry","intention":"We are learning words for position and direction, and to make symmetrical pictures.","criteria":["I can use in front, behind, above, below, left, right, forwards and backwards.","I can follow and give simple directions.","I can make a picture with one line of symmetry."],"steps":{"start":"Simon says: put your hand above your head, behind your back.","teach":"Hide a toy and give directions to find it. Fold paper, paint on one side and press to make a symmetrical butterfly.","practise":"Give the pupil directions to move a toy on a grid, then swap roles.","check":"Where is the cup? (in front of / behind the book). Is this picture the same on both sides?"},"use":[],"home":"Play a hide-and-seek game giving directions.","vocab":"in front, behind, above, below, left, right, forwards, backwards, symmetry","understand":"Hide a toy and give me clues with words like behind, under and next to. Which clue helped me most? Why?","lookFor":"Chooses position words to suit a new hiding place, and can say which clue helped and why."},
    {"id":"lesson-early-sorting-and-simple-charts","level":"Early","subject":"Maths","strand":"Data and chance","codes":["MNU 0-20a","MNU 0-20b","MNU 0-20c"],"title":"Sorting and simple charts","intention":"We are learning to sort things and show what we found.","criteria":["I can sort objects by colour, shape or size.","I can ask a question and collect answers.","I can make a picture chart where one picture is one thing.","I can answer questions about a simple chart."],"steps":{"start":"Sort a pile of buttons or toys: how did you sort them?","teach":"Ask family members their favourite fruit. Show each answer with one picture. Which has most? Least? Count tally marks in fives.","practise":"Tally marks: count them in fives.","check":"Look at a picture chart: which has the most? How many like apples?"},"use":["n-tally"],"home":"Sort the washing or toys and count each group.","vocab":"sort, group, most, least, chart, tally","understand":"What does our chart tell us? Which has the most?","lookFor":"Reads the chart to answer a question, not just describing the pictures."},
    {"id":"lesson-first-rounding-to-estimate","level":"First","subject":"Maths","strand":"Number","codes":["MNU 1-01a"],"title":"Rounding to estimate","intention":"We are learning to round to the nearest 10 and 100 to estimate and check answers.","criteria":["I can round whole numbers to the nearest 10 and 100.","I can use rounding or doubling to estimate an answer.","I can check if my answer is sensible."],"steps":{"start":"Is 48 nearer 40 or 50? Show it on a number line.","teach":"Use a number line to round 2-digit numbers to 10, then 3-digit numbers to 100. Model estimating 38 + 41 as 40 + 40, then working it out and comparing.","practise":"Rounding to the nearest 10.","check":"Round 67 and 352. Estimate 29 + 52, then check."},"use":["n-round-10","n-round-10-100"],"home":"Round prices in the shop to estimate the total.","vocab":"round, nearest, estimate, about, check, sensible","understand":"Why would you round before you work it out?","lookFor":"Uses rounding to check whether an answer is sensible."},
    {"id":"lesson-first-place-value-to-1000","level":"First","subject":"Maths","strand":"Number","codes":["MNU 1-02a"],"title":"Place value to 1000","intention":"We are learning what each digit is worth in numbers to 1000.","criteria":["I can read, write and order numbers to 1000.","I know zero holds a place, as in 405.","I can say what each digit is worth, as in 867 = 800 + 60 + 7."],"steps":{"start":"Make 34 with tens and ones. How many tens? How many ones?","teach":"Use hundreds, tens and ones (blocks or place value cards) to build 3-digit numbers. Show 405 and why the zero matters. Order four 3-digit numbers.","practise":"Tens and ones, then Hundreds, tens and ones.","check":"What is the 6 worth in 263? Write 'four hundred and nine' in digits."},"use":["n-place-value","n-hundreds"],"home":"Read big numbers on signs and prices together.","vocab":"digit, place, value, hundreds, tens, ones, zero","understand":"What is the 4 worth in 346? What if it moved to the hundreds?","lookFor":"Explains the value of a digit depends on its place."},
    {"id":"lesson-first-counting-in-2s-5s-10s-and-100s","level":"First","subject":"Maths","strand":"Patterns and missing numbers","codes":["MNU 1-02a","MTH 1-13b"],"title":"Counting in 2s, 5s, 10s and 100s","intention":"We are learning to count forwards and backwards in steps.","criteria":["I can count forwards and backwards in 2s, 5s and 10s from any number to 1000.","I can count in 100s.","I can spot the pattern in the steps."],"steps":{"start":"Count in 10s from 0, then from 3 (3, 13, 23…).","teach":"Use a hundred square to show counting in 2s, 5s and 10s. Count back too. Count in 100s from 50.","practise":"Number patterns.","check":"Count on in 5s from 35. Count back in 2s from 20."},"use":["m-patterns"],"home":"Count in 2s using pairs of socks or shoes.","vocab":"count on, count back, steps, pattern, multiple","understand":"What do you notice about numbers when you count in 5s?","lookFor":"Spots the pattern (they end in 0 or 5) and uses it to continue or check."},
    {"id":"lesson-first-adding-and-subtracting-within-20","level":"First","subject":"Maths","strand":"Number","codes":["MNU 1-02a","MNU 1-03a"],"title":"Adding and subtracting within 20","intention":"We are learning to add and subtract quickly within 20.","criteria":["I know number bonds to 10 and 20.","I can add and subtract within 20 using what I know.","I know addition can be done in any order, as in 6 + 3 = 3 + 6."],"steps":{"start":"Quick-fire bonds to 10: 7 and ? make 10.","teach":"Use a bead string or ten frames. Show bridging through 10: 8 + 5 = 8 + 2 + 3. Show 6 + 3 = 3 + 6. Use 'I know 7 + 3 = 10, so 17 + 3 = 20'.","practise":"Number bonds to 20, Adding within 20, Taking away within 20.","check":"Ask 9 + 6, 15 − 7 and 13 + ? = 20, and how they worked it out."},"use":["n-bonds-20","n-add-20","n-sub-20"],"home":"Play a quick bonds game in the car: I say 6, you say 4.","vocab":"add, subtract, sum, total, difference, bond, bridge","understand":"If 8 + 6 = 14, what else do you know?","lookFor":"Uses the fact to find others: 6 + 8 = 14, 14 − 6 = 8, 14 − 8 = 6."},
    {"id":"lesson-first-adding-and-subtracting-to-1000","level":"First","subject":"Maths","strand":"Number","codes":["MNU 1-02a","MNU 1-03a"],"title":"Adding and subtracting to 1000","intention":"We are learning to add and subtract 3-digit numbers.","criteria":["I can add and subtract multiples of 10 and 100 to and from numbers to 1000.","I can add and subtract 3-digit numbers.","I can use the inverse to check."],"steps":{"start":"What is 340 + 100? 340 + 10? 340 − 20?","teach":"Model partitioning: 253 + 125 = 200 + 100, 50 + 20, 3 + 5. Then a written method. Check 378 − 125 = 253 by adding back.","practise":"Adding and taking away bigger numbers.","check":"Work out 436 + 251 and 587 − 230, and check one with the inverse."},"use":["n-big-add"],"home":"Add up two prices or two distances from a map.","vocab":"add, subtract, partition, inverse, check","understand":"How could you check your answer?","lookFor":"Uses the inverse (adds back) or an estimate to check, and explains why the check works."},
    {"id":"lesson-first-multiplication-facts-2-3-4-5-and-10","level":"First","subject":"Maths","strand":"Number","codes":["MNU 1-02a","MNU 1-03a"],"title":"Multiplication facts: 2, 3, 4, 5 and 10","intention":"We are learning to work out and remember multiplication facts.","criteria":["I can work out multiplication facts using repeated addition, groups and arrays.","I know 2 × 4 = 4 × 2.","I can recall facts for the 2, 3, 4, 5 and 10 times tables."],"steps":{"start":"Count in 5s to 50 on your fingers.","teach":"Build arrays with counters: 3 rows of 4. Write it as 4 + 4 + 4 and 3 × 4, then turn it to show 4 × 3. Link doubles to the 2 and 4 times tables.","practise":"2, 5 and 10 times tables, then 3 and 4 times tables.","check":"Show an array: write two multiplication facts. Ask 4 × 5 and 3 × 6."},"use":["n-tables-2-5-10","n-tables-3-4","n-doubles"],"home":"Spot arrays at home: egg boxes, muffin trays, windows.","vocab":"multiply, times, groups of, lots of, array, product","understand":"How could 2 × 5 help you work out 4 × 5?","lookFor":"Uses doubling or facts they know to find a new fact, rather than counting from the start."},
    {"id":"lesson-first-division-sharing-and-grouping","level":"First","subject":"Maths","strand":"Number","codes":["MNU 1-02a","MNU 1-03a"],"title":"Division: sharing and grouping","intention":"We are learning to divide by sharing and grouping.","criteria":["I can divide by sharing equally and by making equal groups.","I can use multiplication facts to divide.","I know division undoes multiplication."],"steps":{"start":"Share 12 counters between 3 people. How many each?","teach":"Show 12 ÷ 3 two ways: sharing into 3 groups, and making groups of 3. Link to 3 × 4 = 12. Try a remainder: 13 ÷ 3.","practise":"Division facts.","check":"Ask 20 ÷ 5 and 18 ÷ 2, and which times table fact helps."},"use":["n-division"],"home":"Share snacks fairly between the family.","vocab":"divide, share, equal groups, shared equally, remainder","understand":"Here is 12 ÷ 3. Show it as sharing, then as grouping.","lookFor":"Can show both and knows the answer is the same."},
    {"id":"lesson-first-multiplying-and-dividing-by-10-and-100","level":"First","subject":"Maths","strand":"Number","codes":["MNU 1-03a"],"title":"Multiplying and dividing by 10 and 100","intention":"We are learning to multiply and divide whole numbers by 10 and 100.","criteria":["I can multiply and divide whole numbers by 10 and 100.","I can explain how the digits move."],"steps":{"start":"What is 10 lots of 3? 10 lots of 30?","teach":"Use a place value grid. Show 23 × 10 = 230: the digits move one place left. ×100 moves two places. Dividing moves them right.","practise":"Multiplying and dividing by 10 and 100.","check":"Ask 45 × 10, 6 × 100 and 700 ÷ 10."},"use":["n-x10"],"home":"How many 10p coins make £3? How many pence in £5?","vocab":"multiply, divide, place, digit, ten times","understand":"What happens to the digits when you multiply by 10?","lookFor":"Says the digits move one place bigger, rather than just \"add a zero\"."},
    {"id":"lesson-first-solving-two-step-problems","level":"First","subject":"Maths","strand":"Number","codes":["MNU 1-03a"],"title":"Solving two-step problems","intention":"We are learning to choose what to do in a problem and solve it in two steps.","criteria":["I can decide which calculation a problem needs.","I can solve two-step problems.","I can check my answer makes sense."],"steps":{"start":"Tell a one-step story: 5 apples, 3 more. Now add a second step: then 2 are eaten.","teach":"Read a problem together. Underline the important numbers. Draw a bar model or picture. Decide step 1 and step 2. Check with an estimate.","practise":"Missing numbers and signs, then make up a two-step problem for the tutor to solve.","check":"Sam has 24 stickers, gets 10 more and gives away 8. How many now?"},"use":["m-equations"],"home":"Make up shopping problems: two things, then change.","vocab":"problem, calculate, step, total, left, more, fewer","understand":"Before you work it out: what are the two steps, and why that order?","lookFor":"Explains which operation each step needs and why."},
    {"id":"lesson-first-what-fractions-are","level":"First","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MNU 1-07a"],"title":"What fractions are","intention":"We are learning to name, write and compare fractions.","criteria":["I can explain what a fraction is using pictures or objects.","I know the more equal parts, the smaller each part.","I can write fractions like ½, ⅔ and ⅝, and say what the numerator and denominator mean.","I can compare fractions and place them on a number line."],"steps":{"start":"Fold a paper strip in half, then quarters, then eighths. What happens to the parts?","teach":"Use fraction strips. Write ½, ¼, ⅛ and show which is biggest. Explain numerator (parts we have) and denominator (equal parts in the whole). Place ½ and ¼ on a 0–1 number line.","practise":"Halves, quarters and thirds.","check":"Which is bigger, ⅓ or ⅕? Show ¾ of a shape."},"use":["n-fractions"],"home":"Cut a pizza or cake into equal parts and name the fractions.","vocab":"fraction, half, quarter, third, numerator, denominator, equal parts","understand":"Which is bigger, one half or one quarter of the same pizza? Why?","lookFor":"Explains more equal parts means each part is smaller."},
    {"id":"lesson-first-fractions-of-amounts-and-equivalent-fractions","level":"First","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MNU 1-07b","MTH 1-07c"],"title":"Fractions of amounts and equivalent fractions","intention":"We are learning to find a fraction of a number and to spot fractions that are the same.","criteria":["I can find a fraction of an amount using division, as in ¼ of 12.","I can show simple equivalent fractions, as in ½ = 2/4."],"steps":{"start":"Share 12 sweets into 4 equal groups. What is ¼ of 12?","teach":"Link ¼ of 20 to 20 ÷ 4. Then use fraction strips to show ½ = 2/4 = 4/8.","practise":"Halves, quarters and thirds, then Equivalent fractions.","check":"Ask ⅓ of 15 and draw a picture to show ½ = 3/6."},"use":["n-fractions","n-equivalent"],"home":"Find half or a quarter of a bag of pasta shapes.","vocab":"fraction of, share, equivalent, same as","understand":"How do you find a quarter of 20? Why does that work?","lookFor":"Links finding a quarter to sharing into 4 equal groups."},
    {"id":"lesson-first-paying-and-change-within-10","level":"First","subject":"Maths","strand":"Money","codes":["MNU 1-09a","MNU 1-09b"],"title":"Paying and change within £10","intention":"We are learning to pay for things and work out change.","criteria":["I know all coins and notes to £20.","I can write amounts correctly, as in 149p = £1·49.","I can pay for things and work out change within £10.","I know things can be paid for with cards and phones."],"steps":{"start":"Make £1 in three different ways with coins.","teach":"Write prices both ways (75p, £0·75). Total two items. Count on to find change from £5 or £10 (from £3·60: 40p makes £4, then £1 makes £5).","practise":"Counting money.","check":"A book costs £3·45. What change from £5?"},"use":["n-money"],"home":"Let your child work out the change when you pay.","vocab":"pounds, pence, total, change, cost, note, card","understand":"You pay with 10p for something that costs 7p. How much change? How did you work it out?","lookFor":"Counts on from the cost to the amount paid, or takes away, and explains which."},
    {"id":"lesson-first-half-past-quarter-past-and-quarter-to","level":"First","subject":"Maths","strand":"Time","codes":["MNU 1-10a"],"title":"Half past, quarter past and quarter to","intention":"We are learning to tell the time to the quarter hour.","criteria":["I can tell half past, quarter past and quarter to on analogue and digital clocks.","I can use am and pm.","I know 24-hour times are used on phones and computers."],"steps":{"start":"Show o'clock times and read them.","teach":"Show the clock face split into quarters. Move the minute hand: quarter past, half past, quarter to. Show the matching digital times (2:15, 2:30, 2:45). Talk about am and pm.","practise":"Telling the time, then Digital time.","check":"Set quarter to 4 on a clock. What is 7:30 on an analogue clock?"},"use":["n-time","n-time-digital"],"home":"Ask your child the time at quarter past, half past and quarter to.","vocab":"quarter past, half past, quarter to, am, pm, analogue, digital","understand":"Why is the hour hand between two numbers at half past?","lookFor":"Knows the hour hand moves on through the hour, not just the minute hand."},
    {"id":"lesson-first-calendars-dates-and-how-long","level":"First","subject":"Maths","strand":"Time","codes":["MNU 1-10b","MNU 1-10c"],"title":"Calendars, dates and how long","intention":"We are learning to use calendars and work out how long things take.","criteria":["I can write the date in words and numbers.","I can use a calendar to plan.","I know seconds in a minute, minutes in an hour, hours in a day, days in each month and in a year.","I can choose and use a timer."],"steps":{"start":"What is today's date? Write it two ways.","teach":"Use a calendar to find birthdays and count days between. Learn the time facts. Use a timer: how many star jumps in 30 seconds?","practise":"How long? Time intervals.","check":"How many days in June? How many minutes in an hour? What is the date one week from today?"},"use":["n-durations"],"home":"Put family birthdays on a calendar and count down.","vocab":"date, calendar, month, season, minute, hour, second, timer","understand":"How long is it from Monday to Thursday? How do you know?","lookFor":"Counts the gaps (days passing), not the days named."},
    {"id":"lesson-first-measuring-with-rulers-scales-and-jugs","level":"First","subject":"Maths","strand":"Measurement","codes":["MNU 1-11a"],"title":"Measuring with rulers, scales and jugs","intention":"We are learning to estimate and measure in standard units.","criteria":["I can estimate length, height, weight and capacity.","I can measure with rulers, metre sticks, scales and jugs to the nearest unit.","I can make simple conversions, as in 1 m 58 cm = 158 cm.","I can read scales, including halves."],"steps":{"start":"Estimate how long a pencil is in cm. Measure it.","teach":"Show starting a ruler at 0. Weigh fruit in grams, measure water in ml. Read a jug scale with ½ litre marked. Convert 1 m 20 cm to 120 cm.","practise":"Measuring: rulers, jugs and units.","check":"Measure a book in cm. Read a scale at 250 ml."},"use":["n-measure"],"home":"Bake together, measuring grams and millilitres.","vocab":"estimate, measure, centimetre, metre, gram, kilogram, millilitre, litre, scale","understand":"Why do we use centimetres instead of hand spans?","lookFor":"Explains standard units give the same answer whoever measures."},
    {"id":"lesson-first-area-by-counting-squares","level":"First","subject":"Maths","strand":"Measurement","codes":["MNU 1-11b"],"title":"Area by counting squares","intention":"We are learning to find area by counting squares.","criteria":["I can estimate and count squares to find the area of a shape, to the nearest half square.","I can make shapes with a given area.","I know different shapes can have the same area."],"steps":{"start":"How many squares cover this sticky note?","teach":"Draw shapes on squared paper. Count whole squares, then pair up halves. Make two different shapes with an area of 6 squares.","practise":"Draw three shapes with an area of 8 squares on squared paper.","check":"Count the area of a shape with some half squares."},"use":[],"home":"Count the tiles on a floor or wall to find its area.","vocab":"area, square, cover, half square","understand":"Can two different shapes have the same area?","lookFor":"Yes: area is how many squares are covered, not what the shape looks like."},
    {"id":"lesson-first-number-patterns-and-rules","level":"First","subject":"Maths","strand":"Patterns and missing numbers","codes":["MTH 1-13a","MTH 1-13b"],"title":"Number patterns and rules","intention":"We are learning to continue number patterns and explain the rule.","criteria":["I can continue and make repeating patterns with shapes and symbols.","I can describe patterns in tables and the hundred square.","I can continue a number sequence and say its rule."],"steps":{"start":"2, 4, 6, 8… what comes next? What is the rule?","teach":"Show sequences that add, subtract, double and halve. Find the rule and the next two numbers. Colour the 5 times table on a hundred square.","practise":"Number patterns.","check":"Continue 30, 27, 24… and say the rule."},"use":["m-patterns"],"home":"Make up a number pattern for someone at home to solve.","vocab":"pattern, sequence, rule, next, double, halve","understand":"What's the rule? What will the 10th number be?","lookFor":"States the rule in words and uses it to predict, without listing every number."},
    {"id":"lesson-first-equals-greater-than-and-missing-numbers","level":"First","subject":"Maths","strand":"Patterns and missing numbers","codes":["MTH 1-15a","MTH 1-15b"],"title":"Equals, greater than and missing numbers","intention":"We are learning to compare numbers and find missing numbers.","criteria":["I can use =, ≠, < and > correctly.","I know the equals sign means both sides balance.","I can find a missing number, as in □ + 17 = 30."],"steps":{"start":"Which is bigger, 45 or 54? Show it with < or >.","teach":"Use a balance picture: 8 + 2 = 5 + 5. Then □ + 6 = 15 and □ × 6 = 30, using number facts and the inverse.","practise":"Missing numbers and signs.","check":"Fill in 23 □ 32 and □ − 8 = 12."},"use":["m-equations"],"home":"Make balance puzzles with coins.","vocab":"equals, not equal to, less than, greater than, balance, missing","understand":"What does = mean in 7 + 3 = 6 + 4?","lookFor":"Explains both sides are worth the same, not \"the answer comes next\"."},
    {"id":"lesson-first-describing-2d-shapes-and-3d-objects","level":"First","subject":"Maths","strand":"Shape and angles","codes":["MTH 1-16a","MTH 1-16b"],"title":"Describing 2D shapes and 3D objects","intention":"We are learning to name and describe shapes and objects.","criteria":["I can name and sort 2D shapes and 3D objects in any size or way round.","I can use side, face, edge, vertex, base and angle.","I can find 2D shapes in 3D objects.","I can make a tiling pattern with two shapes."],"steps":{"start":"Show a triangle upside down: is it still a triangle?","teach":"Count faces, edges and vertices of a cube and a cylinder. Find the 2D faces of 3D objects. Tile with squares and triangles.","practise":"2D shapes, then 3D objects.","check":"How many faces, edges and vertices on a cuboid?"},"use":["m-shapes-2d","m-shapes-3d"],"home":"Find cuboids, cylinders and spheres in the kitchen.","vocab":"side, face, edge, vertex, base, angle, tiling","understand":"How is a cube different from a square?","lookFor":"Knows a cube is 3D with faces, edges and corners, and its faces are squares."},
    {"id":"lesson-first-turns-right-angles-and-compass-points","level":"First","subject":"Maths","strand":"Shape and angles","codes":["MTH 1-17a"],"title":"Turns, right angles and compass points","intention":"We are learning to describe turns and directions.","criteria":["I can describe full, half and quarter turns, clockwise and anticlockwise.","I know a right angle is 90°.","I can use North, South, East and West.","I can find right angles in shapes and around me."],"steps":{"start":"Stand up: make a quarter turn clockwise, then a half turn.","teach":"Make a right-angle checker by folding paper. Find right angles in the room. Mark N, S, E, W on the walls and give directions.","practise":"Angles and turns.","check":"Face North, turn a quarter turn clockwise: which way now?"},"use":["m-angles"],"home":"Give directions on a walk: turn left, quarter turn right.","vocab":"turn, clockwise, anticlockwise, right angle, North, South, East, West","understand":"If you face north and make a quarter turn clockwise, which way do you face?","lookFor":"Says east, and can show the turn with their body or a pointer."},
    {"id":"lesson-first-grid-references-and-symmetry","level":"First","subject":"Maths","strand":"Shape and angles","codes":["MTH 1-18a","MTH 1-19a"],"title":"Grid references and symmetry","intention":"We are learning to use grid references and to make symmetrical designs.","criteria":["I know where grid references are used.","I can find and give two-figure grid references.","I can find symmetry in pictures, nature and shapes.","I can make a design with more than one line of symmetry."],"steps":{"start":"Look at a simple map with a grid. Where is the park?","teach":"Draw a 5 × 5 grid with letters along and numbers up. Place items and name their squares (along the corridor, then up the stairs). Fold shapes to find lines of symmetry.","practise":"Play a grid hide-and-seek: hide treasure in a square and guess each other's.","check":"Which square is the tree in? Draw the other half of a symmetrical pattern."},"use":[],"home":"Look at a street map together and find places by their squares.","vocab":"grid, reference, along, up, symmetry, line of symmetry","understand":"Why does the order of a grid reference matter?","lookFor":"Explains B3 and 3B point to different places if the order is swapped: across first, then up."},
    {"id":"lesson-first-collecting-and-showing-data","level":"First","subject":"Maths","strand":"Data and chance","codes":["MNU 1-20a","MNU 1-20b","MTH 1-21a"],"title":"Collecting and showing data","intention":"We are learning to collect, sort and show data, and answer questions about it.","criteria":["I can answer questions using charts, bar graphs and tables.","I can collect data with a survey or tally.","I can show data in bar graphs, tables, Carroll diagrams and Venn diagrams.","I can give a graph a title, labels and a sensible scale."],"steps":{"start":"What is the favourite pet of people you know?","teach":"Collect answers with a tally. Draw a bar graph with a title, labelled axes and a scale going up in 2s. Sort numbers in a Venn diagram (even / more than 10).","practise":"Tally marks, then Bar charts.","check":"Ask three questions about a bar graph, including one about the difference between two bars."},"use":["n-tally","n-bar"],"home":"Do a family survey and make a chart.","vocab":"data, survey, tally, bar graph, table, axis, scale, Venn diagram, Carroll diagram","understand":"What question could someone answer from your chart?","lookFor":"Asks and answers a question the data really shows, such as which is most popular."},
    {"id":"lesson-first-how-likely-is-it","level":"First","subject":"Maths","strand":"Data and chance","codes":["MNU 1-22a"],"title":"How likely is it?","intention":"We are learning to describe how likely things are.","criteria":["I can use likely, unlikely, certain, uncertain, possible, impossible, fair and unfair.","I can use what I know to predict how likely something is."],"steps":{"start":"Will it snow tomorrow? Will the sun rise tomorrow?","teach":"Put events on a line from impossible to certain. Is a game with one red and five blue counters fair?","practise":"How likely is it?","check":"Give three events to place on the likelihood line, with reasons."},"use":["n-chance"],"home":"Talk about the weather forecast: how likely is rain?","vocab":"likely, unlikely, certain, possible, impossible, fair, unfair, chance","understand":"Is it impossible or just unlikely that it will snow tomorrow? Why?","lookFor":"Explains the difference: unlikely can still happen, impossible can't."},
    {"id":"lesson-first-numbers-in-life-work-and-history","level":"First","subject":"Maths","strand":"Number","codes":["MTH 1-12a"],"title":"Numbers in life, work and history","intention":"We are learning how numbers are used in the world and in the past.","criteria":["I can talk about how numbers are used in learning, life and work.","I can explore a number system from history, such as Roman numerals."],"steps":{"start":"Where did you see numbers today?","teach":"List jobs that use numbers. Show Roman numerals I to XX on clocks and old buildings. Write today's day number in Roman numerals.","practise":"Write five numbers in Roman numerals and five jobs that use maths.","check":"What is XIV? Name a job that uses measuring."},"use":[],"home":"Spot Roman numerals on clocks, films or buildings.","vocab":"number system, Roman numerals","understand":"Where have you seen numbers used today? What were they for?","lookFor":"Gives real examples and what the number told someone (time, price, a bus number)."},
    {"id":"lesson-second-rounding-large-numbers-and-decimals","level":"Second","subject":"Maths","strand":"Number","codes":["MNU 2-01a"],"title":"Rounding large numbers and decimals","intention":"We are learning to round to estimate and check calculations.","criteria":["I can round whole numbers to the nearest 1000, 10 000 and 100 000.","I can round decimals to the nearest whole number, 1 and 2 decimal places.","I can estimate an answer that suits the problem."],"steps":{"start":"Round 4 682 to the nearest 1000. How do you know?","teach":"Use number lines for large numbers and for decimals (3·46 → 3·5 → 3). Estimate 598 × 4 as 600 × 4. Talk about when to round up (buying enough paint).","practise":"Rounding to 100 and 1000, then Estimating answers.","check":"Round 56 349 to the nearest 10 000 and 7·286 to 2 decimal places."},"use":["n-round-100","n-estimate"],"home":"Estimate the shopping bill before you get to the till.","vocab":"round, nearest, estimate, decimal place, approximately","understand":"When is rounding useful, and when do you need the exact number?","lookFor":"Gives sensible examples: estimating a shopping total vs. paying the exact amount."},
    {"id":"lesson-second-place-value-to-a-million","level":"Second","subject":"Maths","strand":"Number","codes":["MNU 2-02a"],"title":"Place value to a million","intention":"We are learning to read, write and order numbers to 1 000 000.","criteria":["I can read, write and order whole numbers to 1 000 000.","I can explain what each digit is worth.","I can add and subtract multiples of 10, 100 and 1000."],"steps":{"start":"Read 305 061 aloud. What is the 5 worth?","teach":"Use a place value chart to a million. Partition 482 350. Order five large numbers. Add 3000 to 67 400.","practise":"Hundreds, tens and ones, then build bigger numbers on the chart.","check":"Write 'two hundred and six thousand and forty' in digits."},"use":["n-hundreds"],"home":"Read populations or prices of houses and cars.","vocab":"million, thousand, digit, value, place, partition","understand":"Is 300 000 bigger than 299 999? How can you tell without counting?","lookFor":"Compares from the biggest place value first."},
    {"id":"lesson-second-decimals-to-three-places","level":"Second","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MNU 2-02a","MNU 2-03b"],"title":"Decimals to three places","intention":"We are learning what each digit is worth in decimals.","criteria":["I can read, write and order decimals to three places.","I can explain the value of tenths, hundredths and thousandths.","I can partition decimals, as in 3·6 = 3 ones and 6 tenths = 36 tenths."],"steps":{"start":"Show 0·5 and ½ on a number line. Are they the same?","teach":"Extend the place value chart past the decimal point. Order 0·45, 0·405 and 0·5. Partition 3·6 in different ways.","practise":"Decimal fractions.","check":"Which is larger, 0·7 or 0·65? Why?"},"use":["n-decimals"],"home":"Compare prices and times in a race to the hundredth of a second.","vocab":"decimal point, tenths, hundredths, thousandths","understand":"Which is bigger, 0.4 or 0.35? Why?","lookFor":"Explains 0.4 is 4 tenths and 0.35 is 3 tenths and 5 hundredths, so 0.4 is bigger."},
    {"id":"lesson-second-adding-and-subtracting-large-numbers-and-decimals","level":"Second","subject":"Maths","strand":"Number","codes":["MNU 2-03a","MNU 2-03b"],"title":"Adding and subtracting large numbers and decimals","intention":"We are learning to add and subtract whole numbers and decimals.","criteria":["I can add and subtract whole numbers to 1 000 000.","I can add and subtract decimals to two places.","I can choose a mental or written method and explain it."],"steps":{"start":"What is 4·5 + 2·7? How did you do it?","teach":"Model a written method lining up place values, then with decimals (lining up the point). Compare with a mental method for 3 000 − 1 998.","practise":"Adding and taking away bigger numbers.","check":"Work out 24 587 + 6 345 and 12·5 − 3·75."},"use":["n-big-add"],"home":"Add up the receipt and check the total.","vocab":"add, subtract, method, decimal point, total, difference","understand":"Why do the decimal points need to line up?","lookFor":"Explains digits of the same value must be added together."},
    {"id":"lesson-second-multiplication-and-division-facts-and-10-100-1000","level":"Second","subject":"Maths","strand":"Number","codes":["MNU 2-03a"],"title":"Multiplication and division facts, and ×÷ 10, 100, 1000","intention":"We are learning to use all the times tables and to multiply and divide by 10, 100 and 1000.","criteria":["I can use multiplication and division facts to 10 × 10.","I can multiply and divide whole numbers and decimals by 10, 100 and 1000."],"steps":{"start":"Quick-fire 6, 7, 8 and 9 times tables.","teach":"Use known facts to work out others (7 × 8 = 7 × 4 doubled). Use a place value chart for 3·45 × 100 and 560 ÷ 1000.","practise":"6, 7, 8 and 9 times tables, Division facts, then Multiplying and dividing by 10 and 100.","check":"Ask 8 × 7, 63 ÷ 9 and 2·5 × 100."},"use":["n-tables-6-9","n-division","n-x10"],"home":"Practise one times table a day, out loud, for five minutes.","vocab":"multiply, divide, product, quotient, factor","understand":"What is 3.5 × 10? Why doesn't \"add a zero\" work here?","lookFor":"Says 35, explaining each digit becomes ten times bigger."},
    {"id":"lesson-second-multiplying-by-2-digits-and-dividing-with-decimal-answers","level":"Second","subject":"Maths","strand":"Number","codes":["MNU 2-03a","MNU 2-03b"],"title":"Multiplying by 2 digits and dividing with decimal answers","intention":"We are learning to multiply by two-digit numbers and divide by a single digit.","criteria":["I can multiply whole numbers by two-digit numbers.","I can multiply decimals by a single digit.","I can divide by a single digit, giving decimal answers, as in 43 ÷ 5 = 8·6."],"steps":{"start":"What is 23 × 10? And 23 × 2?","teach":"Model 23 × 12 as 23 × 10 + 23 × 2, then with a grid or written method. Show 43 ÷ 5 as 8 remainder 3, then 8·6.","practise":"Work through a set of 6 calculations on paper, checking with estimates.","check":"Work out 34 × 15 and 27 ÷ 4."},"use":["n-division"],"home":"Work out costs for several of the same item.","vocab":"multiply, product, divide, remainder, decimal","understand":"Estimate 38 × 21 first. Is your answer close?","lookFor":"Rounds to 40 × 20 = 800 and uses it to check."},
    {"id":"lesson-second-order-of-operations","level":"Second","subject":"Maths","strand":"Number","codes":["MTH 2-03c"],"title":"Order of operations","intention":"We are learning the order to do calculations in.","criteria":["I can apply the correct order of operations, including brackets, in multi-step calculations."],"steps":{"start":"Is 2 + 3 × 4 equal to 20 or 14?","teach":"Explain the order: brackets, then multiply and divide, then add and subtract. Work through examples with and without brackets.","practise":"Solve 8 calculations, then write two of your own with brackets that change the answer.","check":"Work out (6 + 2) × 3 and 6 + 2 × 3."},"use":[],"home":"Make up number puzzles with brackets for the family.","vocab":"brackets, order of operations, multiply, divide, add, subtract","understand":"Why does 2 + 3 × 4 not equal 20?","lookFor":"Explains multiplication is done before addition unless brackets say otherwise."},
    {"id":"lesson-second-negative-numbers","level":"Second","subject":"Maths","strand":"Number","codes":["MNU 2-04a"],"title":"Negative numbers","intention":"We are learning about numbers less than zero.","criteria":["I can say where negative numbers are used, such as temperatures.","I can order negative numbers and place them on a number line."],"steps":{"start":"What happens to the temperature at night in winter?","teach":"Draw a vertical number line like a thermometer from −10 to 10. Count back through zero. Order −3, 2, −7, 0. Find differences in temperature.","practise":"Negative numbers.","check":"Which is colder, −4°C or −1°C? What is 3 less than 1?"},"use":["n-negative"],"home":"Check the weather forecast for temperatures below zero.","vocab":"negative, minus, below zero, temperature, number line","understand":"Which is warmer, −2 °C or −7 °C? Why?","lookFor":"Uses a number line or thermometer: −2 is nearer zero, so warmer."},
    {"id":"lesson-second-multiples-factors-and-primes","level":"Second","subject":"Maths","strand":"Number","codes":["MTH 2-05a"],"title":"Multiples, factors and primes","intention":"We are learning to find multiples and factors.","criteria":["I can find multiples and factors of whole numbers.","I can use them to solve problems.","I can recognise prime numbers."],"steps":{"start":"List the first five multiples of 6.","teach":"Find all factors of 24 using arrays or factor pairs. Show a prime has only two factors. Use a common multiple to solve a problem (buses every 4 and 6 minutes).","practise":"Multiples, factors and primes.","check":"List the factors of 18. Is 21 prime?"},"use":["n-multiples"],"home":"Find the factors of the house number.","vocab":"multiple, factor, factor pair, prime, common multiple","understand":"Why is 9 not a prime number?","lookFor":"Explains 9 has a factor other than 1 and itself (3)."},
    {"id":"lesson-second-fractions-decimals-and-percentages-are-linked","level":"Second","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MNU 2-07b"],"title":"Fractions, decimals and percentages are linked","intention":"We are learning that fractions, decimals and percentages can show the same amount.","criteria":["I can show equivalent forms, as in ¾ = 0·75 = 75%.","I can choose the easiest form for a problem and explain why."],"steps":{"start":"What is ½ as a decimal? As a percentage?","teach":"Use a 100 square: shade 25 squares and write ¼, 0·25 and 25%. Build a table for ½, ¼, ¾, ⅒, ⅕.","practise":"Percentages, then Decimal fractions.","check":"Write 0·2 as a fraction and a percentage."},"use":["n-percent","n-decimals"],"home":"Spot percentages on food labels and sales signs.","vocab":"equivalent, fraction, decimal, percentage, per cent","understand":"Show me a half three different ways.","lookFor":"Writes 1/2, 0.5 and 50%, and explains they are the same amount."},
    {"id":"lesson-second-percentages-and-fractions-of-amounts","level":"Second","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MNU 2-07a"],"title":"Percentages and fractions of amounts","intention":"We are learning to find fractions and percentages of amounts.","criteria":["I can find simple fractions of a quantity, as in ⅗ of 60.","I can find simple percentages of a quantity and use them, as in a 15% discount."],"steps":{"start":"What is ½ of 80? 10% of 80?","teach":"Find ⅕ of 60 then ⅗ of 60. Find 10% and 5% of £40, then 15%. Work out a sale price.","practise":"Percentages, then Halves, quarters and thirds.","check":"A £30 game has 20% off. What is the sale price?"},"use":["n-percent","n-fractions"],"home":"Work out sale prices when shopping.","vocab":"fraction of, percentage of, discount, sale price","understand":"Is 25% of 80 the same as a quarter of 80? Why?","lookFor":"Yes: 25% and a quarter are the same proportion."},
    {"id":"lesson-second-equivalent-fractions-and-simplest-form","level":"Second","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MTH 2-07c"],"title":"Equivalent fractions and simplest form","intention":"We are learning to make equivalent fractions, simplify and order them.","criteria":["I can create equivalent fractions.","I can write a fraction in its simplest form.","I can put common fractions in order."],"steps":{"start":"Fold a strip: show ½ = 2/4 = 4/8.","teach":"Multiply or divide top and bottom by the same number. Simplify 12/16 using common factors. Order ⅔, ¾ and 5/8 using equivalent fractions.","practise":"Equivalent fractions.","check":"Simplify 15/20. Put ½, ⅖ and 3/4 in order."},"use":["n-equivalent"],"home":"Share a pizza: is 2/8 the same as 1/4?","vocab":"equivalent, simplest form, numerator, denominator, common factor","understand":"Why are 2/4 and 1/2 the same?","lookFor":"Draws or explains the same amount split into more parts."},
    {"id":"lesson-second-budgets-best-value-profit-and-loss","level":"Second","subject":"Maths","strand":"Money","codes":["MNU 2-09a","MNU 2-09b","MNU 2-09c"],"title":"Budgets, best value, profit and loss","intention":"We are learning to manage money, compare costs and work out profit and loss.","criteria":["I can do money calculations with all four operations.","I can compare costs and decide what I can afford in a budget.","I understand the benefits and risks of bank cards and paying digitally.","I can work out profit and loss."],"steps":{"start":"You have £20 for a party. What would you buy?","teach":"Compare two pack sizes to find the better value. Plan a budget with a list of prices. Sell 20 cakes at 50p that cost £6 to make: profit or loss? Talk about card payments and keeping PINs safe.","practise":"Counting money, then plan a £25 budget from a price list.","check":"Which is better value: 6 for £1·50 or 10 for £2·20?"},"use":["n-best-value","n-money"],"home":"Compare unit prices together when shopping.","vocab":"budget, afford, best value, profit, loss, bank card","understand":"Is the bigger pack always better value? How can you tell?","lookFor":"Compares the price per item or per gram, not just the total."},
    {"id":"lesson-second-12-and-24-hour-time-and-timetables","level":"Second","subject":"Maths","strand":"Time","codes":["MNU 2-10a"],"title":"12- and 24-hour time and timetables","intention":"We are learning to use 12- and 24-hour time and read timetables.","criteria":["I can read and write time in 12- and 24-hour notation and change between them.","I can use timetables and calendars to plan and solve problems."],"steps":{"start":"What is 3:45 pm in 24-hour time?","teach":"Show a 24-hour clock line from 00:00 to 23:59. Convert times both ways. Read a bus or train timetable: which bus gets there by 14:30?","practise":"12-hour and 24-hour time.","check":"Write 18:20 in 12-hour time. Which train arrives first?"},"use":["n-time-24"],"home":"Plan a trip using a real bus or train timetable.","vocab":"24-hour, am, pm, timetable, depart, arrive","understand":"What time is 15:45 on a 12-hour clock? How did you work it out?","lookFor":"Takes 12 off the hours: quarter to four in the afternoon."},
    {"id":"lesson-second-durations-units-of-time-speed-and-distance","level":"Second","subject":"Maths","strand":"Time","codes":["MNU 2-10a","MNU 2-10b","MNU 2-10c"],"title":"Durations, units of time, speed and distance","intention":"We are learning to work out durations and how long journeys take.","criteria":["I can convert units of time, as in 1¾ hours = 105 minutes.","I can work out durations across hours, in 12- and 24-hour time.","I can choose the right timer and unit, including hundredths of a second.","I can estimate journey times using speed, distance and time."],"steps":{"start":"How many minutes in 2½ hours?","teach":"Use a time line to find 10:45 to 13:20. Convert hours and minutes. If a car goes 50 km in an hour, how long for 150 km?","practise":"How long? Time intervals.","check":"A film starts at 18:50 and lasts 1 hour 45 minutes. When does it end?"},"use":["n-durations"],"home":"Time a journey and work out how long it took.","vocab":"duration, hours, minutes, speed, distance, time","understand":"Why can't you subtract 10:50 from 11:20 like ordinary numbers?","lookFor":"Explains there are 60 minutes in an hour, so counts on through the hour."},
    {"id":"lesson-second-estimate-measure-and-convert-metric-units","level":"Second","subject":"Maths","strand":"Measurement","codes":["MNU 2-11a","MNU 2-11b"],"title":"Estimate, measure and convert metric units","intention":"We are learning to estimate, measure accurately and convert units.","criteria":["I can estimate using familiar objects.","I can measure length, mass and capacity in the right units.","I can convert between units using decimals, as in 550 cm = 5·5 m.","I can read a range of scales accurately."],"steps":{"start":"Estimate the height of the door in metres.","teach":"Measure to the nearest mm. Convert km–m–cm–mm, kg–g and l–ml using the place value chart. Read scales with different steps.","practise":"Changing units, then Measuring: rulers, jugs and units.","check":"Convert 3·009 kg to grams and 2 400 m to km."},"use":["n-units","n-measure"],"home":"Read food labels: how many grams? Convert to kilograms.","vocab":"millimetre, centimetre, metre, kilometre, gram, kilogram, millilitre, litre, convert","understand":"How many millimetres in 4.5 cm? How do you know?","lookFor":"Says 45 and explains there are 10 mm in each centimetre."},
    {"id":"lesson-second-perimeter-area-and-volume","level":"Second","subject":"Maths","strand":"Measurement","codes":["MNU 2-11b","MNU 2-11c"],"title":"Perimeter, area and volume","intention":"We are learning to calculate perimeter, area and volume.","criteria":["I can calculate the perimeter of straight-sided shapes.","I can calculate the area of squares, rectangles and right-angled triangles.","I can calculate the volume of cubes and cuboids.","I can draw shapes with a given perimeter or area."],"steps":{"start":"How could you find the distance round the table?","teach":"Find perimeter by adding sides. Find area of a rectangle as length × breadth, and a right-angled triangle as half of that. Build a cuboid with cubes to show length × breadth × height.","practise":"Area and perimeter.","check":"A rectangle is 7 cm by 4 cm: find its perimeter and area."},"use":["n-area"],"home":"Measure a room and work out the area of carpet needed.","vocab":"perimeter, area, volume, square centimetre, cubic centimetre, length, breadth, height","understand":"Can two rectangles have the same perimeter but a different area?","lookFor":"Yes, with an example: 1 × 5 and 2 × 4 both have a perimeter of 12 but areas of 5 and 8."},
    {"id":"lesson-second-square-triangular-and-fibonacci-numbers","level":"Second","subject":"Maths","strand":"Patterns and missing numbers","codes":["MTH 2-13a"],"title":"Square, triangular and Fibonacci numbers","intention":"We are learning to explain and use the rules for famous number sequences.","criteria":["I can extend square, triangular and Fibonacci sequences and explain the rule.","I can use multiples, square and triangular numbers to make patterns."],"steps":{"start":"Build squares with counters: 1, 4, 9… what comes next?","teach":"Build square and triangular numbers with counters. Show Fibonacci (each number is the sum of the two before). Find the rule for sequences like 3, 7, 11, 15.","practise":"Number patterns.","check":"Give the next two numbers of 1, 3, 6, 10 and of 1, 1, 2, 3, 5, with the rule."},"use":["m-patterns"],"home":"Look for Fibonacci spirals in pinecones and flowers.","vocab":"sequence, rule, square number, triangular number, Fibonacci","understand":"Why are they called square numbers?","lookFor":"Shows the number as a square array of dots."},
    {"id":"lesson-second-solving-simple-equations","level":"Second","subject":"Maths","strand":"Patterns and missing numbers","codes":["MTH 2-15a"],"title":"Solving simple equations","intention":"We are learning to find an unknown value shown by a letter or symbol.","criteria":["I can solve simple equations with one unknown, as in a − 30 = 40 and 4b = 20."],"steps":{"start":"I'm thinking of a number. I add 8 and get 20. What's my number?","teach":"Use a balance: what you do to one side you do to the other. Solve a + 15 = 40, b − 30 = 40, 4c = 20 using inverse operations.","practise":"Missing numbers and signs.","check":"Solve 3n = 27 and x − 12 = 19."},"use":["m-equations"],"home":"Play 'think of a number' puzzles.","vocab":"equation, unknown, solve, inverse, balance","understand":"In 3n + 2 = 14, how do you find n? How can you check?","lookFor":"Undoes the steps in reverse, then puts the value back in to check."},
    {"id":"lesson-second-shape-properties-nets-and-circles","level":"Second","subject":"Maths","strand":"Shape and angles","codes":["MTH 2-16a","MTH 2-16b","MTH 2-16c"],"title":"Shape properties, nets and circles","intention":"We are learning to describe shapes precisely and link 3D objects to their nets.","criteria":["I can use regular, irregular, diagonal, radius, diameter and circumference.","I know the radius is half the diameter.","I can match 3D objects to their nets.","I can draw 2D shapes and represent 3D objects."],"steps":{"start":"Is a square a regular shape? Why?","teach":"Compare regular and irregular shapes. Measure the radius and diameter of a circle. Unfold a cereal box to see its net, and draw a net for a cube.","practise":"3D objects, then draw two different nets for a cube.","check":"A circle's diameter is 12 cm: what is its radius? Which net makes a cube?"},"use":["m-shapes-3d"],"home":"Unfold boxes at home to see their nets.","vocab":"regular, irregular, diagonal, radius, diameter, circumference, net","understand":"Will this net fold into a cube? How do you know?","lookFor":"Imagines or tests the folding and spots faces that would overlap."},
    {"id":"lesson-second-classifying-and-measuring-angles","level":"Second","subject":"Maths","strand":"Shape and angles","codes":["MTH 2-17a","MTH 2-17b"],"title":"Classifying and measuring angles","intention":"We are learning to name, measure and calculate angles.","criteria":["I can classify angles as acute, right, obtuse, straight and reflex.","I can measure and draw angles to within 2°.","I know complementary angles make 90° and supplementary angles make 180°, and can find missing angles."],"steps":{"start":"Find an acute and an obtuse angle in the room.","teach":"Classify angles. Show how to use a protractor (zero line, which scale). Find a missing angle on a straight line.","practise":"Angles and turns, then measure and draw five angles.","check":"Measure an angle. Two angles on a straight line: one is 115°, what is the other?"},"use":["m-angles"],"home":"Spot angles in roofs, scissors and clock hands.","vocab":"acute, obtuse, reflex, straight, protractor, degree, complementary, supplementary","understand":"Without measuring, is this angle more or less than 90°?","lookFor":"Compares to a right angle first, then measures to check."},
    {"id":"lesson-second-compass-points-scale-and-coordinates","level":"Second","subject":"Maths","strand":"Shape and angles","codes":["MTH 2-17c","MTH 2-17d","MTH 2-18a"],"title":"Compass points, scale and coordinates","intention":"We are learning to use eight compass points, maps with scales and coordinates.","criteria":["I can use the eight compass points and their angles.","I can read maps and plans with simple scales, as in 1 cm : 2 km.","I can plot and describe points with coordinates in the first quadrant."],"steps":{"start":"Which direction is halfway between North and East?","teach":"Draw the eight compass points with angles between them. Measure on a map and use the scale. Plot (3, 5) and (5, 3) — along first, then up.","practise":"Angles and turns, then plot a shape from coordinates.","check":"On a 1 cm : 2 km map, 4·5 cm is how far? Plot (2, 6)."},"use":["m-angles"],"home":"Use a map on a walk and work out real distances.","vocab":"North-East, South-West, scale, coordinates, axis, plot","understand":"On a scale of 1 cm to 2 km, how far is 3.5 cm?","lookFor":"Multiplies by the scale: 7 km, and explains why."},
    {"id":"lesson-second-lines-of-symmetry","level":"Second","subject":"Maths","strand":"Shape and angles","codes":["MTH 2-19a"],"title":"Lines of symmetry","intention":"We are learning to find lines of symmetry and complete symmetrical patterns.","criteria":["I can draw lines of symmetry on 2D shapes.","I can complete symmetrical pictures and patterns."],"steps":{"start":"How many lines of symmetry does a square have?","teach":"Fold and use mirrors to find lines of symmetry in regular and irregular shapes. Complete patterns on squared paper across vertical, horizontal and diagonal lines.","practise":"Complete three symmetrical patterns on squared paper.","check":"Draw the lines of symmetry on a rectangle and a regular hexagon."},"use":[],"home":"Look for symmetry in flags, logos and leaves.","vocab":"symmetry, line of symmetry, reflect, mirror line","understand":"Does a rectangle have a diagonal line of symmetry? Prove it.","lookFor":"Folds or reflects to show the halves don't match, so no."},
    {"id":"lesson-second-graphs-pie-charts-and-reliable-data","level":"Second","subject":"Maths","strand":"Data and chance","codes":["MNU 2-20a","MNU 2-20b","MTH 2-21a"],"title":"Graphs, pie charts and reliable data","intention":"We are learning to collect, display and interpret data, and judge if it's reliable.","criteria":["I can collect data in a suitable way.","I can display data in tables, bar graphs, line graphs, frequency tables and simple pie charts, with a suitable scale.","I can draw conclusions from data.","I can judge how reliable data is, thinking about who made it and the sample size."],"steps":{"start":"Is a survey of 3 people enough to know the favourite food of a whole school?","teach":"Make a frequency table, then a bar graph and a line graph for change over time. Read a simple pie chart. Spot a misleading graph scale.","practise":"Reading tables, then Bar charts.","check":"Read values from a line graph and explain one conclusion."},"use":["n-table","n-bar"],"home":"Look at a graph in the news: is it fair or misleading?","vocab":"frequency table, line graph, pie chart, scale, reliable, sample","understand":"Could this data be misleading? Why?","lookFor":"Looks at the sample size, who collected it and the scale."},
    {"id":"lesson-second-probability-and-chance-experiments","level":"Second","subject":"Maths","strand":"Data and chance","codes":["MNU 2-22a"],"title":"Probability and chance experiments","intention":"We are learning to describe probability and test it with experiments.","criteria":["I can describe likelihood with equal chance, fifty-fifty, one in two, percentages and fractions like ⅙.","I can plan and carry out experiments with repeated trials.","I can use data to predict outcomes."],"steps":{"start":"What is the chance of rolling a 6? Of an even number?","teach":"Predict how many 6s in 30 rolls, then test it. Record results in a tally. Compare with the prediction and talk about why they differ.","practise":"How likely is it?","check":"A bag has 3 red and 1 blue counter. What is the chance of blue, as a fraction and a percentage?"},"use":["n-chance"],"home":"Flip a coin 20 times and record heads and tails.","vocab":"probability, chance, fifty-fifty, one in, likely, outcome, trial","understand":"You flipped 4 heads in a row. Is tails more likely next? Why?","lookFor":"Knows each flip is still an even chance: what happened before doesn't change it."},
    {"id":"lesson-second-maths-in-inventions-life-and-work","level":"Second","subject":"Maths","strand":"Number","codes":["MTH 2-12a"],"title":"Maths in inventions, life and work","intention":"We are learning how maths shapes the world, now and in the past.","criteria":["I can find and present examples of how maths is used in life and work.","I can discuss the part maths played in important inventions."],"steps":{"start":"Which jobs need maths? Which inventions needed it?","teach":"Choose an invention (bridges, computers, GPS) and find the maths it needs. Plan a short presentation.","practise":"Make a fact poster or slide about one example.","check":"Explain one way maths is used in a job you'd like."},"use":[],"home":"Ask family members how they use maths at work or at home.","vocab":"invention, engineer, data, measurement","understand":"What maths would someone use in this job? Give an example.","lookFor":"Names the maths (measuring, angles, money, data) and a real task it's used for."},
    {"id":"lesson-third-rounding-to-decimal-places-and-estimating","level":"Third","subject":"Maths","strand":"Number","codes":["MNU 3-01a"],"title":"Rounding to decimal places and estimating","intention":"We are learning to round to a sensible degree of accuracy and to estimate answers.","criteria":["I can round decimal fractions to three decimal places.","I can choose how accurately to round, thinking about the problem.","I can round to estimate the answer to a calculation, then use the estimate to check."],"steps":{"start":"Round 4·276 to the nearest whole number, then to one decimal place.","teach":"Zoom in on a number line between 4·27 and 4·28 to show why 4·276 rounds to 4·28. Round 3·14159 to 1, 2 and 3 decimal places. Talk about context: money to 2 places, a shelf to the nearest centimetre, buses for 130 people always rounded up. Estimate 38·7 × 5·2 as 40 × 5 = 200 before calculating.","practise":"Rounding to 100 and 1000, then Estimating answers, then the \"Round it sensibly\" sheet.","check":"Round 7·0459 to 2 decimal places. Estimate 61·8 ÷ 2·9: how does the estimate tell you a calculator answer is sensible?"},"use":["n-round-100","n-estimate"],"home":"Estimate the shopping bill before you reach the till, then compare.","vocab":"round, decimal place, degree of accuracy, estimate, approximately","understand":"Why would you round 2·3 buses up to 3, but £2·346 to £2·35?","lookFor":"Explains that the context decides: you can't have part of a bus, and money is counted to the penny."},
    {"id":"lesson-third-calculating-with-whole-numbers-and-decimals","level":"Third","subject":"Maths","strand":"Number","codes":["MNU 3-03a","MNU 3-03b"],"title":"Calculating with whole numbers and decimals","intention":"We are learning to recall facts quickly, choose a method, calculate accurately with decimals and explain our working.","criteria":["I can recall multiplication and division facts quickly, and use facts to the 12 times table.","I can add and subtract whole numbers and decimals to three decimal places.","I can multiply and divide whole numbers and decimals to three decimal places.","I can explain my method and my answer clearly."],"steps":{"start":"Quick fire: 7 × 8, 72 ÷ 9, 11 × 12, 144 ÷ 12.","teach":"Line up the decimal points for 12·45 + 3·078 and 20 − 6·375, filling gaps with zeros. Multiply 4·26 × 7 by working out 426 × 7, then placing the point by estimating. Divide 9·36 ÷ 4 by short division. Ask the pupil to say each step aloud, then write a one-line explanation of the method.","practise":"6, 7, 8 and 9 times tables and Division facts for speed, then the \"Decimal calculations\" sheet.","check":"Work out 15·8 − 7·256 and 3·45 × 6. How did you check each answer?"},"use":["n-tables-6-9","n-division","n-big-add"],"home":"Split a bill, or work out the cost of several items with prices in pounds and pence.","vocab":"decimal point, place value, method, estimate, inverse, check","understand":"When you work out 4·26 × 7 as 426 × 7, how do you know where the point goes?","lookFor":"Uses an estimate (about 4 × 7 = 28) or explains that 4·26 is 426 hundredths, so the answer is hundredths too."},
    {"id":"lesson-third-negative-numbers-in-calculations","level":"Third","subject":"Maths","strand":"Number","codes":["MNU 3-04a"],"title":"Negative numbers in calculations","intention":"We are learning to add, subtract, multiply and divide with negative numbers, and use them to solve problems.","criteria":["I can add and subtract with integers, as in −3 + 8 and 4 − 9.","I can multiply and divide with integers, as in −4 × 3 and −12 ÷ −4.","I can use negative numbers to solve problems about temperature, money or height."],"steps":{"start":"The temperature is −2°C and falls 5 degrees. What is it now?","teach":"Use a vertical number line, like a thermometer, for adding and subtracting. Show subtracting a negative as finding the gap: 3 − (−2) is the distance from −2 up to 3, which is 5. Find the multiplying rules from a pattern: 3 × −2 = −6, 2 × −2 = −4, 1 × −2 = −2, 0 × −2 = 0, so −1 × −2 = 2. Link division to the multiplication facts.","practise":"Negative numbers, then the \"Below zero\" sheet.","check":"Work out −6 − 4, 5 − (−3) and −20 ÷ 5. A diver is 12 m below the surface and rises 7 m: where are they now?"},"use":["n-negative"],"home":"Look up temperatures in cold places around the world and find the differences.","vocab":"integer, negative, positive, below zero, difference, number line","understand":"Why is 5 − (−3) bigger than 5?","lookFor":"Explains that taking away a negative is finding the gap from −3 up to 5, or that removing a debt leaves you better off."},
    {"id":"lesson-third-common-multiples-common-factors-and-primes","level":"Third","subject":"Maths","strand":"Number","codes":["MTH 3-05a","MTH 3-05b"],"title":"Common multiples, common factors and primes","intention":"We are learning to find common multiples and factors, identify primes, and use them to solve problems.","criteria":["I can find common multiples, including the lowest common multiple, and explain my method.","I can find common factors, including the highest common factor, and explain my method.","I can identify prime numbers to 100 and explain how I know.","I can write a number as a product of its prime factors.","I can solve problems using multiples and factors."],"steps":{"start":"Is 51 prime? Convince me.","teach":"List multiples of 6 and 8 to find the lowest common multiple (24), and factor pairs of 36 and 48 to find the highest common factor (12). Draw a factor tree for 60 to write it as 2 × 2 × 3 × 5. Sieve a 100 square for primes. Solve: buses every 12 and 18 minutes leave together at 9:00. When do they next leave together?","practise":"Multiples, factors and primes, then the \"Factor trees and primes\" sheet.","check":"Find the highest common factor and lowest common multiple of 18 and 24. Write 84 as a product of primes."},"use":["n-multiples"],"home":"Find the prime dates on this month's calendar.","vocab":"multiple, factor, common, lowest common multiple, highest common factor, prime, prime factor, factor tree","understand":"Is 1 a prime number? Why or why not?","lookFor":"Explains that a prime has exactly two different factors, and 1 has only one."},
    {"id":"lesson-third-powers-and-indices","level":"Third","subject":"Maths","strand":"Number","codes":["MTH 3-06a"],"title":"Powers and indices","intention":"We are learning what powers mean, and to work them out mentally or with a calculator.","criteria":["I can explain index notation and use the words index, exponent, power and base.","I can evaluate whole number powers, as in 2⁴ = 16.","I can write whole numbers as powers, as in 27 = 3³."],"steps":{"start":"Fold a sheet of paper in half, again and again. How many layers after 1, 2, 3 and 4 folds?","teach":"Record the folds as 2, 2 × 2, 2 × 2 × 2 and write 2³: the base is 2 and the index (or exponent) is 3. Contrast 3² = 9 with 3 × 2 = 6. Work out powers mentally, then with a calculator's power key. Write 64 as 8², 4³ and 2⁶. Talk about why powers are useful: they're short, and show fast growth and very big numbers.","practise":"The \"Powers\" sheet, then check the answers with a calculator.","check":"Work out 5³ and 10⁴. Write 81 as a power of 3, and as a power of 9."},"use":[],"home":"Work out how many great-great-grandparents you have, using powers of 2.","vocab":"power, index, exponent, base, squared, cubed","understand":"Why is 3² not the same as 3 × 2?","lookFor":"Explains that the index says how many times the base is multiplied by itself: 3 × 3 = 9."},
    {"id":"lesson-third-fractions-decimals-and-percentages-in-real-life","level":"Third","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MNU 3-07a","MTH 3-07c"],"title":"Fractions, decimals and percentages in real life","intention":"We are learning to convert between fractions, decimals and percentages, and use them to make choices.","criteria":["I can convert fractions, decimal fractions and percentages into each other.","I can convert between whole or mixed numbers, improper fractions and decimal fractions.","I can calculate with fractions, decimals and percentages, with and without a calculator.","I can use my answers to compare and make informed choices."],"steps":{"start":"Which is bigger: ⅜, 0·4 or 35%?","teach":"Divide to turn ⅜ into 0·375 and 37·5%. Change 2¾ into 11/4 and 2·75 with a bar model. Find 17·5% of £240 by building it from 10%, 5% and 2·5%, then by calculator (0·175 × 240). Compare two offers on a £45 jacket: ⅓ off, or 30% off?","practise":"Percentages and Equivalent fractions, then the \"Which deal?\" sheet.","check":"Write 7/8 as a decimal and as a percentage. Which is better: 25% off £60, or £14 off?"},"use":["n-percent","n-equivalent","en-fractions-y6"],"home":"Compare discounts on a shopping website or in a shop window.","vocab":"equivalent, convert, mixed number, improper fraction, decimal fraction, percentage, discount","understand":"Why is ⅓ off a better deal than 30% off?","lookFor":"Explains that ⅓ is about 33%, so it takes off more, whatever the price."},
    {"id":"lesson-third-adding-and-subtracting-fractions","level":"Third","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MTH 3-07b"],"title":"Adding and subtracting fractions","intention":"We are learning to add and subtract fractions with different denominators.","criteria":["I can use equivalent fractions and common multiples to find a common denominator.","I can add and subtract whole numbers and fractions, including when I need to change a denominator.","I can simplify my answer, and change an improper fraction to a mixed number."],"steps":{"start":"Shade ⅓ and ¼ of the same bar. Why can't we just add the tops and the bottoms?","teach":"Use the lowest common multiple of 3 and 4 to rename both: 4/12 + 3/12 = 7/12. Work through ⅚ − ¼, then 2½ + 1⅔ (whole numbers first, then the fractions). Simplify, and change improper answers into mixed numbers.","practise":"Mixed numbers and calculating with fractions, then the \"Fraction sums\" sheet.","check":"Work out ⅖ + ⅓ and 3¼ − 1⅔."},"use":["en-fractions-y5","n-equivalent"],"home":"Follow a recipe with fractions of a cup or spoon, and add up the total.","vocab":"denominator, numerator, common denominator, lowest common multiple, equivalent, simplify, mixed number","understand":"Why can't you add ⅓ and ¼ to get 2/7?","lookFor":"Explains that the parts are different sizes, so they must be changed into the same size (twelfths) before adding."},
    {"id":"lesson-third-proportion-and-ratio","level":"Third","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MNU 3-08a"],"title":"Proportion and ratio","intention":"We are learning to increase and decrease quantities in proportion, and to use ratio.","criteria":["I can solve problems where related quantities increase or decrease in proportion.","I can write quantities as a ratio and simplify it.","I can use proportion and ratio in everyday problems, such as recipes and prices."],"steps":{"start":"A recipe for 4 people uses 300 g of pasta. How much for 6 people?","teach":"Use the unitary method (find one, then many) and a ratio table for the recipe. Write the ratio of 6 teachers to 60 children as 6 : 60 = 1 : 10, and of teachers to everyone in the school as 6 : 66 = 1 : 11. Share £45 in the ratio 2 : 3 by counting parts. Talk about when things are not in proportion, such as a taxi with a fixed charge.","practise":"Ratio and proportion, then the \"Recipe for a crowd\" sheet.","check":"5 pens cost £3·60. What do 8 cost? Simplify 18 : 24."},"use":["en-ratio"],"home":"Scale a family recipe up or down for a different number of people.","vocab":"ratio, proportion, simplify, unitary method, scale up, scale down, share","understand":"If teachers to children is 1 : 10, why aren't teachers 1/10 of the school?","lookFor":"Explains there are 11 parts altogether, so teachers are 1/11 of everyone."},
    {"id":"lesson-third-best-value-budgets-and-money-words","level":"Third","subject":"Maths","strand":"Money","codes":["MNU 3-09a","MNU 3-09b"],"title":"Best value, budgets and money words","intention":"We are learning to compare deals, plan a budget, and understand financial words.","criteria":["I can compare products, contracts and services to find the best value for me, and justify my choice.","I can make a budget, using technology where it helps, and plan for future costs.","I know financial words such as debit, credit, APR, per annum, direct debit, standing order and interest rate.","I can convert between currencies."],"steps":{"start":"Phone A: £12 a month for 24 months. Phone B: £180 now, then £5 a month for 24 months. Which costs less overall?","teach":"Work out the total cost of each deal over the contract, then discuss what else matters: data, how long you're tied in, paying up front. Build a monthly budget in a spreadsheet or table with income, fixed costs and saving for a future cost. Explain each financial word with an everyday example. Convert £150 to euros at a given rate, then back.","practise":"Best value, budgets, profit and loss, then the \"Plan a budget\" sheet.","check":"Explain the difference between a direct debit and a standing order. At €1·16 to £1, how many euros do you get for £250?"},"use":["n-best-value"],"home":"Compare two phone or streaming deals at home and work out the yearly cost of each.","vocab":"budget, income, expense, contract, APR, interest, per annum, debit, credit, direct debit, standing order, exchange rate","understand":"Is the cheapest deal always the best value? Why?","lookFor":"Explains that best value depends on what you need: total cost, length of contract, what's included, and your own situation."},
    {"id":"lesson-third-speed-distance-and-time","level":"Third","subject":"Maths","strand":"Time","codes":["MNU 3-10a"],"title":"Speed, distance and time","intention":"We are learning to use the link between speed, distance and time, and to work out durations.","criteria":["I can use the link between speed, distance and time to find any one of them.","I can calculate durations across hours and days.","I can work out how long a journey will take, how far it is, or the average speed."],"steps":{"start":"A car travels 60 miles in one hour. How far does it go in 2½ hours?","teach":"Show where distance = speed × time comes from (60 mph means 60 miles every hour), then rearrange it to find speed and time. Work in hours: 45 minutes = 0·75 hours. Find the time for 150 km at 60 km/h. Work out durations across midnight and across days on a timeline, such as 22:40 on Monday to 06:15 on Tuesday.","practise":"12-hour and 24-hour time, then the \"Journey planner\" sheet.","check":"A cyclist rides 36 km in 1 hour 30 minutes. What is their average speed? How long is it from 21:50 on Friday to 07:20 on Saturday?"},"use":["n-time-24","n-durations"],"home":"Plan a real journey with a timetable or map: distance, time and average speed.","vocab":"speed, distance, time, average speed, km/h, mph, duration","understand":"Why can't you write 1 hour 30 minutes as 1·3 hours in a speed calculation?","lookFor":"Explains that 30 minutes is half an hour, so it's 1·5 hours: minutes are sixtieths, not tenths."},
    {"id":"lesson-third-area-and-volume-including-compound-shapes","level":"Third","subject":"Maths","strand":"Measurement","codes":["MNU 3-11a","MTH 3-11b"],"title":"Area and volume, including compound shapes","intention":"We are learning to choose units, convert them, and find the area and volume of compound shapes.","criteria":["I can choose sensible units for length, area and volume.","I can convert between units, as in 2·5 m = 250 cm and 1500 ml = 1·5 litres, and use them in calculations.","I can find an area when the measurements are in different units.","I can find the area of compound 2D shapes made from squares, rectangles and triangles.","I can find the volume of compound 3D objects made from cubes and cuboids."],"steps":{"start":"Which unit would you use for the area of a stamp, a classroom, and a farm?","teach":"Split an L-shape into two rectangles in two different ways, and check both give the same area. Add a triangle (½ × base × height). Convert first when lengths are in metres and centimetres. Build a compound solid from cubes and find its volume by splitting it into cuboids (length × breadth × height). Link 1 cm³ to 1 ml.","practise":"Area and perimeter and Changing units, then the \"Floor plans and boxes\" sheet.","check":"Find the area of an L-shape and the volume of a step made from two cuboids. Which units did you use, and why?"},"use":["n-area","n-units","en-area-formulae"],"home":"Measure a room and work out how much flooring it would need.","vocab":"area, volume, compound, cm², m², cm³, litre, length, breadth, height, formula","understand":"You split the L-shape a different way from me. Will we get the same area? Why?","lookFor":"Explains that the area of the whole shape doesn't change however you split it, as long as no part is counted twice or missed."},
    {"id":"lesson-third-researching-a-mathematician-or-a-maths-topic","level":"Third","subject":"Maths","strand":"Number","codes":["MTH 3-12a"],"title":"Researching a mathematician or a maths topic","intention":"We are learning to research a mathematician or a maths topic, and present its impact on the world.","criteria":["I can research a famous mathematician or a maths topic, using reliable sources.","I can explain the maths using the right words and notation.","I can explain the difference it has made to society.","I can prepare and give a short presentation."],"steps":{"start":"What do GPS, music streaming and weather forecasts have in common? (They all depend on maths.)","teach":"Agree a choice, such as Mary Somerville, John Napier, Ada Lovelace, Katherine Johnson or al-Khwarizmi, or a topic such as codes or logarithms. Model making notes from two sources and checking they agree. Plan a three-minute talk: who or what, the maths itself with one worked example, and its impact today. Rehearse with the tutor as the audience.","practise":"The \"Maths that changed the world\" sheet: notes, one worked example and a plan for the talk.","check":"Give the talk. Ask: what was the maths, and why does it still matter?"},"use":[],"home":"Give the talk to someone at home and ask them one thing they learned.","vocab":"research, source, notation, impact, presentation","understand":"How do you know your information about this mathematician is accurate?","lookFor":"Checked more than one source, chose reliable ones, and can say where each fact came from."},
    {"id":"lesson-third-sequences-and-their-rules","level":"Third","subject":"Maths","strand":"Patterns and missing numbers","codes":["MTH 3-13a"],"title":"Sequences and their rules","intention":"We are learning to make sequences from rules, and to find and write the rule for a sequence.","criteria":["I can generate a sequence from a rule, as in T = 4n + 6.","I can extend a pattern and describe its rule.","I can write a sequence rule in algebra, as in C = 0·05m + 75."],"steps":{"start":"Squares made from matchsticks in a row use 4, 7, 10 … matches. How many for 10 squares?","teach":"Make the pattern, record it in a table of n and T, and spot the difference (+3). Show the rule T = 3n + 1 and why the +1 is needed. Generate terms from T = 4n + 6. Write a car-hire rule (£75 plus 5p a mile) as C = 0·05m + 75 and use it.","practise":"Number patterns, then the \"Find the rule\" sheet.","check":"Find the rule for 5, 9, 13, 17 … and use it to find the 20th term."},"use":["m-patterns"],"home":"Find a pattern at home (stairs, tiles, fence posts) and write its rule.","vocab":"sequence, term, rule, nth term, difference, formula","understand":"In T = 3n + 1, why is the number in front of n the same as the difference between terms?","lookFor":"Explains that each time n goes up by 1, 3n goes up by 3, so the terms go up by 3."},
    {"id":"lesson-third-simplifying-and-evaluating-expressions","level":"Third","subject":"Maths","strand":"Patterns and missing numbers","codes":["MTH 3-14a"],"title":"Simplifying and evaluating expressions","intention":"We are learning to collect like terms, and to evaluate expressions by substituting.","criteria":["I can collect like terms, including squared terms, to simplify an expression.","I can evaluate an expression with two variables, using positive and negative numbers."],"steps":{"start":"3 apples + 2 bananas + 4 apples. How could you write that more simply?","teach":"Simplify 3a + 2b + 4a = 7a + 2b, then 5x² + 3x − 2x² + x = 3x² + 4x, stressing that x and x² are unlike terms. Substitute a = 3 and b = −2 into 4a − 3b and a² + 2b, writing each step with brackets.","practise":"The \"Simplify and substitute\" sheet.","check":"Simplify 6p − 2q + p + 5q. Find 2x² − y when x = −3 and y = 4."},"use":[],"home":"Write an expression for a family shop (a apples, b loaves) and work it out with real prices.","vocab":"term, like terms, expression, simplify, variable, substitute, evaluate","understand":"Why can't 3x² + 4x be simplified to 7x³?","lookFor":"Explains that x² and x are unlike terms, as different as apples and bananas, so they can't be collected."},
    {"id":"lesson-third-solving-equations-and-using-formulae","level":"Third","subject":"Maths","strand":"Patterns and missing numbers","codes":["MTH 3-15a","MTH 3-15b"],"title":"Solving equations and using formulae","intention":"We are learning to write and solve equations, and to create and use formulae.","criteria":["I can solve linear equations, as in 3x + 5 = 26 and 4x − 7 = −15.","I can write an equation for a problem and solve it.","I can create a simple formula from a diagram, problem or statement.","I can evaluate a formula, as in C = 0·05m + 75."],"steps":{"start":"I think of a number, multiply it by 3 and add 5. I get 26. What was my number?","teach":"Use a balance: whatever you do to one side, do to the other. Solve 3x + 5 = 26, then 4x − 7 = −15. Turn a word problem into an equation: a rectangle's perimeter is 30 cm and its length is twice its width. Write a formula for a taxi fare of £3 plus £1·20 a mile, then use it.","practise":"Missing numbers and signs, then the \"Equations and formulae\" sheet.","check":"Solve 5y − 9 = 16. Write a formula for the number of legs on c chairs (4 legs) and t stools (3 legs)."},"use":["m-equations","en-area-formulae"],"home":"Write a formula for a phone plan or taxi fare and check it against a real price.","vocab":"equation, solve, balance, inverse, formula, variable, substitute","understand":"Why do you take away 5 before dividing by 3 when solving 3x + 5 = 26?","lookFor":"Explains that you undo the steps in reverse order: the number was multiplied by 3 first, then 5 was added."},
    {"id":"lesson-third-drawing-shapes-accurately","level":"Third","subject":"Maths","strand":"Shape and angles","codes":["MTH 3-16a"],"title":"Drawing shapes accurately","intention":"We are learning to draw triangles and regular polygons accurately with mathematical instruments.","criteria":["I can draw triangles accurately with a ruler and protractor, or a ruler and compasses.","I can draw a regular polygon when I know its interior angle.","I can choose the right instruments and method for the shape."],"steps":{"start":"Can you draw a triangle with sides of 3 cm, 4 cm and 10 cm? Why not?","teach":"Model drawing a triangle from two sides and the angle between them with a protractor, then from three sides with compasses. Draw a regular hexagon (interior angle 120°) one side at a time with a protractor, then inside a circle with compasses. Check by measuring.","practise":"The \"Triangles and polygons, accurately\" sheet. Measure and check each other's drawings.","check":"Draw triangle ABC with AB = 7 cm, angle A = 50° and AC = 5 cm. Measure BC."},"use":["m-angles"],"home":"Draw a regular pentagon (interior angle 108°) and turn it into a badge.","vocab":"protractor, compasses, construct, interior angle, regular polygon, accurate","understand":"Why can't you draw a triangle with sides 3 cm, 4 cm and 10 cm?","lookFor":"Explains that the two shorter sides together must be longer than the longest side, or they can't meet."},
    {"id":"lesson-third-angles-in-shapes-and-with-parallel-lines","level":"Third","subject":"Maths","strand":"Shape and angles","codes":["MTH 3-17a"],"title":"Angles in shapes and with parallel lines","intention":"We are learning to name angles and find missing angles using angle facts.","criteria":["I can name angles with three letters, as in angle ABC.","I can identify corresponding, alternate and vertically opposite angles, and use them to find missing angles.","I can use the angle properties of triangles and quadrilaterals to find missing angles."],"steps":{"start":"Tear the three corners off a paper triangle and put them together. What do you notice?","teach":"Name angles with three letters. Draw two parallel lines crossed by a third line and mark the F (corresponding), Z (alternate) and X (vertically opposite) angles. Find all eight angles from one. Use 180° in a triangle and 360° in a quadrilateral to find missing angles, giving a reason each time.","practise":"Angles and turns, then the \"Missing angles\" sheet.","check":"Find the missing angles and give a reason for each: which fact did you use?"},"use":["m-angles"],"home":"Spot parallel lines and their angles on a gate, a window or road markings.","vocab":"corresponding, alternate, vertically opposite, parallel, transversal, angle sum","understand":"How do you know these two angles are equal? Which fact tells you?","lookFor":"Names the fact (alternate, corresponding or vertically opposite) and points to the parallel lines it depends on."},
    {"id":"lesson-third-bearings-scale-drawings-and-enlargement","level":"Third","subject":"Maths","strand":"Shape and angles","codes":["MTH 3-17b","MTH 3-17c"],"title":"Bearings, scale drawings and enlargement","intention":"We are learning to use bearings and scale to read and make plans, and to enlarge and reduce shapes.","criteria":["I can use and give three-figure bearings.","I can read maps and plans, and make accurate scale drawings of routes.","I can enlarge and reduce shapes using a scale factor."],"steps":{"start":"A map's scale is 1 : 50 000. What does 1 cm on the map stand for?","teach":"Measure bearings clockwise from north as three figures (east is 090°). Draw a route at 1 cm to 1 km: 4 km on a bearing of 060°, then 3 km on 150°. Measure the distance and bearing back to the start. Enlarge a shape on squared paper by scale factor 2 and reduce it by ½, comparing the lengths.","practise":"The \"Route and scale\" sheet: a scale drawing from bearings, then an enlargement.","check":"What is the bearing of west? A 3 cm by 5 cm photo is enlarged by scale factor 3. What size is it now?"},"use":["en-ratio"],"home":"Use a map of your area to find the bearing and distance from home to school.","vocab":"bearing, north, clockwise, scale, scale drawing, scale factor, enlarge, reduce","understand":"When a shape is enlarged by scale factor 2, does its area double too?","lookFor":"Explains, or finds by drawing, that the area is four times as big, because the length and width both double."},
    {"id":"lesson-third-coordinates-in-four-quadrants-and-symmetry","level":"Third","subject":"Maths","strand":"Shape and angles","codes":["MTH 3-18a","MTH 3-19a"],"title":"Coordinates in four quadrants, and symmetry","intention":"We are learning to plot and describe points anywhere on a grid, and to use lines of symmetry.","criteria":["I can plot and describe the position of points in all four quadrants.","I can identify all the lines of symmetry in 2D shapes.","I can create and complete symmetrical patterns and pictures."],"steps":{"start":"Where is (−3, 2)? Which way do you go first?","teach":"Draw axes from −6 to 6. Plot points in all four quadrants and join them to make a shape. Reflect it in the y-axis: what happens to the coordinates? Find every line of symmetry of a square, a rectangle, a kite and a regular hexagon. Complete a pattern that is symmetrical about two lines.","practise":"Coordinates: plotting, translating and reflecting, then the \"Four quadrants and symmetry\" sheet.","check":"Plot (2, −3) and reflect it in the y-axis. How many lines of symmetry does a regular pentagon have?"},"use":["en-coordinates"],"home":"Find symmetrical logos or flags and draw in their lines of symmetry.","vocab":"coordinates, quadrant, axis, origin, reflect, line of symmetry","understand":"Why does reflecting a point in the y-axis change the sign of its x-coordinate only?","lookFor":"Explains that the point moves left or right across the axis to the same distance on the other side, but its height doesn't change."},
    {"id":"lesson-third-data-fair-samples-clear-graphs-and-misleading-claims","level":"Third","subject":"Maths","strand":"Data and chance","codes":["MNU 3-20a","MTH 3-20b","MTH 3-21a"],"title":"Data: fair samples, clear graphs and misleading claims","intention":"We are learning to collect and display data fairly, and to judge whether information can be trusted.","criteria":["I can find or collect data, using technology where it helps.","I can interpret data and describe trends, as in an increasing trend.","I can decide if information is robust, vague or misleading, thinking about the source, scale, sample size and how it is shown.","I can choose a representative sample to avoid bias.","I can display data clearly, choosing graphs such as compound bar charts, line graphs and pie charts."],"steps":{"start":"\"9 out of 10 people prefer Fizz!\" What would you want to know before you believed it?","teach":"Show two graphs of the same data, one with an axis that doesn't start at zero. Which looks misleading, and why? Discuss sample size and how a sample was chosen (asking only a football club about favourite sports). Plan a fair survey. Draw a line graph of temperatures and describe the trend, then a pie chart of a small survey (angle = fraction × 360°).","practise":"Reading tables and Bar charts, then the \"Can you trust it?\" sheet.","check":"Give two reasons a graph or claim might mislead. Describe the trend in a line graph."},"use":["n-table","n-bar","en-mean"],"home":"Find a graph in a news story or advert and decide if it's fair.","vocab":"data, sample, bias, representative, robust, misleading, trend, pie chart, line graph, compound bar chart","understand":"Why might asking 10 people give a less reliable answer than asking 100?","lookFor":"Explains that a small sample may not represent everyone, so the result could be due to chance."},
    {"id":"lesson-third-probability-from-0-to-1","level":"Third","subject":"Maths","strand":"Data and chance","codes":["MNU 3-22a"],"title":"Probability from 0 to 1","intention":"We are learning to calculate probabilities and use them to make decisions.","criteria":["I can use the probability scale from 0 to 1, writing probability as a fraction or a decimal.","I can calculate the probability of a simple event, as in throwing a prime number on a 12-sided dice.","I can list all the outcomes of an event and find the probability of each.","I can use a probability to work out an expected number, as in days of rain.","I can explain how the consequences of an event, as well as its probability, affect decisions."],"steps":{"start":"Put these on a line from 0 to 1: rolling a 7 on a normal dice, a coin landing heads, the sun rising tomorrow.","teach":"Probability = favourable outcomes ÷ all outcomes. Find the probability of a prime on a 12-sided dice (5/12). List all the outcomes of a spinner and check the probabilities add to 1. Toss a coin 50 times and compare the frequency of heads with ½. Expected number: if the probability of rain on a June day is 0·25, expect about 7 or 8 rainy days in June. Discuss decisions: a 10% chance of a storm matters more for a sailing trip than a cinema trip.","practise":"How likely is it?, then the \"Chances and choices\" sheet.","check":"A bag has 3 red, 5 blue and 2 green counters. Find the probability of blue as a fraction and as a decimal. In 50 picks (putting it back each time), about how many blues?"},"use":["n-chance"],"home":"Look at the forecast's chance of rain and decide what to plan.","vocab":"probability, outcome, event, equally likely, expected, frequency, fraction, decimal","understand":"The probability of rain is 0·25. Why might you still take a coat?","lookFor":"Explains that unlikely isn't impossible, and the consequence of getting soaked matters as well as the probability."},
    {"id":"lesson-fourth-significant-figures-tolerance-and-error","level":"Fourth","subject":"Maths","strand":"Number","codes":["MNU 4-01a"],"title":"Significant figures, tolerance and error","intention":"We are learning to round to significant figures, judge the accuracy a problem needs, and work with tolerance.","criteria":["I can round answers to a given number of significant figures.","I can show that the context decides how to round.","I can show the effect of rounding too early in a multi-step calculation.","I can use a tolerance to decide whether a measurement is acceptable, as in 235 mm ± 1 mm."],"steps":{"start":"Round 48 263 to 1 significant figure, then 0·004 72 to 2 significant figures.","teach":"Count significant figures from the first non-zero digit. Show that 3·6 × 3·6 = 12·96, but rounding 3·64 to 3·6 first gives 12·96 instead of 13·2496: round only at the end. Explain tolerance with a machine part: 235 mm ± 1 mm means anything from 234 mm to 236 mm is accepted. Check a batch of measurements against it.","practise":"The \"Accurate enough?\" sheet.","check":"Round 0·060 49 to 3 significant figures. Is a 49·3 mm bolt acceptable at 50 mm ± 0·5 mm?"},"use":["n-round-100","n-estimate"],"home":"Look at the tolerance printed on a measuring jug, a bag of flour or a part's packaging.","vocab":"significant figure, round, tolerance, error, accuracy, upper and lower limit","understand":"Why shouldn't you round in the middle of a calculation?","lookFor":"Explains that rounding early carries an error into every later step, so the final answer can be noticeably wrong; round only at the end."},
    {"id":"lesson-fourth-multi-step-problems-and-the-order-of-operations","level":"Fourth","subject":"Maths","strand":"Number","codes":["MNU 4-03a","MTH 4-03b"],"title":"Multi-step problems and the order of operations","intention":"We are learning to solve unfamiliar multi-step problems and use the order of operations, including brackets.","criteria":["I can interpret and solve multi-step problems using the four operations.","I can see how a new problem is like one I've solved before, and use that.","I can apply the correct order of operations in all calculations, including those with brackets.","I can show how adding brackets changes a calculation."],"steps":{"start":"Work out 8 + 4 × 3 and (8 + 4) × 3. Why are they different?","teach":"Review the order of operations: brackets, powers, then multiplying and dividing, then adding and subtracting. Place brackets in 2 + 6 × 5 − 3 to make as many different answers as you can. Solve an unfamiliar problem by asking: what do I know, what do I need, which problem is this like? Model a three-step problem (planning a school trip cost with a discount and a deposit) and write each step.","practise":"Multi-step problems, then the \"Plan it step by step\" sheet.","check":"Work out 36 ÷ (4 + 2) × 3 − 2². Then solve a new multi-step problem and explain your plan."},"use":["en-multistep"],"home":"Plan the cost of a family day out with tickets, travel and food, step by step.","vocab":"order of operations, brackets, powers, multi-step, strategy, inverse","understand":"How did you decide which step to do first in that problem?","lookFor":"Explains the plan: what was known, what was needed, and how it matched a problem solved before, as well as the order of operations."},
    {"id":"lesson-fourth-powers-roots-and-scientific-notation","level":"Fourth","subject":"Maths","strand":"Number","codes":["MTH 4-06a","MTH 4-06b"],"title":"Powers, roots and scientific notation","intention":"We are learning to use the link between powers and roots, and to write very large and very small numbers in scientific notation.","criteria":["I can use the inverse relationship between powers and roots to evaluate roots, as in ∛27 = 3.","I understand that square roots can be positive or negative, as in √9 = ±3.","I can write numbers in scientific notation and work with them."],"steps":{"start":"What number squared makes 49? Is there more than one answer?","teach":"Link squaring and square roots, and cubing and cube roots, as inverses: 5² = 25, so √25 = 5 (and −5 squared is 25 too). Find ∛64 and ⁴√81. Show scientific notation as a × 10ⁿ with 1 ≤ a < 10: the Earth is about 150 000 000 km from the Sun, 1·5 × 10⁸ km; a red blood cell is about 0·000 008 m wide, 8 × 10⁻⁶ m. Multiply in scientific notation with a calculator's EXP or ×10ˣ key.","practise":"The \"Big and small numbers\" sheet.","check":"Write 0·000 46 and 3 200 000 in scientific notation. Evaluate ∛125. Why does √16 have two answers?"},"use":[],"home":"Find a very large or very small number in a science article and write it in scientific notation.","vocab":"power, root, square root, cube root, inverse, scientific notation, standard form","understand":"Why is 4·5 × 10⁶ written that way and not as 45 × 10⁵?","lookFor":"Explains that scientific notation always has one non-zero digit before the point (1 ≤ a < 10), so numbers are easy to compare."},
    {"id":"lesson-fourth-percentage-change-and-choosing-the-best-form","level":"Fourth","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MNU 4-07a"],"title":"Percentage change, and choosing the best form","intention":"We are learning to choose the most efficient form of fraction, decimal or percentage, and to calculate percentage increase and decrease.","criteria":["I can choose the most efficient form of fractions, decimals or percentages for a calculation.","I can calculate a percentage increase or decrease.","I can use my calculations to compare, decide and choose."],"steps":{"start":"Which is easiest to work out in your head: 25% of 48, ¼ of 48, or 0·25 × 48? Why?","teach":"Talk through when each form is quickest: ¼ for mental work, 0·25 with a calculator, % for comparing. Find a percentage change: (change ÷ original) × 100. A bike's price goes from £240 to £276: a 15% increase. Use multipliers: a 15% increase is × 1·15; a 20% decrease is × 0·8. Compare two shops' price rises.","practise":"Percentages, then the \"Up or down?\" sheet.","check":"A phone falls from £450 to £378. What is the percentage decrease? Increase £80 by 12·5% using a multiplier."},"use":["n-percent"],"home":"Track the price of something you buy often and work out the percentage change over a few months.","vocab":"percentage increase, percentage decrease, multiplier, original value, efficient","understand":"A price rises by 10%, then falls by 10%. Is it back where it started? Why?","lookFor":"Explains no: the 10% fall is of a bigger amount, so it ends lower (× 1·1 × 0·9 = × 0·99)."},
    {"id":"lesson-fourth-calculating-with-fractions-and-mixed-numbers","level":"Fourth","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MTH 4-07b"],"title":"Calculating with fractions and mixed numbers","intention":"We are learning to add, subtract and multiply fractions and mixed numbers to solve problems in context.","criteria":["I can add and subtract fractions and mixed numbers in context.","I can multiply fractions and mixed numbers.","I can solve real problems involving fractions and mixed numbers."],"steps":{"start":"A recipe needs 1½ cups of flour. You make 2½ times the recipe. How much flour?","teach":"Review adding with a common denominator. Multiply fractions as part of a part (⅔ × ¾ = 6/12 = ½), cancelling first where you can. Change mixed numbers to improper fractions to multiply: 1½ × 2½ = 3/2 × 5/2 = 15/4 = 3¾. Solve problems: lengths of wood, recipe scaling, time in hours.","practise":"Mixed numbers and calculating with fractions, then the \"Fractions at work\" sheet.","check":"Work out 2⅓ + 1¾ and 2⅖ × 1¼. A plank is 3¾ m long; ⅖ is cut off. How long is the piece cut off?"},"use":["en-fractions-y6","en-fractions-y5"],"home":"Use fractions when cooking: scale a recipe by 1½.","vocab":"mixed number, improper fraction, common denominator, multiply, cancel, simplify","understand":"Why can't you multiply 1½ × 2½ by doing 1 × 2 and ½ × ½?","lookFor":"Explains that you'd miss the parts that cross over (1 × ½ and ½ × 2), so change to improper fractions first."},
    {"id":"lesson-fourth-direct-and-inverse-proportion","level":"Fourth","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MNU 4-08a"],"title":"Direct and inverse proportion","intention":"We are learning to calculate how a change in one quantity changes a related quantity.","criteria":["I can use proportion to calculate the change in one quantity caused by a change in a related quantity.","I can tell direct proportion from inverse proportion.","I can solve real-life proportion problems."],"steps":{"start":"4 painters take 6 days to paint a school. How long would 8 painters take? And how much paint would they use?","teach":"Direct proportion: both go up together at the same rate (twice the time, twice the cost); use the unitary method. Inverse proportion: one goes up as the other goes down (twice the workers, half the time); multiply to find the total amount of work first. Sort real situations into direct, inverse or neither (age and height).","practise":"Ratio and proportion, then the \"Proportion problems\" sheet.","check":"6 litres of fuel take a car 84 km. How far on 10 litres? A journey takes 3 hours at 60 km/h. How long at 45 km/h?"},"use":["en-ratio"],"home":"Spot direct and inverse proportion at home: cooking times, sharing costs, how long chores take with more helpers.","vocab":"direct proportion, inverse proportion, unitary method, rate, constant","understand":"How do you know whether a problem is direct or inverse proportion?","lookFor":"Explains it by asking: if one quantity doubles, does the other double (direct) or halve (inverse)?"},
    {"id":"lesson-fourth-earnings-deductions-and-net-pay","level":"Fourth","subject":"Maths","strand":"Money","codes":["MNU 4-09b"],"title":"Earnings, deductions and net pay","intention":"We are learning to calculate gross and net pay from earnings and deductions.","criteria":["I can find information on earnings and deductions.","I can calculate gross pay, including overtime.","I can calculate net income from gross pay and deductions."],"steps":{"start":"Two jobs: £11·50 an hour for 30 hours, or £18 000 a year. Which pays more a week?","teach":"Explain gross pay, overtime (time and a half, double time), commission, and deductions (income tax, National Insurance, pension). Use given practice rates on a payslip to work out net pay, and point out that real rates change each year and are published by the government. Read a sample payslip line by line.","practise":"The \"My payslip\" sheet, using the practice rates on it.","check":"Someone works 37 hours at £12 and 4 hours' overtime at time and a half. Find their gross pay. With £68·40 deducted, what is their net pay?"},"use":["n-best-value"],"home":"Look at a real (or example) payslip with a grown-up and find gross pay, deductions and net pay.","vocab":"gross pay, net pay, deduction, overtime, commission, income tax, National Insurance, pension","understand":"Why is net pay what matters when budgeting?","lookFor":"Explains that net pay is what actually arrives after deductions, so it's the money there is to spend or save."},
    {"id":"lesson-fourth-credit-debt-and-choosing-financial-products","level":"Fourth","subject":"Maths","strand":"Money","codes":["MNU 4-09a","MNU 4-09c"],"title":"Credit, debt and choosing financial products","intention":"We are learning to manage credit and debt responsibly, compare financial products, and convert currencies for best value.","criteria":["I can discuss what to consider when deciding what I can afford, to manage credit and debt.","I can budget and justify my spending and saving choices.","I can compare financial products, such as savings accounts, loans and credit cards, after calculating.","I can explain the impact of financial decisions.","I can use currency conversion to find best value."],"steps":{"start":"A £600 laptop: pay now, or £55 a month for 12 months. What is the difference?","teach":"Calculate the total cost of buying on credit and compare it with saving first. Compare two savings accounts with simple interest (3% a year, or 2·5% plus a £10 bonus) over a year. Discuss what 'can I afford it?' means: income, essential costs, other debts. Compare holiday money from two exchange rates with a fee. Talk about the impact of missing payments.","practise":"The \"Borrow, save or wait?\" sheet.","check":"Which costs less: a £900 loan repaid at £80 a month for 12 months, or saving £75 a month for 12 months then buying? Explain the impact of each choice."},"use":["n-best-value"],"home":"Compare the real cost of buying something on a payment plan with saving up for it.","vocab":"credit, debt, interest, APR, savings account, loan, exchange rate, commission, budget","understand":"Why might the cheapest monthly payment not be the best deal?","lookFor":"Explains that a longer term or higher interest can make the total cost much more, and that missing payments has consequences."},
    {"id":"lesson-fourth-time-zones-planning-and-speed-with-decimal-hours","level":"Fourth","subject":"Maths","strand":"Time","codes":["MNU 4-10a","MNU 4-10b"],"title":"Time zones, planning, and speed with decimal hours","intention":"We are learning to manage time across time zones and midnight, and to calculate speed, distance and time with decimal hours.","criteria":["I can plan using different time zones and across midnight.","I can calculate durations across hours, days and months.","I can calculate speed, distance and time using decimal fractions of an hour."],"steps":{"start":"A flight leaves Glasgow at 21:40 and takes 7 hours 50 minutes. New York is 5 hours behind. What is the local time when it lands?","teach":"Use a timeline to cross midnight and change time zone in separate steps. Convert minutes to decimal hours (36 minutes = 0·6 hours) and back. Calculate a speed from a time like 2 hours 24 minutes (2·4 hours). Count durations across months, remembering month lengths. Plan a revision timetable that fits around fixed times.","practise":"12-hour and 24-hour time, then the \"Around the world\" sheet.","check":"A train travels 186 km in 1 hour 33 minutes. What is its average speed? How many days from 18 March to 4 May?"},"use":["n-time-24","n-durations"],"home":"Plan a call to someone in another time zone at a time that suits you both.","vocab":"time zone, GMT, BST, duration, decimal hours, average speed, timetable","understand":"Why is 1 hour 15 minutes written as 1·25 hours, not 1·15?","lookFor":"Explains that 15 minutes is a quarter of an hour, because there are 60 minutes in an hour, not 100."},
    {"id":"lesson-fourth-surface-area-and-using-materials-efficiently","level":"Fourth","subject":"Maths","strand":"Measurement","codes":["MNU 4-11a","MTH 4-11b"],"title":"Surface area, and using materials efficiently","intention":"We are learning to find areas and surface areas, and use them to make the best use of materials.","criteria":["I can calculate the area of kites, parallelograms and trapeziums.","I can use formulae to find the surface area of cuboids, triangular prisms and cylinders.","I can make the most efficient use of materials in a real problem.","I understand the impact of rounding too early on accuracy."],"steps":{"start":"Which box needs less card to make: a 10 cm cube, or a 20 cm × 10 cm × 5 cm cuboid? Both hold 1000 cm³.","teach":"Derive the trapezium formula ½(a + b)h by doubling it into a parallelogram, and the kite as half the product of its diagonals. Draw nets to find surface areas: cuboid 2(lb + bh + lh); a cylinder's curved surface unrolls to a rectangle 2πr by h. Compare the card needed for packaging that holds the same amount, keeping full accuracy until the end.","practise":"Area and perimeter, then the \"Wrap it up\" sheet.","check":"Find the area of a trapezium with parallel sides 7 cm and 11 cm and height 5 cm. Find the surface area of a cylinder with radius 3 cm and height 10 cm."},"use":["n-area","en-area-formulae"],"home":"Measure a cereal box and work out how much card it uses.","vocab":"trapezium, kite, parallelogram, net, surface area, prism, cylinder, efficient","understand":"Two boxes hold the same amount. Why might one need less card?","lookFor":"Explains that shapes closer to a cube have a smaller surface area for the same volume, so they need less material."},
    {"id":"lesson-fourth-volume-of-prisms-and-cylinders","level":"Fourth","subject":"Maths","strand":"Measurement","codes":["MTH 4-11c"],"title":"Volume of prisms and cylinders","intention":"We are learning to calculate the volume of prisms, including triangular prisms and cylinders, using formulae.","criteria":["I can calculate the volume of a prism as the area of its cross-section × its length.","I can calculate the volume of triangular prisms and cylinders.","I can solve practical problems with volume and capacity."],"steps":{"start":"A tent is shaped like a triangular prism. How could you work out how much air it holds?","teach":"Show that every prism's volume is cross-section area × length, from cuboids to triangular prisms. For a cylinder, V = πr²h. Convert between cm³ and litres (1000 cm³ = 1 litre). Solve: how many 330 ml cans fill a cylinder tank of radius 20 cm and height 50 cm?","practise":"The \"Fill it up\" sheet.","check":"Find the volume of a triangular prism with triangle base 6 cm, height 4 cm and length 15 cm, and of a cylinder with radius 5 cm and height 12 cm."},"use":["en-area-formulae"],"home":"Work out how many litres a mug, a vase or a fish tank holds, then check with water.","vocab":"prism, cross-section, volume, cylinder, capacity, litre, cm³","understand":"Why does area of cross-section × length work for every prism?","lookFor":"Explains that the prism is the same cross-section repeated along its length, layer after layer."},
    {"id":"lesson-fourth-maths-in-careers-and-the-workplace","level":"Fourth","subject":"Maths","strand":"Number","codes":["MTH 4-12a"],"title":"Maths in careers and the workplace","intention":"We are learning about the maths used in different careers, and to present how maths is applied at work.","criteria":["I can contribute to discussions on the role of maths in everyday life and work.","I can investigate the maths skills needed for a range of careers, including STEM careers.","I can present, with others, how maths is applied in a workplace."],"steps":{"start":"Name a job that uses no maths at all. Now let's test it.","teach":"Pick three careers the pupil is interested in (for example, a nurse, an electrician and a games designer). For each, find the maths: dosage calculations, Ohm's law and measurements, coordinates and algorithms. Use careers information, such as job profiles that list the skills needed. Plan a short presentation with a worked example from one job.","practise":"The \"Maths in careers\" sheet: research three careers and plan the presentation.","check":"Give the presentation. Ask: which maths skill came up in all three jobs, and why?"},"use":[],"home":"Ask a family member or friend what maths they use at work, and add it to your research.","vocab":"career, STEM, skill, workplace, application, presentation","understand":"Which maths skill came up in most of the careers you researched? Why do you think that is?","lookFor":"Names a skill (such as percentages, measurement or data) and links it to tasks common across jobs, with evidence from the research."},
    {"id":"lesson-fourth-sequences-finding-the-nth-term","level":"Fourth","subject":"Maths","strand":"Patterns and missing numbers","codes":["MTH 4-13a"],"title":"Sequences: finding the nth term","intention":"We are learning to find a general formula for the nth term of a linear sequence and use it to solve problems.","criteria":["I can establish a number sequence from a physical or pictorial pattern.","I can find a formula for the nth term of a linear sequence.","I can use the formula to make evaluations and solve related problems."],"steps":{"start":"Tables in a row seat 6, 10, 14, 18 people. How many seats for 25 tables?","teach":"Draw the tables pattern and see why it goes up by 4 each time: each new table adds 4 seats. Find the nth term as 4n + 2 by comparing with the 4 times table. Check with n = 1. Use the formula backwards: how many tables to seat 150? Repeat with a decreasing sequence.","practise":"Number patterns, then the \"nth term\" sheet.","check":"Find the nth term of 7, 11, 15, 19 … Which term is 123? Is 200 in the sequence?"},"use":["m-patterns"],"home":"Find a growing pattern in real life (fence panels, a staircase of blocks) and write its nth term.","vocab":"sequence, nth term, general formula, linear, common difference","understand":"In 4n + 2, what does the 2 tell you?","lookFor":"Explains it is the adjustment from the 4 times table: each term is 2 more than a multiple of 4 (the 'zero term')."},
    {"id":"lesson-fourth-gradient-and-straight-line-graphs","level":"Fourth","subject":"Maths","strand":"Patterns and missing numbers","codes":["MTH 4-13b","MTH 4-13c","MTH 4-13d"],"title":"Gradient and straight-line graphs","intention":"We are learning to calculate gradients, write equations of horizontal and vertical lines, and plot straight lines from formulae.","criteria":["I can calculate the gradient of a line on a coordinate diagram.","I can interpret a gradient in context, as in whether a ramp meets building regulations.","I can give the equation of a horizontal or vertical line, as in x = a or y = b.","I can use a formula to plot a straight line and answer questions from it."],"steps":{"start":"Which is steeper: a ramp that rises 1 m over 12 m, or one that rises 1 m over 15 m?","teach":"Gradient = vertical change ÷ horizontal change. Find gradients from graphs, including negative gradients. Horizontal lines have gradient 0 and equation y = b; vertical lines are x = a and have no gradient. Use y = 2x − 1 to make a table of points, plot them and read off values. Check a ramp against a maximum gradient of 1 in 12.","practise":"The \"Slopes and lines\" sheet.","check":"Find the gradient through (1, 2) and (5, 10). What is the equation of the line through (3, −1) and (3, 4)? Does a ramp rising 0·5 m over 5 m meet a 1 in 12 rule?"},"use":["en-coordinates"],"home":"Measure a ramp or slope near you and work out its gradient.","vocab":"gradient, slope, vertical, horizontal, steepness, equation, coordinate, straight line","understand":"Why does a vertical line have no gradient?","lookFor":"Explains that the horizontal change is zero, and you can't divide by zero."},
    {"id":"lesson-fourth-brackets-and-factorising","level":"Fourth","subject":"Maths","strand":"Patterns and missing numbers","codes":["MTH 4-14a","MTH 4-14b"],"title":"Brackets and factorising","intention":"We are learning to expand and simplify brackets, and to factorise expressions.","criteria":["I can expand brackets using the distributive law, and simplify.","I can evaluate expressions involving a bracket.","I can find the factors of algebraic terms and identify common factors.","I can factorise expressions with a numerical common factor."],"steps":{"start":"4 × 23 is 4 × 20 + 4 × 3. How does that help you work out 3(x + 5)?","teach":"Use area rectangles to show 3(x + 5) = 3x + 15. Expand and simplify 2(3a − 4) + 5a, and with negatives: −2(x − 3) = −2x + 6. Factorise by finding the highest common factor: 6x + 9 = 3(2x + 3), and 8y − 12 = 4(2y − 3). Check by expanding back.","practise":"The \"Expand and factorise\" sheet.","check":"Expand and simplify 4(2x + 1) − 3(x − 2). Factorise 15a − 20. Find 5(2p − 3) when p = −1."},"use":[],"home":"Make a puzzle for someone at home: give them a factorised expression and ask them to expand it.","vocab":"expand, bracket, distributive law, factorise, common factor, simplify","understand":"How can you check that 3(2x + 3) is the right factorisation of 6x + 9?","lookFor":"Expands it back to 6x + 9, and checks that 3 is the highest common factor so nothing more comes out."},
    {"id":"lesson-fourth-harder-equations-and-inequalities","level":"Fourth","subject":"Maths","strand":"Patterns and missing numbers","codes":["MTH 4-15a"],"title":"Harder equations and inequalities","intention":"We are learning to solve equations with unknowns on both sides and brackets, and to solve inequalities.","criteria":["I can solve equations such as ax ± b = cx ± d.","I can solve equations involving brackets.","I can solve linear inequalities, including on closed intervals.","I can express a problem as an equation, inequation or formula and solve it."],"steps":{"start":"Two phone plans: £15 plus £2 a gigabyte, or £25 plus £1 a gigabyte. When do they cost the same?","teach":"Write the plans as 15 + 2g = 25 + g and solve by balancing (take g from both sides first). Solve 3(x − 2) = x + 8 by expanding first. Solve inequalities like a balance too: 4x − 3 > 13 gives x > 4; show it on a number line. Solve −2 ≤ x + 3 < 5 and list the whole numbers that fit.","practise":"Missing numbers and signs, then the \"Balance it\" sheet.","check":"Solve 5x + 4 = 2x + 19 and 4(x + 1) = 2(x + 7). Solve 3x − 5 ≤ 16. When is the first phone plan cheaper?"},"use":["m-equations"],"home":"Compare two real price plans (phones, gyms, taxis) and find where they cost the same.","vocab":"equation, inequation, inequality, balance, expand, solve, interval","understand":"When does the inequality sign flip?","lookFor":"Explains it flips when you multiply or divide both sides by a negative number, and can show why with an example."},
    {"id":"lesson-fourth-pythagoras-and-trigonometry-in-right-angled-triangles","level":"Fourth","subject":"Maths","strand":"Shape and angles","codes":["MTH 4-16a"],"title":"Pythagoras and trigonometry in right-angled triangles","intention":"We are learning to use Pythagoras' theorem and trigonometry to find sides and angles in right-angled triangles.","criteria":["I can calculate any side of a right-angled triangle using Pythagoras' theorem.","I can calculate a side using trigonometry.","I can calculate an angle using trigonometry.","I can choose the right strategy and interpret the answer in context."],"steps":{"start":"A 5 m ladder leans against a wall with its foot 3 m out. How high up the wall does it reach?","teach":"Square the sides of 3, 4, 5 triangles to show a² + b² = c². Find a hypotenuse and a shorter side. Label opposite, adjacent and hypotenuse from an angle, and use SOH CAH TOA. Find a side (tan 35° × 8) and an angle (inverse tan of 5 ÷ 8). Decide which tool fits: two sides and no angle needed means Pythagoras.","practise":"The \"Pythagoras and trigonometry\" sheet.","check":"Find the hypotenuse when the other sides are 9 cm and 12 cm. A ramp rises 1·2 m over 6 m: find its angle with the ground."},"use":[],"home":"Use a ruler and protractor to check a Pythagoras answer on a real triangle, such as a ladder's position or a slope.","vocab":"hypotenuse, Pythagoras, opposite, adjacent, sine, cosine, tangent, inverse","understand":"How do you decide between Pythagoras and trigonometry?","lookFor":"Pythagoras when you know two sides and want the third; trigonometry when an angle is involved, either known or wanted."},
    {"id":"lesson-fourth-circles-circumference-and-area","level":"Fourth","subject":"Maths","strand":"Shape and angles","codes":["MTH 4-16b"],"title":"Circles: circumference and area","intention":"We are learning the links between radius, diameter, circumference and area, and to solve problems with circles.","criteria":["I can calculate circumference using C = πD or C = 2πr.","I can calculate area using A = πr².","I can find the diameter or radius when I know the area or circumference."],"steps":{"start":"Wrap string round a tin and measure it, then measure across. Divide the first by the second. What do you notice?","teach":"Find π from several round objects. Use C = πD and A = πr², taking care to use the radius for area. Work backwards: a circle of circumference 50 cm has diameter 50 ÷ π. A circle of area 100 cm² has radius √(100 ÷ π). Solve problems such as the distance a wheel travels in 100 turns.","practise":"The \"Round and round\" sheet.","check":"Find the circumference and area of a circle of diameter 14 cm. A circular pond has area 50 m². What is its radius?"},"use":[],"home":"Measure round objects at home and check that circumference ÷ diameter is about 3·14 each time.","vocab":"radius, diameter, circumference, area, pi, π","understand":"Why must you use the radius, not the diameter, in A = πr²?","lookFor":"Explains that the formula squares the radius; using the diameter makes the area four times too big."},
    {"id":"lesson-fourth-circle-angle-facts-and-similar-shapes","level":"Fourth","subject":"Maths","strand":"Shape and angles","codes":["MTH 4-17a","MTH 4-17b"],"title":"Circle angle facts and similar shapes","intention":"We are learning to use the facts about tangents and angles in a semicircle, and to solve problems with similar shapes.","criteria":["I know a tangent meets a radius at 90°, and use it to find missing angles.","I know the angle in a semicircle is 90°, and use it to solve problems.","I can use similarity to find unknown lengths.","I can solve problems involving the area of similar shapes."],"steps":{"start":"Draw a semicircle and mark a point on the curve. Join it to both ends of the diameter. Measure the angle. Try another point.","teach":"Show that the angle in a semicircle is always 90°, then combine it with triangle angle sums. Draw a tangent and its radius to show the right angle. Find missing angles in diagrams that use both facts and isosceles triangles made by radii. For similar shapes, find the scale factor from matching sides, then the unknown length. Areas scale by the square of the scale factor.","practise":"The \"Circles and similar shapes\" sheet.","check":"Find a missing angle using a tangent and a radius. Two similar photos have widths 6 cm and 15 cm. If the small one is 4 cm tall, how tall is the large one? How many times larger is its area?"},"use":[],"home":"Find similar shapes at home (photo sizes, paper sizes such as A4 and A5) and work out their scale factor.","vocab":"tangent, radius, semicircle, similar, scale factor, corresponding, area factor","understand":"A shape is enlarged by scale factor 3. Why is its area 9 times bigger, not 3?","lookFor":"Explains that both length and width are tripled, so the area is multiplied by 3 × 3 = 9."},
    {"id":"lesson-fourth-transformations-and-rotational-symmetry","level":"Fourth","subject":"Maths","strand":"Shape and angles","codes":["MTH 4-18a","MTH 4-18b","MTH 4-19a"],"title":"Transformations and rotational symmetry","intention":"We are learning to transform shapes on a four-quadrant grid and to describe rotational symmetry.","criteria":["I can read and plot coordinates on a four-quadrant grid.","I can reflect and translate a point or shape, and describe a transformation.","I can describe the rotational properties of shapes, pictures and patterns, including the order of rotation.","I can use rotational symmetry to complete or create designs."],"steps":{"start":"How many times does a square look the same as you turn it through one full turn?","teach":"Plot a shape in all four quadrants. Translate it by a vector, such as 3 right and 2 down, and reflect it in the x-axis, the y-axis and a line such as x = 1. Describe a given transformation fully. Find the order of rotational symmetry of letters, logos and regular polygons with tracing paper, then complete a design with order 4.","practise":"Coordinates: plotting, translating and reflecting, then the \"Move it and turn it\" sheet.","check":"Reflect triangle (1, 1), (3, 1), (3, 4) in the x-axis and give the new coordinates. What is the order of rotational symmetry of a regular hexagon?"},"use":["en-coordinates"],"home":"Find logos with rotational symmetry and give each one's order.","vocab":"translate, reflect, transformation, image, vector, rotational symmetry, order of rotation","understand":"How is order of rotational symmetry different from lines of symmetry?","lookFor":"Explains that the order counts how many times a shape fits onto itself in one full turn, while lines of symmetry are about reflection."},
    {"id":"lesson-fourth-averages-and-spread","level":"Fourth","subject":"Maths","strand":"Data and chance","codes":["MTH 4-20b"],"title":"Averages and spread","intention":"We are learning to find the mean, median, mode and range, choose the best average, and see how an average can mislead.","criteria":["I can calculate the mean, median, mode and range of a data set.","I can decide which average is most appropriate.","I can explain how using a different average could be misleading."],"steps":{"start":"Five people earn £18 000, £20 000, £21 000, £22 000 and £150 000. What is the 'average' pay?","teach":"Find the mean (£46 200) and median (£21 000) of the pay data and discuss which is fairer. Find the mode of shoe sizes for a shop order. Use the range to compare spread. Decide which average suits each situation: house prices (median), most popular size (mode), test scores with no extreme values (mean).","practise":"The mean, then the \"Which average?\" sheet.","check":"Find the mean, median, mode and range of 4, 7, 7, 9, 12, 15. A company says its 'average' pay is £46 200. Why could that mislead?"},"use":["en-mean"],"home":"Collect a week of temperatures or bus journey times and find all four statistics.","vocab":"mean, median, mode, range, average, spread, outlier, misleading","understand":"When is the median a better average than the mean?","lookFor":"When there are extreme values (outliers), such as a few very high salaries, which pull the mean away from what is typical."},
    {"id":"lesson-fourth-interpreting-data-correlation-and-choosing-diagrams","level":"Fourth","subject":"Maths","strand":"Data and chance","codes":["MNU 4-20a","MTH 4-21a"],"title":"Interpreting data, correlation and choosing diagrams","intention":"We are learning to interpret raw and graphical data, describe relationships, and choose the best diagram for the data.","criteria":["I can interpret raw and graphical data and comment on relationships, using words such as correlation.","I can choose and justify the most appropriate diagram, such as a stem and leaf diagram.","I can display discrete, continuous and grouped data appropriately.","I can communicate my findings clearly."],"steps":{"start":"Do taller people have bigger feet? How could we find out, and how would we show it?","teach":"Draw a scatter graph of height against foot length and describe the correlation (positive, negative, none) and its strength. Discuss why correlation doesn't prove one causes the other. Make an ordered stem and leaf diagram of test scores and read the median from it. Sort data into discrete, continuous and grouped, and match each to a suitable chart.","practise":"Reading tables, then the \"What does the data say?\" sheet.","check":"Describe the correlation in a given scatter graph. Which diagram would you choose for 30 reaction times, and why?"},"use":["n-table","n-bar"],"home":"Find a graph in the news and write two sentences about what it shows and one about what it doesn't.","vocab":"correlation, scatter graph, stem and leaf, discrete, continuous, grouped, frequency, trend","understand":"Ice cream sales and sunburn are positively correlated. Does ice cream cause sunburn?","lookFor":"Explains that correlation doesn't prove cause: both are linked to a third factor, hot sunny weather."},
    {"id":"lesson-fourth-probability-expectation-and-risk","level":"Fourth","subject":"Maths","strand":"Data and chance","codes":["MNU 4-22a"],"title":"Probability, expectation and risk","intention":"We are learning to calculate probabilities and expected outcomes, and to use them for predictions, risk and decisions.","criteria":["I can calculate the probability of an event.","I can determine how many times I expect an event to occur.","I can use probability to make predictions, assess risk and make informed decisions."],"steps":{"start":"A game costs £1 to play. You win £5 if you roll a 6. Over 60 games, would you expect to win or lose money?","teach":"Calculate expected frequency = probability × number of trials. Work out the expected result of the game (60 × ⅙ = 10 wins, £50 won, £60 spent). Use relative frequency from an experiment to estimate a probability. Discuss risk as probability and consequence together, with examples like insurance, weather warnings and medical tests.","practise":"How likely is it?, then the \"Risky business\" sheet.","check":"The probability a phone is faulty is 0·02. How many faulty phones would you expect in a batch of 1500? Is a 1% chance of losing £1000 worse than a 50% chance of losing £10? Explain."},"use":["n-chance"],"home":"Look at a weather warning or an insurance offer and talk about the probability and the consequences.","vocab":"probability, expected frequency, relative frequency, risk, prediction, outcome","understand":"Why might people buy insurance even though they expect to lose money on it on average?","lookFor":"Explains that the consequence of a rare loss could be very serious, so paying a small certain cost reduces the risk."},
    {"id":"lesson-early-rhyme-and-patterns-in-words","level":"Early","subject":"Literacy","strand":"Listening and sounds","codes":["LIT 0-01a","LIT 0-11a","LIT 0-20a"],"title":"Rhyme and patterns in words","intention":"We are learning to hear and make rhymes.","criteria":["I can hear and say rhyming words.","I can make a rhyme for a word.","I can join in with songs, rhymes and stories."],"steps":{"start":"Say a nursery rhyme together. Which words sound the same at the end?","teach":"Say pairs: cat–hat (rhyme?), cat–dog (rhyme?). Give a word and make up rhymes, real or silly.","practise":"Rhyming words.","check":"Ask for a word that rhymes with 'pig' and with 'sun'."},"use":["l-rhyme"],"home":"Read rhyming books and pause so your child says the rhyming word.","vocab":"rhyme, sound, word","understand":"Do cat and cup rhyme? Why not?","lookFor":"Says they start the same but end differently; rhymes have the same ending sound."},
    {"id":"lesson-early-hearing-the-sounds-in-words","level":"Early","subject":"Literacy","strand":"Listening and sounds","codes":["ENG 0-12a","LIT 0-13a"],"title":"Hearing the sounds in words","intention":"We are learning to hear the first sound and all the sounds in a word.","criteria":["I can hear and say the single sounds letters make.","I can hear the first sound in a word.","I can count the sounds in a short word."],"steps":{"start":"I spy with my little eye something beginning with /m/.","teach":"Say a word slowly, stretching each sound (m-a-p). Push a counter for each sound. Find the first sound of objects in a bag.","practise":"First sounds, then How many sounds?","check":"What's the first sound in 'fish'? How many sounds in 'dog'?"},"use":["l-first-sound","l-count-sounds"],"home":"Play I spy using sounds, not letter names.","vocab":"sound, first sound, word, stretch","understand":"How many sounds in ship? Show me.","lookFor":"Says 3 (sh-i-p) and knows two letters can make one sound."},
    {"id":"lesson-early-letter-sounds-and-blending-to-read","level":"Early","subject":"Literacy","strand":"Reading: phonics and tricky words","codes":["ENG 0-12a","LIT 0-13a","LIT 0-21a"],"title":"Letter sounds and blending to read","intention":"We are learning to say letter sounds and blend them to read words.","criteria":["I know the sounds of lowercase letters.","I can blend sounds to read a word.","I read from left to right and top to bottom."],"steps":{"start":"Flash letter cards: say the sound for each.","teach":"Show s, a, t, p, i, n. Blend s-a-t → sat, pointing left to right. Change one sound to make a new word (sat → pat).","practise":"Sound Switch: first doors, then the Short a list.","check":"Read five words such as pin, tap, sit, nap, tin."},"use":["g-switch-first","short-a"],"home":"Point to words left to right when you read together.","vocab":"sound, letter, blend, read","understand":"Here's a word you haven't seen: sip. How will you read it?","lookFor":"Says each sound and blends them, without guessing from a picture."},
    {"id":"lesson-early-two-letters-one-sound-sh-ch-and-th","level":"Early","subject":"Literacy","strand":"Reading: phonics and tricky words","codes":["ENG 0-12a","LIT 0-13a"],"title":"Two letters, one sound: sh, ch and th","intention":"We are learning that two letters can make one sound.","criteria":["I can hear and say sounds made by two letters together.","I can read words with sh, ch and th."],"steps":{"start":"Make a 'shh' sound. What letters do you think make it?","teach":"Show sh, ch and th as one sound tile each. Blend sh-o-p, ch-i-p, th-i-n. Sort pictures by sound.","practise":"Sound Hopper: two-letter sounds, then the sh list.","check":"Read ship, chin, moth and point to the two-letter sound."},"use":["g-hopper-digraphs","sh"],"home":"Hunt for sh, ch and th in signs and books.","vocab":"digraph, sound, two letters","understand":"Why do we say s-h as one sound in shop?","lookFor":"Knows the two letters work together to make one sound."},
    {"id":"lesson-early-reading-tricky-words","level":"Early","subject":"Literacy","strand":"Reading: phonics and tricky words","codes":["ENG 0-12a","LIT 0-13a"],"title":"Reading tricky words","intention":"We are learning to read tricky words we can't sound out.","criteria":["I can read familiar tricky words in sentences.","I know the difference between a letter, a word and a number."],"steps":{"start":"Is this a letter, a word or a number? (a, 7, cat)","teach":"Show the, said, was, you. Spot the tricky part. Read each in a sentence. Hide them around the room to find and read.","practise":"Tricky word sentences.","check":"Read five tricky words on cards, then in a short sentence."},"use":["r-tricky"],"home":"Make tricky word cards and play snap or pairs.","vocab":"tricky word, letter, word, sentence","understand":"Which part of the word is tricky? Which part can you sound out?","lookFor":"Points to the tricky part (the heart part) and sounds out the rest."},
    {"id":"lesson-early-talking-about-a-story","level":"Early","subject":"Literacy","strand":"Reading: understanding stories","codes":["ENG 0-17a","LIT 0-19a"],"title":"Talking about a story","intention":"We are learning to talk about stories and predict what happens.","criteria":["I can ask and answer questions about a story.","I can say what might happen next.","I can retell a story in my own way.","I can share what I liked and link it to my life."],"steps":{"start":"Look at the cover: what do you think this story is about?","teach":"Read the story together, stopping to ask: who is in it? What happened? What will happen next? Retell it with props or pictures.","practise":"Read and answer the questions on a first story.","check":"Ask who, where and what happened, and what they liked."},"use":["r-bus","s-d-hen"],"home":"Read a bedtime story every night and talk about it.","vocab":"story, character, beginning, middle, end, predict","understand":"What do you think will happen next? What makes you think that?","lookFor":"Gives a prediction and a reason from the story or the pictures."},
    {"id":"lesson-early-listening-taking-turns-and-following-instructions","level":"Early","subject":"Literacy","strand":"Listening and talking","codes":["LIT 0-02a","ENG 0-03a","LIT 0-04a"],"title":"Listening, taking turns and following instructions","intention":"We are learning to listen, take turns and follow instructions.","criteria":["I can take turns when listening and talking.","I can look at the person talking.","I can ask and answer questions.","I can follow and give simple instructions."],"steps":{"start":"Play a quick game: touch your nose, then your knees, then clap.","teach":"Take turns with a talking object. Follow two-step instructions to make something. Listen to a short story and answer questions about it.","practise":"Listen to the story, then answer the questions.","check":"Give a three-step instruction to follow. Ask one question about what they heard."},"use":["lc-bus","lc-shell-shop"],"home":"Ask your child to give you instructions to make a sandwich.","vocab":"listen, turn, instruction, question, answer","understand":"What did your partner just say? Tell me in your own words.","lookFor":"Repeats the main idea, showing they listened."},
    {"id":"lesson-early-forming-lowercase-letters","level":"Early","subject":"Literacy","strand":"Handwriting","codes":["LIT 0-21a"],"title":"Forming lowercase letters","intention":"We are learning to hold a pencil well and form letters.","criteria":["I can hold a pencil with control.","I can form most lowercase letters clearly.","I can leave a space between words."],"steps":{"start":"Air-write big letters with your finger.","teach":"Show where each letter starts and the direction of movement. Trace grey letters, then dotted ones, then write alone. Use a finger space between words.","practise":"The letter formation sheet.","check":"Write their name and three letters you choose, starting each in the right place."},"use":["letter-formation"],"home":"Draw letters in sand, shaving foam or with chalk.","vocab":"letter, start, finger space, pencil grip","understand":"Why does it matter where you start a letter? Show me what goes wrong with b if you start at the bottom.","lookFor":"Explains that the right start makes each letter the same every time; can show a wrong start, spot what changed, and fix it."},
    {"id":"lesson-early-writing-a-sentence","level":"Early","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["ENG 0-12a","LIT 0-21a","LIT 0-21b"],"title":"Writing a sentence","intention":"We are learning to write a sentence with a capital letter and full stop.","criteria":["I can try to spell familiar words.","I can write words from left to right with spaces.","I can try to use a capital letter and a full stop in a sentence."],"steps":{"start":"Say a sentence about your weekend. Count the words on your fingers.","teach":"Model writing the sentence: capital letter to start, sound out each word, finger spaces, full stop. Read it back together.","practise":"Capital letters and full stops, then a short dictation.","check":"Write one sentence of their own and check for a capital and full stop."},"use":["w-capitals","dictate:short-a"],"home":"Write shopping lists or cards together.","vocab":"sentence, capital letter, full stop, finger space","understand":"How do you know where your sentence starts and ends?","lookFor":"Points to the capital letter and full stop, and reads the sentence back."},
    {"id":"lesson-early-telling-and-drawing-my-own-story","level":"Early","subject":"Literacy","strand":"Writing: creating texts","codes":["LIT 0-09b","LIT 0-26a","LIT 0-31a"],"title":"Telling and drawing my own story","intention":"We are learning to make up and share our own stories.","criteria":["I can tell a story in order.","I can share ideas in pictures, words and talk.","I can use new words I've learned."],"steps":{"start":"Tell me about something you did yesterday, from start to finish.","teach":"Plan a story in three pictures (beginning, middle, end). Talk it through, then label or write a sentence for each picture.","practise":"Draw and tell a three-part story.","check":"Retell the story in order, using first, then, at the end."},"use":[],"home":"Make up a story together at bedtime.","vocab":"story, beginning, middle, end, character","understand":"What's the problem in your story, and how does it end?","lookFor":"Tells a beginning, middle and end in order."},
    {"id":"lesson-early-choosing-and-sharing-stories-i-like","level":"Early","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 0-01b","LIT 0-11b","LIT 0-01c"],"title":"Choosing and sharing stories I like","intention":"We are learning to choose stories we enjoy and share what we think about them.","criteria":["I can choose a story using its cover, title, author or illustrator.","I can share what I like and don't like about stories, songs and rhymes.","I can retell or act out a story in different ways, for example with puppets or props."],"steps":{"start":"Lay out three or four books. Which one would you like? What made you pick it: the cover, the title, the pictures?","teach":"Read the chosen story. Stop to talk about the characters and what happens. Then retell it together with props, puppets or the pictures, and say which part was best and which part they didn't like, and why.","practise":"The \"My favourite story\" sheet: draw a favourite part and colour a face for how they felt about it.","check":"Ask them to choose between two books and tell you why. Can they retell one part of the story in their own way?"},"use":[],"home":"Visit the library together and let your child choose a book. Ask what made them pick it.","vocab":"story, cover, title, author, illustrator, character, like, dislike","understand":"Why did you choose that book? What did you like or not like about it?","lookFor":"Gives a reason linked to the book (the cover, the characters, a funny part), not just \"it's good\"."},
    {"id":"lesson-early-asking-questions-about-stories","level":"Early","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 0-07a","LIT 0-16a"],"title":"Asking questions about stories","intention":"We are learning to ask and answer questions about stories, and link them to what we already know.","criteria":["I can ask and answer questions about a story to show I understand it.","I can make a simple prediction about what might happen.","I can link a story to something I already know or have done."],"steps":{"start":"Show the cover. What do you think will happen? Have you ever been somewhere like this?","teach":"Read or listen to a short story. Model asking a question (\"I wonder why…\"), then let the child ask one. Stop before the end: what will happen next? Afterwards, link it to their life: has that ever happened to you?","practise":"Read a story and answer its questions, then listen to a story and answer.","check":"Ask one who, one what and one why question, and ask them to ask you one about the story."},"use":["r-bus","lc-shell-shop"],"home":"At story time, ask your child to ask you a question about the story.","vocab":"question, ask, answer, predict, I wonder, remember","understand":"What question would you ask the character? Why?","lookFor":"Asks a real question about the story, and links it to something they know or have done."},
    {"id":"lesson-early-sharing-my-news-and-new-words","level":"Early","subject":"Literacy","strand":"Listening and talking","codes":["LIT 0-09a","LIT 0-10a"],"title":"Sharing my news and new words","intention":"We are learning to share our experiences, feelings and ideas, and to use new words we have learned.","criteria":["I can talk clearly to others, sharing my feelings, ideas and thoughts.","I can tell about something that happened in the right order.","I can share ideas in play and pretend situations.","I can use new words and phrases I have learned."],"steps":{"start":"Share some news of your own in three parts: first, then, at the end. How did it make you feel?","teach":"The child shares their news, using first, then and at the end. Teach two or three new words that fit it (for example delighted, enormous, crowded) and use them back. Then act out a pretend situation, such as a shop or a vet, where they explain what they want.","practise":"The \"My news\" sheet: draw the news in order, then tell it to an adult using a new word.","check":"Ask them to tell you about something they did, in order, using at least one new word."},"use":[],"home":"At teatime, ask about the day: what happened first, next and at the end?","vocab":"news, first, then, at the end, feeling, new word","understand":"Tell me your news again, using our new word.","lookFor":"Tells events in order and uses the new word correctly, in a way that fits."},
    {"id":"lesson-early-finding-information-in-signs-and-books","level":"Early","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 0-14a"],"title":"Finding information in signs and books","intention":"We are learning to find useful information in signs, books and other texts, and use it.","criteria":["I can find information in a sign, book or other text to learn something new.","I can tell a storybook from an information book.","I can use what I find to make a choice or a plan."],"steps":{"start":"Show a sign (a toilet sign, a shop sign, an exit). What does it tell us? How do you know?","teach":"Put a storybook beside an information book. How are they different (photographs, labels, facts)? Find one fact in the information book together. Then read a simple poster or menu and use it to choose or plan something.","practise":"The \"Find it!\" sheet: read a poster and a menu with an adult, find the information and make a choice.","check":"Show a new sign or a page of an information book. What does it tell us? What could we do with that?"},"use":[],"home":"Point out signs on a walk or in a shop, and ask what each one tells you.","vocab":"sign, information, fact, label, storybook, information book","understand":"How did this sign or page help us? What can we do now we know that?","lookFor":"Explains what the information tells them and uses it to choose or plan something."},
    {"id":"lesson-first-silent-e-a-e-i-e-o-e-u-e","level":"First","subject":"Literacy","strand":"Reading: phonics and tricky words","codes":["ENG 1-12a","LIT 1-13a","LIT 1-21a"],"title":"Silent e: a–e, i–e, o–e, u–e","intention":"We are learning to read and spell words with a split vowel sound.","criteria":["I can decode words with familiar letter patterns.","I can spell words with split vowel sounds using what I know about phonics."],"steps":{"start":"Read cap, then cape. What changed?","teach":"Show how the e at the end changes the vowel sound (hop → hope). Map the sounds: c-a_e-k. Sort words by short and long vowel.","practise":"Sound Hopper: long a, then the a–e and i–e lists.","check":"Read and spell five words with a split vowel."},"use":["g-hopper-long-a","a-e","i-e"],"home":"Find words with a magic e in a book.","vocab":"vowel, long vowel, split digraph, silent e","understand":"What does the e do in hope? Read hop and hope.","lookFor":"Explains the e changes the vowel sound, and reads both correctly."},
    {"id":"lesson-first-vowel-teams-ai-ee-oa-igh","level":"First","subject":"Literacy","strand":"Reading: phonics and tricky words","codes":["ENG 1-12a","LIT 1-13a","LIT 1-21a"],"title":"Vowel teams: ai, ee, oa, igh","intention":"We are learning to read and spell words with vowel teams.","criteria":["I can decode words with vowel teams.","I can choose a sensible spelling for a long vowel sound."],"steps":{"start":"Say rain, tree, boat, night. What sound is in the middle of each?","teach":"Show each team as one sound tile. Map r-ai-n, t-r-ee. Talk about ai in the middle and ay at the end of words.","practise":"The ai and ee lists.","check":"Read and spell train, sheep, coat, light."},"use":["ai","ee"],"home":"Spot vowel teams on cereal boxes and signs.","vocab":"vowel team, long vowel sound","understand":"How do you know whether to write ai or ay?","lookFor":"Knows ay usually comes at the end of a word and ai in the middle."},
    {"id":"lesson-first-vowels-with-r-ar-or-er-ir-ur","level":"First","subject":"Literacy","strand":"Reading: phonics and tricky words","codes":["ENG 1-12a","LIT 1-21a"],"title":"Vowels with r: ar, or, er, ir, ur","intention":"We are learning to read and spell words where r changes the vowel.","criteria":["I can read words with ar, or, er, ir and ur.","I can choose between er, ir and ur, and check spellings in a word list."],"steps":{"start":"Say car, fork, her, bird, fur.","teach":"Show each spelling. Sort words into er, ir and ur. Build a reminder list for tricky ones.","practise":"Sound Hopper: r sounds, then the ar list.","check":"Read and spell star, storm, girl, turn."},"use":["g-hopper-r","ar"],"home":"Play 'r sound' I spy around the house.","vocab":"vowel, r sound","understand":"Bird, her and turn all have the same sound. Why are they spelled differently?","lookFor":"Knows one sound can be written in more than one way, and learns which way each word uses."},
    {"id":"lesson-first-common-words-and-spelling-strategies","level":"First","subject":"Literacy","strand":"Spelling","codes":["LIT 1-21a"],"title":"Common words and spelling strategies","intention":"We are learning to spell common words and use strategies for tricky ones.","criteria":["I can spell most commonly used words.","I can use phonics and spelling strategies for new words.","I can use alphabetical order to find a word in a dictionary or word list."],"steps":{"start":"Try to spell 'because'. Which part is tricky?","teach":"Look, say, cover, write, check. Split words into syllables (be-cause). Practise alphabetical order with first and second letters, then find words in a dictionary.","practise":"The Tricky words list.","check":"Spell five common words. Put five words in alphabetical order."},"use":["tricky"],"home":"Practise three tricky words a day with look, say, cover, write, check.","vocab":"spelling, syllable, alphabetical order, dictionary","understand":"You're stuck on a word. What could you try?","lookFor":"Names a strategy: sound it out, think of a word like it, write it and check if it looks right."},
    {"id":"lesson-first-reading-aloud-with-expression","level":"First","subject":"Literacy","strand":"Reading: phonics and tricky words","codes":["ENG 1-12a","LIT 1-13a"],"title":"Reading aloud with expression","intention":"We are learning to read aloud fluently and with expression.","criteria":["I can read a familiar text aloud with expression.","I can work out new words using letter patterns and context.","I use punctuation to help me read with meaning."],"steps":{"start":"Read 'Help!' in a calm voice, then a frightened one. Which fits?","teach":"Model reading a page with expression. Show how question marks and exclamation marks change your voice. Show how to work out a new word from its sounds and the sentence.","practise":"Read a story by yourself, then answer the questions.","check":"Read a short passage aloud and explain how a word was worked out."},"use":["s-d-gull","s-d-boat"],"home":"Take turns reading pages aloud, using funny voices for characters.","vocab":"expression, fluency, punctuation, context","understand":"Why did you change your voice there?","lookFor":"Links expression to the punctuation or a character's feelings."},
    {"id":"lesson-first-answering-questions-about-a-text","level":"First","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 1-16a","ENG 1-17a","ENG 1-19a"],"title":"Answering questions about a text","intention":"We are learning to answer literal, inferential and evaluative questions.","criteria":["I can find the main ideas of a text.","I can answer questions where the answer is in the text and where I have to think.","I can tell fact from opinion.","I can share ideas about characters and the writer's message."],"steps":{"start":"What's the difference between 'What colour was the kite?' and 'How did Jake feel?'","teach":"Read a passage. Ask a 'right there' question, a 'think and search' question, and an 'on my own' question. Show how to find evidence in the text.","practise":"Read the story, then answer the questions.","check":"Ask one question of each kind and ask them to point to the evidence."},"use":["r-kite","r-rain"],"home":"Ask 'why do you think…?' questions about books.","vocab":"main idea, fact, opinion, character, evidence","understand":"How do you know? Show me the words that tell you.","lookFor":"Points to evidence in the text, not just memory."},
    {"id":"lesson-first-finding-information-and-making-notes","level":"First","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 1-14a","LIT 1-15a"],"title":"Finding information and making notes","intention":"We are learning to find key information and make notes.","criteria":["I can find key information using contents, headings and pictures.","I can make notes under headings and use them."],"steps":{"start":"How would you find out about sharks in a book?","teach":"Show contents, headings and captions. Read a short non-fiction page and make notes under 'where they live', 'what they eat'.","practise":"Read a passage and fill in notes under three headings.","check":"Use notes to tell three facts about the topic."},"use":["r-storm"],"home":"Read a leaflet or website together to find one fact.","vocab":"contents, heading, caption, notes, fact","understand":"Why didn't you copy the whole sentence?","lookFor":"Explains notes keep the key words only."},
    {"id":"lesson-first-full-stops-question-marks-and-exclamation-marks","level":"First","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 1-22a"],"title":"Full stops, question marks and exclamation marks","intention":"We are learning to punctuate the ends of sentences.","criteria":["I can start sentences with a capital letter.","I can end sentences with a full stop, question mark or exclamation mark."],"steps":{"start":"Read 'where is my bag' — what's missing?","teach":"Show a statement, a question and an exclamation. Read each aloud with the right voice. Fix sentences with missing punctuation.","practise":"Full stop, question mark or exclamation mark?, then Capital letters and full stops.","check":"Write a question, a statement and an exclamation."},"use":["w-end-marks","w-capitals"],"home":"Write a note with a question in it for someone at home.","vocab":"capital letter, full stop, question mark, exclamation mark","understand":"\"You're going home.\" \"You're going home?\" \"You're going home!\" How does each mark change what it means?","lookFor":"Explains how the end mark changes the meaning or how it's said, and chooses the right mark for a new sentence of their own."},
    {"id":"lesson-first-joining-sentences-and-but-because-so","level":"First","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 1-22a"],"title":"Joining sentences: and, but, because, so","intention":"We are learning to link ideas with conjunctions.","criteria":["I can link sentences with and, but, because and so.","I can start sentences in different ways."],"steps":{"start":"'I was hungry. I ate a sandwich.' Join them with one word.","teach":"Show how each joining word changes meaning. Practise finishing sentence starters. Try different openers: Then, After that, Suddenly.","practise":"Joining words: and, but, because, so.","check":"Write two sentences joined with because, and one with a new opener."},"use":["w-joining"],"home":"Play 'because' — say a sentence and add a reason.","vocab":"conjunction, join, because, but, so, and, opener","understand":"What's the difference between \"I was cold so I wore a coat\" and \"I was cold but I wore a coat\"?","lookFor":"Explains so gives a result and but shows a contrast."},
    {"id":"lesson-first-past-tense-and-checking-my-writing","level":"First","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 1-22a","LIT 1-23a"],"title":"Past tense, and checking my writing","intention":"We are learning to write in the past tense and check our writing makes sense.","criteria":["I can add -ed to show something happened in the past.","I can check my writing makes sense and correct it."],"steps":{"start":"Today I jump. Yesterday I…?","teach":"Show adding -ed. Write three sentences about yesterday. Read them back to check they make sense and fix one mistake.","practise":"Past tense: adding -ed.","check":"Write two past-tense sentences and correct a sentence with a mistake."},"use":["w-past-ed"],"home":"Talk about what happened today using past-tense words.","vocab":"past tense, -ed, check, edit","understand":"How do you know this sentence is about the past?","lookFor":"Points to the past-tense verbs, and spots one that doesn't match."},
    {"id":"lesson-first-dictation-spelling-and-punctuation-together","level":"First","subject":"Literacy","strand":"Writing: dictation","codes":["LIT 1-21a","LIT 1-22a"],"title":"Dictation: spelling and punctuation together","intention":"We are learning to write a whole sentence we hear, with correct spelling and punctuation.","criteria":["I can spell the words in a sentence using what I know.","I can punctuate the sentence accurately."],"steps":{"start":"Spell three words from this week's list.","teach":"Say a sentence twice. Count the words. Write it, then check capital letter, spellings and full stop together.","practise":"Sentence dictation.","check":"Dictate one new sentence and mark it together."},"use":["dictate:ai"],"home":"Dictate a short sentence for your child to write.","vocab":"dictation, sentence, capital letter, full stop","understand":"Read your sentence back. What did you check?","lookFor":"Checks capital letter, spellings and full stop without being told."},
    {"id":"lesson-first-planning-and-writing-a-recount","level":"First","subject":"Literacy","strand":"Writing: creating texts","codes":["LIT 1-26a","ENG 1-30a"],"title":"Planning and writing a recount","intention":"We are learning to plan and write about something that happened to us.","criteria":["I can plan my ideas using a simple format.","I can write about an experience in a logical order.","I can use interesting words."],"steps":{"start":"Tell me about a day out. What happened first?","teach":"Plan with four boxes: who, where, what happened, how I felt. Use time words (first, next, after that, finally). Write it up from the plan.","practise":"Write a short recount from the plan.","check":"Check the order is clear and there are time words."},"use":[],"home":"Keep a weekend diary together.","vocab":"recount, plan, order, time words","understand":"Why does a recount need time words?","lookFor":"Explains they show the order things happened in."},
    {"id":"lesson-first-writing-a-story-with-characters-and-a-setting","level":"First","subject":"Literacy","strand":"Writing: creating texts","codes":["ENG 1-31a","LIT 1-28a"],"title":"Writing a story with characters and a setting","intention":"We are learning to write a story with a clear structure.","criteria":["I can create a story with a beginning, middle and end.","I can describe a character's feelings and actions.","I can describe where it happens."],"steps":{"start":"Who could be the main character? Where could it happen?","teach":"Plan a story mountain: opening, problem, solution, ending. Describe the character with feelings and actions, not just looks.","practise":"Write the opening and the problem of the story.","check":"Point to the opening, problem and ending, and a feeling word."},"use":[],"home":"Make up stories with toys and write one down.","vocab":"character, setting, beginning, problem, ending","understand":"How did you show your character was scared, without saying \"scared\"?","lookFor":"Points to actions, words or feelings that show it."},
    {"id":"lesson-first-listening-for-main-ideas-and-fact-or-opinion","level":"First","subject":"Literacy","strand":"Listening and talking","codes":["LIT 1-04a","LIT 1-07a","LIT 1-08a","LIT 1-09a"],"title":"Listening for main ideas, and fact or opinion","intention":"We are learning to listen for main ideas and tell fact from opinion.","criteria":["I can find the purpose and main ideas of something I hear.","I can answer different types of questions about it.","I can tell simple facts from opinions."],"steps":{"start":"'Dogs have four legs.' 'Dogs are the best pets.' Which is a fact?","teach":"Listen to a short recording or story. Note three main ideas. Sort statements into fact or opinion.","practise":"Listen to the story, then answer the questions.","check":"Retell the main idea and give one fact and one opinion."},"use":["lc-bus"],"home":"Listen to a radio clip or audiobook together and talk about it.","vocab":"main idea, purpose, fact, opinion","understand":"Is \"dogs are the best pets\" a fact or an opinion? How do you know?","lookFor":"Explains an opinion can't be proved true; a fact can be checked."},
    {"id":"lesson-first-clear-legible-handwriting","level":"First","subject":"Literacy","strand":"Handwriting","codes":["LIT 1-24a"],"title":"Clear, legible handwriting","intention":"We are learning to present writing clearly for a reader.","criteria":["I can write clearly so others can read it.","I can lay out my work neatly, using pictures or headings where they help."],"steps":{"start":"Look at two pieces of writing. Which is easier to read? Why?","teach":"Practise letters on four-line ruling, with even size and spacing. Copy a short piece neatly with a heading.","practise":"Handwriting sheet for this week's spelling list.","check":"Copy a sentence neatly with even spacing."},"use":["handwriting-spacing"],"home":"Write a birthday card in best handwriting.","vocab":"handwriting, spacing, size, neat, legible","understand":"Why does it matter that your letters are the right size?","lookFor":"Explains it helps a reader read it easily."},
    {"id":"lesson-first-choosing-texts-and-explaining-why","level":"First","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 1-01a","LIT 1-11a","LIT 1-20a"],"title":"Choosing texts and explaining why","intention":"We are learning to choose texts we enjoy, explain why, and choose how to make our own.","criteria":["I can choose texts to listen to, watch or read, for enjoyment or to find something out.","I can use the cover, title, author, illustrator or blurb to help me choose.","I can explain why I prefer certain texts and authors.","I can choose my own subject, purpose and format when I create a text."],"steps":{"start":"What's the best book, programme or podcast you've read, watched or listened to lately? What made it good?","teach":"Look at three books together. Use the cover, title, author and blurb to predict what each is like, then choose one and explain why. Talk about favourite authors and what they have in common. Then plan a text of their own choice: what will it be about, who is it for, and will it be a poster, a comic, a story or a letter?","practise":"The \"My choices\" sheet: a reading and listening log with reasons, then a plan for a text of their own choosing.","check":"Ask them to recommend a text to you and give two reasons. Ask why they chose the format for their own text."},"use":[],"home":"Keep a list of books and programmes your child enjoys, and talk about why.","vocab":"choose, prefer, author, blurb, genre, format, recommend","understand":"Why would you recommend that book to a friend, and not this one?","lookFor":"Gives reasons about the text itself (the author's style, the topic, the pictures), comparing the two."},
    {"id":"lesson-first-listening-and-talking-in-a-group","level":"First","subject":"Literacy","strand":"Listening and talking","codes":["LIT 1-02a","ENG 1-03a","LIT 1-10a"],"title":"Listening and talking in a group","intention":"We are learning when and how to listen and talk with others, and to talk clearly so others are interested.","criteria":["I can take turns and talk at the right time.","I can listen and respond respectfully, for example by nodding, agreeing, asking and answering questions.","I can use eye contact, expression and body language to engage others.","I can speak clearly and audibly, choosing objects or pictures to help if I need them."],"steps":{"start":"Say \"I like pizza\" in a bored voice, then in an excited voice. Which is more interesting to listen to? Why?","teach":"Agree the rules for talking together: one speaker at a time, look at the speaker, wait for a pause, ask a question that fits. Discuss a simple question together (Should we have school on Saturdays?). Model pace, expression and gesture, then the pupil explains something to you with an object or picture to help.","practise":"The \"Talking together\" sheet: a short talk about a chosen object, and a checklist for how the talk went.","check":"Have a two-minute conversation. Do they wait their turn, respond to what you said and speak clearly?"},"use":[],"home":"Play a game of \"tell me about it\" at dinner: everyone takes a turn and asks one question.","vocab":"turn, listen, respond, eye contact, expression, gesture, clearly","understand":"What did I just say? What would be a good question to ask me about it?","lookFor":"Sums up what you said and asks a question that follows on from it."},
    {"id":"lesson-first-notes-from-listening-then-using-them","level":"First","subject":"Literacy","strand":"Listening and talking","codes":["LIT 1-05a","LIT 1-06a","LIT 1-25a"],"title":"Notes from listening, then using them","intention":"We are learning to make notes under headings as we listen, then use them to create something new.","criteria":["I can find the purpose and main ideas of something I listen to or watch.","I can make notes under given headings.","I can use my notes to put ideas in a logical order and create a new text."],"steps":{"start":"Listen to two sentences about hedgehogs. Which words are the most important to remember?","teach":"Explain notes are key words, not whole sentences. Read the short talk on the adult's sheet aloud twice. The first time, just listen for the main idea. The second time, write key words under the headings. Then turn the notes into three sentences, in order, for someone who didn't hear it.","practise":"The \"Notes from listening\" sheet: notes under headings while the adult reads, then sentences from the notes.","check":"From their notes alone, can they tell you the main ideas in a sensible order?"},"use":[],"home":"Listen to the weather or a short news clip and jot down three key words together.","vocab":"notes, heading, key word, main idea, purpose, order","understand":"Why are notes just key words? Could someone else understand your notes?","lookFor":"Explains notes save time and keep the main ideas; uses them to retell in order."},
    {"id":"lesson-first-fact-and-opinion-in-what-i-read","level":"First","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 1-18a"],"title":"Fact and opinion in what I read","intention":"We are learning to recognise the difference between fact and opinion in what we read.","criteria":["I can tell a fact from an opinion in a text.","I can explain how I know: a fact can be checked, an opinion is what someone thinks.","I can spot words that often show an opinion, such as best, I think and should."],"steps":{"start":"\"Penguins are birds.\" \"Penguins are the cutest animals.\" Which one could we check in a book?","teach":"Read a short text about an animal or place. Underline the facts in one colour and the opinions in another. Collect opinion words (best, worst, I think, amazing, should). Ask: why might a writer put opinions in?","practise":"The \"Fact or opinion? Penguins\" sheet: sort sentences from a short text, then write one fact and one opinion of their own.","check":"Give three new sentences. Which are facts and which are opinions, and how do they know?"},"use":[],"home":"Spot facts and opinions on food packets and adverts together.","vocab":"fact, opinion, true, check, think, believe","understand":"Is \"Edinburgh is the best city\" a fact or an opinion? How could you check?","lookFor":"Explains it's an opinion because it can't be checked; a fact can be found in a reliable book."},
    {"id":"lesson-first-writing-to-share-information-or-an-opinion","level":"First","subject":"Literacy","strand":"Writing: creating texts","codes":["LIT 1-29a"],"title":"Writing to share information or an opinion","intention":"We are learning to write to give information, describe something, share our opinion or persuade.","criteria":["I can choose and organise information and share it in different ways.","I can use words that suit what I'm writing for.","I can give my own opinion and try to persuade the reader."],"steps":{"start":"Show a poster and an information leaflet. What is each one trying to do?","teach":"Choose a topic the pupil knows well (a pet, a game, a place). First write two or three facts to inform. Then write their opinion with a reason, and add one sentence to persuade the reader (You should… because…). Talk about how the words change between informing and persuading.","practise":"The \"Inform or persuade\" sheet: facts in one box, an opinion and reasons in another, then a short poster.","check":"Can they tell you which sentences inform and which persuade, and why?"},"use":[],"home":"Make a poster together for something at home: a family film night, or a room tidy rota.","vocab":"inform, describe, opinion, persuade, reason, because, should","understand":"Which of your sentences informs, and which persuades? How can you tell?","lookFor":"Points to facts that inform and to reasons and \"you should\" that persuade."},
    {"id":"lesson-second-spelling-rules-ing-plurals-and-endings","level":"Second","subject":"Literacy","strand":"Spelling","codes":["LIT 2-21a"],"title":"Spelling rules: -ing, plurals and endings","intention":"We are learning to apply spelling rules to spell most words correctly.","criteria":["I can apply spelling rules for -ing and plurals.","I can self-correct using spelling strategies."],"steps":{"start":"Spell 'running' and 'hoping'. Why is one doubled?","teach":"Teach the rules: double the consonant after a short vowel (run → running), drop the e (hope → hoping), add -es after s, x, sh, ch. Check a piece of writing for errors.","practise":"The Adding -ing and Plurals lists.","check":"Spell five words with endings and explain one rule."},"use":["ing","s-es"],"home":"Spot rule-breakers in a book and talk about them.","vocab":"rule, suffix, plural, double, self-correct","understand":"Why does hop become hopping but jump becomes jumping?","lookFor":"Explains doubling after a short vowel with one consonant."},
    {"id":"lesson-second-tricky-spelling-patterns-soft-c-and-g-silent-letters-ph","level":"Second","subject":"Literacy","strand":"Spelling","codes":["LIT 2-21a"],"title":"Tricky spelling patterns: soft c and g, silent letters, ph","intention":"We are learning to spell words with tricky letter patterns.","criteria":["I can use spelling patterns and rules for soft c and g, silent letters and ph.","I can use resources to check spellings."],"steps":{"start":"Why does 'c' sound different in 'cat' and 'city'?","teach":"Show c and g are soft before e, i or y. Show silent k and w (knock, write) and ph making /f/. Use a dictionary to check.","practise":"The Soft c and soft g, Silent letters and ph lists.","check":"Spell city, giant, knee, wrist, phone."},"use":["soft-c-g","kn-wr","ph"],"home":"Make a family list of words with silent letters.","vocab":"soft c, soft g, silent letter, pattern","understand":"Here are words you haven't practised: cycle, cell, giant. How would you say each one, and why?","lookFor":"Applies the soft c and soft g patterns (before e, i or y) to new words and explains them; knows some words, such as get and girl, break the pattern."},
    {"id":"lesson-second-reading-fluently-with-pace-and-expression","level":"Second","subject":"Literacy","strand":"Reading: phonics and tricky words","codes":["ENG 2-12a","LIT 2-13a"],"title":"Reading fluently, with pace and expression","intention":"We are learning to read unfamiliar texts fluently and with understanding.","criteria":["I can read with fluency, understanding and expression.","I use context clues, punctuation, grammar and layout to read unfamiliar texts."],"steps":{"start":"Read a sentence with no punctuation. Then with it. What changes?","teach":"Model reading a passage at the right pace. Show how commas and dialogue change reading. Work out unfamiliar words from context.","practise":"Read the story, then answer the questions.","check":"Read a passage aloud and explain an unfamiliar word using context."},"use":["r-puppy","s-d-puddle"],"home":"Read aloud to a younger child or a pet.","vocab":"fluency, pace, expression, context","understand":"How did the way you read help a listener understand?","lookFor":"Links pace, pauses and emphasis to the meaning."},
    {"id":"lesson-second-inference-reading-between-the-lines","level":"Second","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 2-16a","ENG 2-17a","ENG 2-19a"],"title":"Inference: reading between the lines","intention":"We are learning to make inferences and support them with evidence.","criteria":["I can answer literal, inferential and evaluative questions.","I can find the main ideas with supporting detail.","I can comment on characters, setting and the writer's language."],"steps":{"start":"'She slammed the door.' How is she feeling? How do you know?","teach":"Read a passage. Model 'I think… because the text says…'. Find clues about a character's feelings. Comment on a word choice and its effect.","practise":"Read the story, then answer the questions.","check":"Answer an inference question and give the evidence."},"use":["r-puppy","s-d-phone"],"home":"Ask 'how do you know?' when talking about books.","vocab":"infer, evidence, clue, character, setting, word choice","understand":"The text doesn't say it. What makes you think so?","lookFor":"Gives a clue from the text and explains what it suggests."},
    {"id":"lesson-second-fact-opinion-and-persuasion","level":"Second","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 2-16a","LIT 2-18a"],"title":"Fact, opinion and persuasion","intention":"We are learning to spot fact, opinion and techniques used to persuade.","criteria":["I can tell fact from opinion and explain why.","I can spot word choice and techniques used to influence readers.","I can judge which sources are most reliable."],"steps":{"start":"Look at an advert. What does it want you to do?","teach":"Sort statements into fact and opinion. Highlight persuasive words in an advert. Compare two sources on one topic: which is more reliable and why?","practise":"Highlight facts and opinions in a short persuasive text.","check":"Give one fact, one opinion and one persuasive technique from the text."},"use":[],"home":"Talk about adverts on TV: what tricks are they using?","vocab":"fact, opinion, persuade, reliable, source, bias","understand":"Why might an advert use opinions and not just facts?","lookFor":"Explains opinions persuade, and that facts can be chosen to suit the writer."},
    {"id":"lesson-second-skimming-scanning-and-notes-in-own-words","level":"Second","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 2-14a","LIT 2-15a"],"title":"Skimming, scanning and notes in own words","intention":"We are learning to skim, scan and make notes in our own words.","criteria":["I can skim to find the purpose and main ideas.","I can scan for key information.","I can make notes in my own words and use them to write."],"steps":{"start":"Find the date in this leaflet as fast as you can.","teach":"Show skimming (first lines, headings) and scanning (looking for a key word). Turn a paragraph into three bullet-point notes in your own words.","practise":"Make notes from a short non-fiction text, then write a summary.","check":"Write a two-sentence summary from the notes."},"use":["r-storm"],"home":"Find information for a family trip from a website.","vocab":"skim, scan, notes, summary, own words","understand":"When would you skim, and when would you scan?","lookFor":"Skim for the gist, scan for a specific detail, with an example of each."},
    {"id":"lesson-second-commas-speech-marks-and-apostrophes","level":"Second","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 2-22a"],"title":"Commas, speech marks and apostrophes","intention":"We are learning to use a range of punctuation accurately.","criteria":["I can use commas in lists and after openers.","I can punctuate speech with speech marks.","I can use apostrophes for contractions and possession."],"steps":{"start":"Punctuate: I bought eggs milk bread and jam.","teach":"Show commas in lists. Model setting out speech: \"Look out!\" shouted Sam. Show apostrophes in don't and the dog's bone.","practise":"Correct the punctuation in five sentences, then write a short conversation.","check":"Punctuate a sentence of speech and one with a possessive apostrophe."},"use":[],"home":"Spot speech marks in a book and read the dialogue in character.","vocab":"comma, speech marks, inverted commas, apostrophe, possession","understand":"What's the difference between the girl's coats and the girls' coats?","lookFor":"Explains one owner vs. more than one owner."},
    {"id":"lesson-second-varying-sentences-and-using-paragraphs","level":"Second","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 2-22a","LIT 2-23a"],"title":"Varying sentences and using paragraphs","intention":"We are learning to vary sentences and organise writing into paragraphs.","criteria":["I can use sentences of different lengths and types.","I can vary sentence openings and link sentences with a range of conjunctions.","I can use paragraphs to separate ideas.","I can review and correct my writing."],"steps":{"start":"Make this more interesting: 'The dog ran. The dog barked.'","teach":"Show short sentences for effect, longer ones with although, while, since. Plan three paragraphs on a topic. Edit a paragraph together.","practise":"Joining words, then write and edit a three-paragraph piece.","check":"Point to a short sentence, a long sentence and a new paragraph."},"use":["w-joining"],"home":"Write a short review of a film in three paragraphs.","vocab":"sentence, conjunction, opener, paragraph, edit","understand":"Why did you start a new paragraph here?","lookFor":"Gives a reason: new time, place, person or idea."},
    {"id":"lesson-second-dictation-longer-sentences","level":"Second","subject":"Literacy","strand":"Writing: dictation","codes":["LIT 2-21a","LIT 2-22a"],"title":"Dictation: longer sentences","intention":"We are learning to write longer dictated sentences accurately.","criteria":["I can spell most words correctly using rules and strategies.","I can punctuate sentences accurately, including commas."],"steps":{"start":"Spell five words from the soft c and g list.","teach":"Say a sentence twice. Write it. Check spellings, capital letter, commas and full stop. Correct mistakes using a word list.","practise":"Sentence dictation.","check":"Dictate one new sentence and mark it together."},"use":["dictate:soft-c-g"],"home":"Dictate a sentence from a favourite book.","vocab":"dictation, spelling, punctuation, check","understand":"Which part was hardest to remember, and how did you hold it in your head?","lookFor":"Uses a strategy: repeating it, chunking it, saying it while writing."},
    {"id":"lesson-second-writing-to-inform-or-persuade","level":"Second","subject":"Literacy","strand":"Writing: creating texts","codes":["LIT 2-26a","LIT 2-28a","LIT 2-29a"],"title":"Writing to inform or persuade","intention":"We are learning to write an information text or a persuasive piece.","criteria":["I can plan and organise information logically.","I can use an introduction and a conclusion.","I can use language to persuade, such as word choice and questions to the reader."],"steps":{"start":"Should children have longer playtimes? Give one reason.","teach":"Plan with a box for each point and a piece of evidence. Model an introduction, linking phrases (firstly, furthermore, however) and a conclusion.","practise":"Write a persuasive letter or an information leaflet from the plan.","check":"Find the introduction, two linking phrases and the conclusion."},"use":[],"home":"Write a persuasive note asking for a family treat.","vocab":"inform, persuade, introduction, conclusion, linking phrase, evidence","understand":"Who is your reader, and how did that change what you wrote?","lookFor":"Links word choice and tone to the audience and purpose."},
    {"id":"lesson-second-writing-a-story-plot-character-and-setting","level":"Second","subject":"Literacy","strand":"Writing: creating texts","codes":["ENG 2-27a","ENG 2-30a","ENG 2-31a"],"title":"Writing a story: plot, character and setting","intention":"We are learning to write a story with convincing characters and a clear plot.","criteria":["I can create interesting characters through their feelings and actions.","I can describe a setting with detail.","I can use figurative language such as similes.","I can structure a plot with an opening, turning point and ending."],"steps":{"start":"Describe this picture of a forest using your five senses.","teach":"Plan a plot with a turning point. Show characterisation through actions and speech. Add a simile or metaphor to describe the setting.","practise":"Write the opening paragraph and the turning point.","check":"Point to a description of feelings, a simile and the turning point."},"use":[],"home":"Read a story together and talk about how the writer builds tension.","vocab":"plot, character, setting, simile, metaphor, turning point","understand":"How does the setting add to the mood of your story?","lookFor":"Points to description that creates atmosphere and fits what happens."},
    {"id":"lesson-second-planning-and-giving-a-short-talk","level":"Second","subject":"Literacy","strand":"Listening and talking","codes":["LIT 2-09a","LIT 2-10a"],"title":"Planning and giving a short talk","intention":"We are learning to plan and deliver a short talk.","criteria":["I can plan an organised talk with relevant content.","I can speak clearly, audibly and with expression.","I can use vocabulary that suits my audience."],"steps":{"start":"What makes a good speaker? Think of someone you like listening to.","teach":"Plan a two-minute talk on a hobby: opening, three points, ending. Practise eye contact, volume and pace.","practise":"Give the talk and answer one question.","check":"Did it have an opening, three points and an ending? Was it clear?"},"use":[],"home":"Give your talk to the family at teatime.","vocab":"talk, audience, eye contact, volume, pace","understand":"What did you do to keep your audience interested?","lookFor":"Names techniques: a question, an example, eye contact, changing their voice."},
    {"id":"lesson-second-choosing-texts-and-authors-and-writing-my-own-choice","level":"Second","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 2-01a","LIT 2-11a","LIT 2-20a"],"title":"Choosing texts and authors, and writing my own choice","intention":"We are learning to choose texts for enjoyment or information, explain our preferences with detail, and choose the right form for our own writing.","criteria":["I can choose texts to read, listen to or watch, for enjoyment or to find information for a purpose.","I can explain my preferences for texts, authors or sources with supporting detail.","I can choose the genre, form, structure and style of my own texts to suit my purpose and audience."],"steps":{"start":"Which author or series would you recommend to a friend? Convince me in one sentence.","teach":"Compare two texts the pupil knows: what does each author do that they like (characters, humour, facts, layout)? Talk about choosing sources for information: a website, a book, a podcast. Then choose a purpose and audience for their own text and decide the best form (a review, a blog post, a comic, a set of instructions).","practise":"The \"Recommend it\" sheet: a review with evidence, then a plan for their own text with its audience and form.","check":"Ask them to justify a preference with a detail from the text, and explain why the form they chose suits the audience."},"use":[],"home":"Swap book recommendations as a family, each giving a reason.","vocab":"genre, author, source, preference, review, audience, purpose, form","understand":"Why did you choose that form for your own text?","lookFor":"Links the form and style to the audience and purpose, for example a comic for younger readers."},
    {"id":"lesson-second-group-discussion-building-on-others-ideas","level":"Second","subject":"Literacy","strand":"Listening and talking","codes":["LIT 2-02a","ENG 2-03a"],"title":"Group discussion: building on others' ideas","intention":"We are learning to take part in discussions, value others' ideas and build on them, and use features of spoken language well.","criteria":["I can contribute relevant ideas, information and opinions in a discussion.","I can show respect for others' views and offer my own.","I can build on what others say by asking or answering questions, clarifying points or supporting their ideas.","I can use vocabulary, eye contact, body language, emphasis, pace and tone when I talk, and spot techniques speakers use to influence me."],"steps":{"start":"Agree or disagree: \"Every child should learn to cook.\" Give one reason.","teach":"Teach discussion moves with sentence starters: I agree with… because…; Building on what you said…; Can you explain what you mean by…?; I see it differently because…. Discuss a question together, taking turns, and use at least three moves each. Then listen to a short persuasive speech (or perform one) and spot the techniques: emphasis, pace, tone, rhetorical questions.","practise":"The \"Discussion: building on ideas\" sheet: plan points for a discussion, use the starters, and note techniques heard.","check":"In a short discussion, do they build on what you said rather than just giving their own point?"},"use":[],"home":"Have a family debate on something light, like the best pizza topping, with everyone building on the last speaker.","vocab":"discussion, agree, disagree, build on, clarify, viewpoint, tone, emphasis, rhetorical question","understand":"How did what I said change your thinking?","lookFor":"Refers to your point and builds on it or disagrees respectfully with a reason."},
    {"id":"lesson-second-notes-from-listening-in-my-own-words","level":"Second","subject":"Literacy","strand":"Listening and talking","codes":["LIT 2-04a","LIT 2-05a","LIT 2-06a","LIT 2-25a"],"title":"Notes from listening, in my own words","intention":"We are learning to make notes in our own words as we listen, organise them, and use them to create new texts, crediting our sources.","criteria":["I can find the purpose and main ideas of something I listen to or watch, with supporting detail.","I can make relevant notes in my own words and organise them under suitable headings.","I can use my notes to create a new text for a purpose.","I can say where my information came from."],"steps":{"start":"Listen to one sentence. Write it in three words. Did you keep the meaning?","teach":"Read the short talk on the adult's sheet aloud twice. First listen for the purpose and main ideas. The second time, the pupil makes notes in their own words and chooses their own headings. Then they use the notes to write a short paragraph for a younger reader, and add where the information came from.","practise":"The \"Notes in my own words\" sheet: notes under their own headings, then a short paragraph with its source.","check":"Compare their notes to the talk: are the main ideas there, in their own words, with the source credited?"},"use":[],"home":"Watch a short documentary clip together and each jot down three facts in your own words.","vocab":"notes, own words, heading, purpose, main idea, detail, source","understand":"Why does it matter to say where your information came from?","lookFor":"Explains it shows the information can be checked and gives credit to the source."},
    {"id":"lesson-second-questions-fact-and-opinion-in-what-i-hear","level":"Second","subject":"Literacy","strand":"Listening and talking","codes":["LIT 2-07a","LIT 2-08a"],"title":"Questions, fact and opinion in what I hear","intention":"We are learning to show we understand what we hear by answering and asking different kinds of questions, and to tell fact from opinion and spot when a source is trying to influence us.","criteria":["I can answer literal, inferential and evaluative questions about something I listen to or watch.","I can ask different kinds of questions of my own.","I can tell fact from opinion and explain how I know.","I can recognise when a source is trying to influence me, and say how useful it is."],"steps":{"start":"\"Our juice is the tastiest in Scotland!\" Who might say this? Why?","teach":"Explain the three kinds of question: literal (it says so), inferential (clues tell you) and evaluative (what do you think, and why?). Read the radio advert on the adult's sheet aloud. The pupil answers one of each kind, sorts facts from opinions, and decides how the advert tries to influence the listener and whether it's a useful source.","practise":"The \"What I heard\" sheet: questions on a spoken advert, fact and opinion, and how it tries to influence.","check":"Ask them to write one literal, one inferential and one evaluative question about something they've heard."},"use":[],"home":"When an advert comes on, ask: what is it trying to make us do? Is everything in it a fact?","vocab":"literal, inferential, evaluative, fact, opinion, influence, source, reliable","understand":"Was the advert a useful source? Why or why not?","lookFor":"Weighs it up: it wants to sell, so it chooses facts and adds opinions, so check elsewhere."},
    {"id":"lesson-second-layout-and-presentation-to-engage-a-reader","level":"Second","subject":"Literacy","strand":"Writing: creating texts","codes":["LIT 2-24a"],"title":"Layout and presentation to engage a reader","intention":"We are learning to choose a layout and presentation, such as headings, bullet points, fonts, pictures and captions, that help and interest our reader.","criteria":["I can make choices about layout and presentation, on paper or on screen, to engage my reader.","I can use headings, sub-headings, bullet points, fonts, pictures and captions for a purpose.","I can explain why my layout suits my reader."],"steps":{"start":"Show the same information twice: once as one block of text, once as a page with a heading, bullet points and a picture. Which would you rather read? Why?","teach":"Name the features on a real leaflet, poster or web page: heading, sub-headings, bullet points, fonts, pictures, captions. For each, ask what it does for the reader (find things fast, see what matters most, want to read on). Plan a page for a younger reader from a plain piece of text: choose the main ideas, then the features that will show them best.","practise":"The \"Design a page\" sheet: turn a plain text into a leaflet page for a younger reader, then explain the choices. It can also be made on a computer or tablet.","check":"Ask: which feature helps your reader most, and why? Could you show the same idea a better way?"},"use":[],"home":"Look at a cereal box, a leaflet or a web page together: what makes you want to read it, and what makes it easy to find things?","vocab":"layout, presentation, heading, sub-heading, bullet point, font, caption, picture, reader","understand":"Why did you make that a heading, and not put it in the middle of a paragraph?","lookFor":"Explains each choice by what the reader needs: to find information quickly, to see what matters most, or to want to read on."},
    {"id":"lesson-third-choosing-texts-and-explaining-how-well-they-meet-my-needs","level":"Third","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 3-01a","LIT 3-11a","LIT 3-20a"],"title":"Choosing texts and explaining how well they meet my needs","intention":"We are learning to choose texts regularly, explain how well they meet our needs, and choose the form of our own texts.","criteria":["I can regularly choose texts to read, watch or listen to, for enjoyment or to find information.","I can give a personal response to a text, with reasons and evidence.","I can explain how well a text or source met my needs and expectations.","I can choose the purpose, form and style of a text of my own to suit my audience."],"steps":{"start":"What's the last thing you read, watched or listened to by choice? Would you recommend it?","teach":"Model a short review of a podcast, article or novel: what I wanted from it, what it gave me, an example or quotation as evidence, and who else it would suit. Look at ways to find more (library catalogues, author pages, review sites) and how far to trust each. Choose a form for the pupil's own text (a review, blog post, short story or report) and discuss why it suits the audience.","practise":"The \"My reading and viewing\" sheet: a log, a review with evidence, and a plan for a text of my own.","check":"Ask: did it meet your expectations? What in the text shows that?"},"use":[],"home":"Keep a reading and viewing log for a fortnight, with a line on how well each one met your needs.","vocab":"genre, review, evidence, purpose, audience, expectations, source","understand":"What would make you stop reading something halfway through?","lookFor":"Explains with reference to their own needs and expectations, such as purpose, interest or difficulty, with an example."},
    {"id":"lesson-third-discussion-contributing-building-on-others-and-respecting-other-views","level":"Third","subject":"Literacy","strand":"Listening and talking","codes":["LIT 3-02a","ENG 3-03a"],"title":"Discussion: contributing, building on others and respecting other views","intention":"We are learning to contribute to discussions with evidence, build on others' ideas, and use features of spoken language.","criteria":["I can contribute relevant ideas, knowledge or opinions with supporting evidence.","I can respond to others' views, and develop or adapt my own thinking.","I can build on others' contributions by asking, clarifying, summarising, supporting or challenging.","I can identify features of spoken language, such as body language, emphasis, pace, tone and rhetorical devices, and use them.","I can use a register that suits my purpose and audience."],"steps":{"start":"Should mobile phones be allowed in school? Give one point and a reason.","teach":"Agree discussion roles (chair, summariser, challenger). Model phrases: \"Building on that…\", \"Can you clarify…?\", \"I see it differently because…\". Watch a short clip of a debate or interview and name the features of spoken language: gesture, emphasis, pace, pauses, rhetorical questions. Compare registers by making the same point to a friend and to a head teacher.","practise":"Hold a 10-minute discussion on a real issue, using the \"Discussion: plan and reflect\" sheet before and after.","check":"Ask: when did you change or add to your thinking? Which feature of spoken language did you use on purpose?"},"use":[],"home":"Watch part of a debate or interview and note one technique each speaker uses.","vocab":"contribute, evidence, clarify, summarise, challenge, register, tone, pace, emphasis, rhetorical question","understand":"How did someone else's point change your view, even slightly?","lookFor":"Gives a specific example of adapting or developing their thinking, and acknowledges the other person's right to disagree."},
    {"id":"lesson-third-listening-for-purpose-and-main-ideas-and-making-notes","level":"Third","subject":"Literacy","strand":"Listening and talking","codes":["LIT 3-04a","LIT 3-05a","LIT 3-06a"],"title":"Listening for purpose and main ideas, and making notes","intention":"We are learning to identify the purpose and main ideas of what we hear, compare spoken texts, and make and use notes.","criteria":["I can give an accurate account of the purpose and main ideas of a spoken text, and justify it.","I can make inferences from key statements.","I can identify similarities and differences between spoken texts in content, style or language.","I can make and organise notes in my own words, selecting key information.","I can use my notes to create a new text that shows I understand the subject."],"steps":{"start":"Listen to a one-minute news item. In one sentence, what was it for?","teach":"Model notes while listening: headings, key words, abbreviations and arrows, not full sentences. Listen to two short talks on one topic (a factual report and a personal opinion) and compare purpose, content and style in a two-column table. Pick out a key statement and infer what the speaker believes. Turn the notes into a short summary for someone who missed it.","practise":"The \"Listen, note, compare\" sheet: the adult reads the two short talks aloud.","check":"Ask: what was each speaker's purpose? What did one suggest without saying it?"},"use":[],"home":"Listen to a radio or podcast item and tell someone the main points from your notes.","vocab":"purpose, main idea, infer, key statement, notes, summarise, compare","understand":"Why are notes better in your own words than copied word for word?","lookFor":"Explains that putting it in your own words shows you understood it and helps you remember it."},
    {"id":"lesson-third-commenting-on-spoken-texts-and-recognising-persuasion","level":"Third","subject":"Literacy","strand":"Listening and talking","codes":["LIT 3-07a","LIT 3-08a"],"title":"Commenting on spoken texts and recognising persuasion","intention":"We are learning to comment on what we hear with evidence, recognise persuasion, and judge our sources.","criteria":["I can comment on the content, form and style of spoken texts, with evidence.","I can identify persuasive techniques, such as word choice, emotive language, repetition, rhetorical questions and statistics.","I can comment on how reliable and useful a source is."],"steps":{"start":"Play or read out an advert. What does it want you to do? How does it try to make you?","teach":"Name persuasive techniques in a charity appeal or campaign speech: emotive words, repetition, rhetorical questions, statistics, speaking directly to \"you\". Ask of each: what effect is this meant to have on me? Compare a campaign video with a news report about the same issue: who made each, why, and which is more reliable?","practise":"The \"Spot the persuasion\" sheet: the adult reads a short campaign speech aloud.","check":"Ask: name two techniques and their effect. Is the speaker a reliable source on this? Why?"},"use":[],"home":"Watch adverts with someone and score each for how many persuasive techniques it uses.","vocab":"persuade, emotive language, repetition, rhetorical question, statistic, bias, reliable, source","understand":"A speaker uses a statistic. Does that make them right?","lookFor":"Explains that it depends on where the statistic came from and how it's used, and that statistics can be chosen to persuade."},
    {"id":"lesson-third-giving-a-talk-clear-structured-and-engaging","level":"Third","subject":"Literacy","strand":"Listening and talking","codes":["LIT 3-09a","LIT 3-10a"],"title":"Giving a talk: clear, structured and engaging","intention":"We are learning to plan and give a talk that is clear, well structured and engaging for the audience.","criteria":["I can communicate information, ideas or opinions, explain a process, and summarise or draw conclusions.","I can organise a talk in a logical order, with signposts such as topic sentences and linking phrases.","I can open and close a talk in a way that engages my audience.","I can use tone, vocabulary and non-verbal techniques to suit my audience.","I can choose resources that help my audience."],"steps":{"start":"Think of a good talk or video you've watched. What made you keep listening?","teach":"Plan a three-minute talk: a hook, three signposted points (\"Firstly…\", \"This leads to…\"), and a conclusion that sums up. Choose one resource: a picture, an object, or three slides with few words. Practise pace, pauses, eye contact and stressing key words. Give one strength and one next step.","practise":"Plan with the \"Talk planner\" sheet, rehearse, then give the talk.","check":"Ask: how did your opening grab attention? Where did you signpost a new point?"},"use":[],"home":"Give the talk to someone at home and ask them to tell you your three main points.","vocab":"hook, signpost, topic sentence, conclusion, audience, tone, pace, eye contact, resource","understand":"Why do talks need signposts more than written texts do?","lookFor":"Explains that listeners can't flick back, so they need to hear where the talk is going and when a new point starts."},
    {"id":"lesson-third-reading-fluently-and-using-reading-strategies","level":"Third","subject":"Literacy","strand":"Reading: understanding stories","codes":["ENG 3-12a","LIT 3-13a"],"title":"Reading fluently and using reading strategies","intention":"We are learning to read unfamiliar texts with fluency and expression, and to choose strategies that help us understand.","criteria":["I can read aloud with fluency, understanding and expression, at a suitable pace and tone.","I can use context clues, word roots, grammar, punctuation and text structure to understand unfamiliar texts.","I can choose strategies such as skimming, scanning, predicting, clarifying, summarising and analysing, before and as I read."],"steps":{"start":"Here's a word you may not know: benevolent. What clues help you work out what it means?","teach":"Model skimming an article for the gist, then scanning it for one fact. Work out unfamiliar words from roots (bene means well, as in benefit) and context. Read a paragraph aloud, marking pauses for punctuation and words to stress, then read it again with more expression. Stop after each paragraph to clarify anything unclear and sum it up in a sentence.","practise":"The \"Reading toolkit\" sheet.","check":"Ask: which strategy helped most, and when? Read a new paragraph aloud with expression."},"use":[],"home":"Read a newspaper article aloud to someone, then sum up each paragraph in a sentence.","vocab":"skim, scan, predict, clarify, summarise, context clue, word root, fluency, expression","understand":"When would you skim, and when would you scan?","lookFor":"Skims for the general idea of a text; scans to find a particular fact or word quickly."},
    {"id":"lesson-third-finding-summarising-and-noting-information-from-more-than-one-source","level":"Third","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 3-14a","LIT 3-15a"],"title":"Finding, summarising and noting information from more than one source","intention":"We are learning to find and sort information from different sources, summarise it, and make linked notes.","criteria":["I can find, select and sort relevant information from different sources.","I can summarise key information in my own words.","I can make and organise notes, linking ideas from more than one source.","I can use my notes to create a new text that draws on more than one source."],"steps":{"start":"You need to find out how much plastic reaches the sea each year. Where would you look first?","teach":"Use the features of non-fiction (headings, contents, index, captions, tables) to find information fast. Read two short sources on one question, mark the key points, and make linked notes in a grid: source 1, source 2, and where they agree. Write a short summary in your own words that uses both, naming the sources.","practise":"The \"Two sources\" sheet.","check":"Ask: where did the sources agree or differ? Which point in your summary came from each?"},"use":[],"home":"Research a question for a family decision on two websites, and sum up what you found.","vocab":"source, select, sort, summarise, notes, link, own words","understand":"Why use two sources and not just one?","lookFor":"Explains that comparing sources checks accuracy, shows different views and gives a fuller picture."},
    {"id":"lesson-third-close-reading-purpose-inference-and-language","level":"Third","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 3-16a","ENG 3-17a"],"title":"Close reading: purpose, inference and language","intention":"We are learning to work out purpose and main ideas, make inferences, and explain the effect of a writer's language.","criteria":["I can identify the purpose and audience of a text, and justify my answer.","I can give an accurate account of the main ideas.","I can make inferences and deductions, with evidence.","I can compare texts and comment on content, style and language.","I can answer literal, inferential and evaluative questions, and explain the effect of word choice, sentence structure, punctuation and imagery."],"steps":{"start":"\"The wind screamed through the trees.\" What is the writer doing here, and why?","teach":"Sort questions into literal (it's in the text), inferential (read between the lines) and evaluative (judge it). Model answering a language question in three steps: quote, name the technique, explain the effect. Look at a short sentence after long ones, a colon introducing a list, and a metaphor. Compare the openings of two texts on the same topic.","practise":"The \"Close reading\" sheet.","check":"Ask a question of each type about a new paragraph. Listen for the quotation, the technique and the effect."},"use":[],"home":"Choose a line from a song or an advert and explain why the writer chose those words.","vocab":"literal, inferential, evaluative, word choice, sentence structure, imagery, effect, purpose, audience","understand":"What is the difference between naming a technique and explaining its effect?","lookFor":"Explains that naming it says what the writer did; the effect says what it makes the reader think or feel, and why."},
    {"id":"lesson-third-persuasion-and-reliable-sources-in-reading","level":"Third","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 3-18a"],"title":"Persuasion and reliable sources in reading","intention":"We are learning to recognise persuasion in what we read and judge how far to trust a source.","criteria":["I can identify persuasive language, such as word choice, emotive language, repetition, rhetorical questions and statistics, and comment on it.","I can judge how reliable, relevant and useful a source is, and justify my view.","I can use this to form an informed view of my own."],"steps":{"start":"Two web pages about an energy drink: one from the company that makes it, one from a health service. Which do you trust more? Why?","teach":"Make a checklist for sources: who wrote it, why, when, what evidence it gives, and whether other sources agree. Mark the persuasive language in an article and explain its effect. Separate facts from claims. Write an informed view that weighs up both sources.","practise":"The \"Can I trust this?\" sheet.","check":"Ask: name a technique, quote it and explain how it works on the reader. How reliable is the source, and why?"},"use":[],"home":"Read the same news story on two different websites and compare how each tells it.","vocab":"persuasive, emotive, bias, reliable, credible, relevant, claim, evidence, informed view","understand":"Can a source be persuasive and reliable at the same time?","lookFor":"Explains yes: a source can argue a view and still use accurate evidence, so you judge the evidence as well as the language."},
    {"id":"lesson-third-character-setting-theme-and-the-writer-s-style","level":"Third","subject":"Literacy","strand":"Reading: understanding stories","codes":["ENG 3-19a"],"title":"Character, setting, theme and the writer's style","intention":"We are learning to evaluate character, setting and structure, identify the theme, and comment on the writer's style.","criteria":["I can make evaluative comments about structure, characterisation and setting, referring to the text.","I can identify the theme and link it to my own or others' experiences.","I can comment on the writer's style and language, and the features of the genre, with evidence."],"steps":{"start":"Think of a story you know well. Underneath the plot, what is it really about?","teach":"Read a short story or extract. Track how a character changes, with a quotation from the start, middle and end. Ask how the setting builds the mood. Put the theme into a sentence (\"Fear can stop us from…\") and connect it to real life. Comment on one feature of the writer's style, such as first-person narration, short chapters or dialogue, and its effect.","practise":"The \"Under the surface\" sheet, with any short story or novel the pupil is reading.","check":"Ask: what is the theme, and which moment shows it most clearly? Why might the writer have structured it this way?"},"use":[],"home":"Talk about a film or series at home: what's its theme, and which character changes most?","vocab":"character, characterisation, setting, mood, structure, theme, style, genre, evidence","understand":"What's the difference between the plot and the theme?","lookFor":"Explains that the plot is what happens; the theme is the bigger idea about life the story explores."},
    {"id":"lesson-third-spelling-specialist-and-tricky-words-accurately","level":"Third","subject":"Literacy","strand":"Spelling","codes":["LIT 3-21a"],"title":"Spelling specialist and tricky words accurately","intention":"We are learning to use strategies and resources to spell most words correctly, including specialist vocabulary.","criteria":["I can use a range of strategies and resources to spell most words correctly.","I can spell unfamiliar and specialist words from different subjects.","I can check and correct my own spelling."],"steps":{"start":"Spell photosynthesis, parliament, rhythm and necessary. Which strategy did you use for each?","teach":"Teach the strategies: break words into syllables (pho-to-syn-the-sis), spot roots and affixes (photo means light), use memory tricks (necessary has one collar and two sleeves: one c, two s's), and look, say, cover, write, check. Show when to use a dictionary or spellchecker, and what a spellchecker misses (their or there). Start a personal list of specialist words from the pupil's subjects.","practise":"The \"Subject spellings\" sheet: words from science, maths, social subjects and English, with a strategy for each.","check":"Say five new specialist words for the pupil to spell. Ask them to check them and explain one correction."},"use":[],"home":"Collect five tricky words from homework each week and test each other.","vocab":"syllable, root, prefix, suffix, memory trick, specialist vocabulary, proofread","understand":"Why might a spellchecker miss a mistake in 'Their going to the match'?","lookFor":"Explains that 'their' is a real word, so the checker doesn't flag it; you need to know which word the meaning needs."},
    {"id":"lesson-third-sentences-punctuation-and-paragraphs","level":"Third","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 3-22a"],"title":"Sentences, punctuation and paragraphs","intention":"We are learning to write accurate, varied sentences, use more complex punctuation, and structure writing in paragraphs.","criteria":["I can write almost all sentences in a grammatically accurate way.","I can vary my sentence structures, openings and lengths.","I can use more complex punctuation, such as colons, brackets, ellipses and inverted commas, mostly accurately.","I can use paragraphs, topic sentences and linking phrases to show the structure of my writing.","I can write fluently and legibly."],"steps":{"start":"Fix this: \"the match was cancelled, it rained all day, we went home\".","teach":"Fix run-on sentences with full stops, semicolons or conjunctions. Combine simple sentences into complex ones (\"Although it rained, …\"). Practise colons for lists and explanations, brackets for extra information, and an ellipsis for suspense. Plan three paragraphs with topic sentences, and link them (\"However,\", \"As a result,\").","practise":"The \"Sentence workshop\" sheet.","check":"Ask the pupil to write a paragraph with a topic sentence, one complex sentence, a colon and a pair of brackets."},"use":[],"home":"Write a short paragraph about your day, starting each sentence in a different way.","vocab":"simple sentence, complex sentence, run-on sentence, colon, semicolon, brackets, ellipsis, topic sentence, paragraph, linking phrase","understand":"Why is 'It rained, we went home' not a correct sentence?","lookFor":"Explains that two complete sentences need a full stop, a semicolon or a conjunction between them, not just a comma."},
    {"id":"lesson-third-editing-and-layout-that-helps-the-reader","level":"Third","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 3-23a","LIT 3-24a"],"title":"Editing, and layout that helps the reader","intention":"We are learning to review and edit our writing, and to choose layout and presentation for our reader.","criteria":["I can review and edit my writing so that it is clear, accurate and meets its purpose.","I can improve the content and language of my writing.","I can choose layout and presentation features, including in digital texts, to suit my purpose and audience."],"steps":{"start":"Read this paragraph once. Was the meaning clear first time? What got in the way?","teach":"Edit in three passes: meaning first (does it make sense, is anything missing?), then language (stronger words, no repetition), then accuracy (spelling, punctuation, grammar). Then plan a layout of the same content for a different reader, with headings, bullet points, text boxes or graphics, and explain each choice.","practise":"The \"Edit and design\" sheet.","check":"Ask: which edit improved it most? Why did you choose that layout for that reader?"},"use":[],"home":"Before sending a message or email, read it once as the person who'll receive it, and edit it.","vocab":"review, edit, proofread, clarity, layout, heading, bullet point, text box, graphic, audience","understand":"Why edit for meaning before checking spelling?","lookFor":"Explains that changing the content can remove or add sentences, so the accuracy check should come last."},
    {"id":"lesson-third-using-notes-and-sources-in-my-writing","level":"Third","subject":"Literacy","strand":"Writing: creating texts","codes":["LIT 3-25a","LIT 3-26a"],"title":"Using notes and sources in my writing","intention":"We are learning to use notes and sources to create new writing, quoting or using our own words, and acknowledging sources.","criteria":["I can use notes and other sources to generate ideas and support new writing.","I can decide when to quote from a source and when to put points in my own words.","I can acknowledge my sources.","I can select relevant ideas, information and supporting detail, and organise them in a logical order."],"steps":{"start":"Why does it matter where information came from?","teach":"Show the difference between copying, putting it in your own words and quoting, with a short source. Practise rewording a sentence, and quoting a short phrase in quotation marks. Record each source: title, author or organisation, date and web address. Sort notes into an order for a short report: introduction, two or three points with detail, and a conclusion.","practise":"The \"From notes to writing\" sheet.","check":"Ask: when did you quote and when did you use your own words, and why? Where is your list of sources?"},"use":[],"home":"Write a short fact file for a younger relative from two sources, listing them at the end.","vocab":"source, quote, quotation marks, own words, acknowledge, list of sources, plan","understand":"When is it better to quote than to use your own words?","lookFor":"Explains that a quotation is best when the exact words matter, such as a striking phrase or an expert's view; otherwise own words show understanding."},
    {"id":"lesson-third-writing-to-inform-describe-and-explain","level":"Third","subject":"Literacy","strand":"Writing: creating texts","codes":["LIT 3-28a","ENG 3-27a"],"title":"Writing to inform, describe and explain","intention":"We are learning to write clear information and explanations that suit our reader.","criteria":["I can write to convey information, describe events, or explain processes or ideas.","I can use a style and format that suit my purpose and audience, with features of the genre.","I can include relevant information and supporting detail in a logical order, with linking words.","I can use topic sentences to signpost my paragraphs.","I can engage my reader through my language, style and tone."],"steps":{"start":"How does a dishwasher get plates clean? Explain it to me in three sentences.","teach":"Read a model explanation and label its features: title, introduction, paragraphs in order with topic sentences, linking words for cause (because, as a result, this means), technical words, and a diagram. Plan an explanation of a process the pupil knows (how bike gears work, how a law is made) and write the first two paragraphs together.","practise":"The \"Explain it\" sheet: plan, then write the explanation.","check":"Ask: who is your reader, and how did you make it clear for them? Point to a topic sentence and a linking word."},"use":[],"home":"Write an explanation of something you can do that someone at home can't.","vocab":"inform, explain, process, sequence, topic sentence, linking word, technical vocabulary, format","understand":"How would your explanation change for a seven-year-old reader?","lookFor":"Explains changes to vocabulary, sentence length, examples and layout to suit the reader."},
    {"id":"lesson-third-writing-to-persuade-and-argue","level":"Third","subject":"Literacy","strand":"Writing: creating texts","codes":["LIT 3-29a"],"title":"Writing to persuade and argue","intention":"We are learning to write persuasive and argumentative texts with a clear line of thought and evidence.","criteria":["I can present a point of view with relevant supporting detail or evidence.","I can organise my ideas in a logical order, with signposts such as topic sentences and linking phrases.","I can write an introduction that makes my purpose clear and engages the reader, and a conclusion that sums up my line of thought.","I can use language to persuade, such as word choice, repetition, rhetorical questions and emotive language."],"steps":{"start":"Should the school day start later? Give your view and your best reason.","teach":"Read a model persuasive article and label its structure: hook, clear view, points with evidence, the other side and an answer to it, and conclusion. Collect evidence: a statistic, an expert, an example. Plan each paragraph as point, evidence, explain. Write the introduction and one paragraph together, using one persuasive technique on purpose.","practise":"The \"Make your case\" sheet: plan, then write the article.","check":"Ask: where is your strongest evidence? How did you answer the other side?"},"use":[],"home":"Write to your local council about something you'd like changed where you live.","vocab":"persuade, argue, point of view, evidence, counter-argument, rhetorical question, emotive language, conclusion","understand":"Why mention the other side in a persuasive text?","lookFor":"Explains that answering the opposing view makes the argument stronger and more convincing to a doubtful reader."},
    {"id":"lesson-third-writing-about-a-personal-experience","level":"Third","subject":"Literacy","strand":"Writing: creating texts","codes":["ENG 3-30a"],"title":"Writing about a personal experience","intention":"We are learning to write about a personal experience so the reader shares our feelings and reflections.","criteria":["I can set a clear context and setting for the events.","I can describe events, making my feelings and reactions clear.","I can reflect on my experience and feelings.","I can engage my reader through language, style and tone."],"steps":{"start":"Think of a time something didn't go as planned. Where were you, and how did you feel?","teach":"Read a short personal piece and find where the writer sets the scene, shows feelings (not just \"I was scared\" but what their body did), and reflects (\"Looking back, I realise…\"). Plan a timeline of the experience, with the feelings at each point. Write the opening together using details from the senses.","practise":"The \"A moment that mattered\" sheet: plan with a feelings timeline, then write.","check":"Ask: where does the reader feel what you felt? Where do you reflect on it?"},"use":[],"home":"Tell someone at home about the experience before you write, and notice which details they ask about.","vocab":"personal, reflective, setting, context, feelings, reaction, reflect, sensory detail, tone","understand":"What is the difference between telling the reader you were nervous and showing it?","lookFor":"Explains that showing uses actions, thoughts or physical details so the reader feels it, not just reads the word."},
    {"id":"lesson-third-creating-texts-in-a-genre-characters-and-settings","level":"Third","subject":"Literacy","strand":"Writing: creating texts","codes":["ENG 3-31a"],"title":"Creating texts in a genre: characters and settings","intention":"We are learning to write in a chosen genre, with convincing characters and settings that come to life.","criteria":["I can use the key features of my chosen genre.","I can create interesting and convincing characters.","I can create a clear sense of setting with descriptive detail.","I can engage the reader through the structure of my story, its mood and my language."],"steps":{"start":"Name a genre: mystery, science fiction, horror or adventure. What do readers expect from it?","teach":"List the features of the chosen genre. Build a character from the inside out: what they want, what they fear, a secret, and how they speak. Describe a setting with three senses and one detail that hints at the mood. Plan the structure: a hook, a problem, rising tension, a turning point, and an ending or cliffhanger.","practise":"The \"Story builder\" sheet: plan the genre, character and setting, then write the opening scene.","check":"Ask: which features of the genre did you use? What makes your character convincing?"},"use":[],"home":"Read the opening of a book in the same genre and compare it with yours.","vocab":"genre, convention, character, motive, setting, mood, atmosphere, structure, tension, cliffhanger","understand":"What makes a character convincing, even in science fiction?","lookFor":"Explains that believable wants, fears and reactions make a character feel real, whatever the setting."},
    {"id":"lesson-fourth-reading-widely-and-developing-my-own-style","level":"Fourth","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 4-01a","LIT 4-11a","LIT 4-20a"],"title":"Reading widely and developing my own style","intention":"We are learning to choose texts independently, justify our response with reference to the text, and make well-considered choices in our own writing.","criteria":["I can select texts regularly and independently, for enjoyment or to inform my thinking.","I can give a personal response, justifying my opinion with relevant reference to the text.","I can independently find sources to widen my reading.","I can make well-considered choices about genre, form, structure and style in my own writing, to meet my audience's needs."],"steps":{"start":"Which writer, podcaster or film-maker do you think has a style of their own? What makes it theirs?","teach":"Look at the pupil's reading and viewing over the last term: what's missing (a genre, a period, non-fiction)? Find two new sources to fill the gap, using reviews, prize lists or library recommendations. Model a short response that quotes the text to justify an opinion. Then look at one feature of a favourite writer's style and try it in a paragraph of the pupil's own.","practise":"The \"Reading with purpose\" sheet: a reading plan, a justified response, and a style experiment.","check":"Ask: what in the text supports your opinion? Which choice in your own paragraph was deliberate, and why?"},"use":[],"home":"Choose a book or long article from a genre you haven't tried, and tell someone at home whether it met your expectations.","vocab":"genre, style, voice, justify, reference, source, audience, form","understand":"What's one thing you've taken from another writer's style into your own writing?","lookFor":"Names a specific technique, gives an example from the source and from their own writing, and explains the effect they wanted."},
    {"id":"lesson-fourth-leading-and-sustaining-a-discussion","level":"Fourth","subject":"Literacy","strand":"Listening and talking","codes":["LIT 4-02a","ENG 4-03a"],"title":"Leading and sustaining a discussion","intention":"We are learning to lead and take part in discussion so everyone contributes, and to explain the effect of features of spoken language.","criteria":["I can contribute relevant ideas with convincing supporting evidence.","I can make sure everyone has a chance to contribute, and encourage people to consider other views.","I can respond positively when challenged, adapting my thinking when appropriate.","I can explore, expand on, clarify, summarise or challenge others' contributions.","I can identify features of spoken language, explain their effect, and sustain a suitable register."],"steps":{"start":"Think of a discussion that went badly. What went wrong, and what could the chair have done?","teach":"Take the chair's role: open with the question, invite quieter voices by name, summarise at intervals, and bring in the opposing view. Practise responding to a challenge without getting defensive (\"That's a fair point; I'd still argue…\"). Watch a short clip of a panel discussion and explain the effect of one speaker's pace, pauses or rhetorical questions on the listener.","practise":"Lead a 15-minute discussion, using the \"Chair's toolkit\" sheet to prepare and then to evaluate.","check":"Ask: how did you make sure every view was heard? When you were challenged, what did you do?"},"use":[],"home":"Lead a family discussion on a real decision (a holiday, a rule) and make sure everyone has a say.","vocab":"chair, contribute, evidence, challenge, summarise, expand, register, rhetorical device, effect","understand":"Why is it the chair's job to bring in views they disagree with?","lookFor":"Explains that a good discussion tests ideas against each other, and the chair makes sure all views are heard fairly."},
    {"id":"lesson-fourth-listening-comparing-texts-and-synthesising-notes","level":"Fourth","subject":"Literacy","strand":"Listening and talking","codes":["LIT 4-04a","LIT 4-05a","LIT 4-06a"],"title":"Listening: comparing texts and synthesising notes","intention":"We are learning to identify purpose, audience and main ideas in spoken texts, compare them, and synthesise notes from more than one source.","criteria":["I can state the purpose, audience and main ideas of spoken texts, justifying my views with reference to the text.","I can make inferences from key statements.","I can compare and contrast the content, style and language of different spoken texts.","I can make notes in my own words that synthesise key information from more than one source.","I can use my notes to create a new text that draws on more than one source."],"steps":{"start":"Listen to the first minute of two podcasts on the same subject. Who is each one for? How can you tell?","teach":"Listen to two spoken texts on one issue (an expert interview and a campaign video, or two radio items). Make notes in a synthesis grid: points both make, points only one makes, and where they disagree. Compare style: formal or informal, and how each uses evidence. Write a short briefing that combines both sources, in your own words.","practise":"The \"Two voices\" sheet: the adult reads two short talks aloud.","check":"Ask: where do the speakers disagree, and whose evidence is stronger? Which sentence in your briefing combines both?"},"use":[],"home":"Listen to two news programmes cover the same story and compare what each one chose to include.","vocab":"purpose, audience, infer, compare, contrast, synthesise, briefing, own words","understand":"What's the difference between summarising two sources and synthesising them?","lookFor":"Explains that a summary deals with each source in turn, while a synthesis combines them by theme and shows where they agree or differ."},
    {"id":"lesson-fourth-evaluating-spoken-texts-persuasion-and-credibility","level":"Fourth","subject":"Literacy","strand":"Listening and talking","codes":["LIT 4-07a","LIT 4-08a"],"title":"Evaluating spoken texts: persuasion and credibility","intention":"We are learning to make detailed evaluative comments on spoken texts and to judge the credibility of sources.","criteria":["I can make detailed evaluative comments, with evidence, on the content, form and style of spoken texts.","I can identify techniques used to influence or persuade, such as emotive language, rhetorical questions, statistics and hyperbole.","I can comment on the relevance, reliability and credibility of sources, justifying my opinion."],"steps":{"start":"Is a celebrity a credible source on climate science? On their own life? What's the difference?","teach":"Listen to a political speech or a persuasive video. Identify the techniques, including hyperbole, and evaluate how effective each is for its audience, not just name it. Judge credibility: the speaker's expertise, purpose, evidence and what's left out. Write two evaluative sentences that quote the text and explain both effect and effectiveness.","practise":"The \"Weighing a speech\" sheet: the adult reads a short speech aloud.","check":"Ask: which technique works best on this audience, and why? How credible is the speaker on this topic?"},"use":[],"home":"Watch a political or campaign broadcast and judge how credible each claim is.","vocab":"evaluate, effectiveness, persuade, hyperbole, emotive, credibility, reliability, bias","understand":"What's the difference between identifying a technique and evaluating it?","lookFor":"Explains that identifying names it, while evaluating judges how well it works for this audience and purpose, with evidence."},
    {"id":"lesson-fourth-presenting-with-confidence-sustaining-a-point-of-view","level":"Fourth","subject":"Literacy","strand":"Listening and talking","codes":["LIT 4-09a","LIT 4-10a"],"title":"Presenting with confidence: sustaining a point of view","intention":"We are learning to present confidently, sustain a point of view with evidence, and engage an audience.","criteria":["I can communicate detailed information, ideas or opinions, and explain with supporting detail.","I can sum up ideas, issues, findings or conclusions.","I can structure a talk clearly, with signposts that support a line of thought.","I can introduce and conclude a talk in a way that engages the audience.","I can adapt tone, vocabulary and non-verbal skills, and choose resources well."],"steps":{"start":"Watch the first 30 seconds of a strong talk. What did the speaker do to make you keep listening?","teach":"Plan a five-minute persuasive talk with a clear position. Build each section from a point, evidence and a link back to the position. Write a hook and a conclusion that returns to it. Practise adapting the same opening for two audiences (a class and a council meeting). Rehearse with timing, pauses and eye contact, and give feedback on one strength and one target.","practise":"Plan with the \"Five-minute talk\" sheet, rehearse, then present.","check":"Ask: how did your conclusion link back to your opening? Where did you change your tone for the audience?"},"use":[],"home":"Present your talk to someone at home and ask what they remember most, and why.","vocab":"position, sustain, signpost, hook, conclusion, adapt, audience, register, resource","understand":"How do you keep a point of view going through a whole talk?","lookFor":"Explains linking each section back to the position with signposts, and ending by returning to the opening."},
    {"id":"lesson-fourth-reading-complex-texts-annotating-and-interrogating","level":"Fourth","subject":"Literacy","strand":"Reading: understanding stories","codes":["ENG 4-12a","LIT 4-13a"],"title":"Reading complex texts: annotating and interrogating","intention":"We are learning to read a wide range of complex texts with understanding, using strategies such as annotating independently.","criteria":["I can read with fluency, understanding and expression across a wide range of texts.","I can use word roots, grammar, punctuation, tone, and sentence and text structure to understand texts.","I can choose and use strategies independently, such as skimming, scanning, predicting, clarifying, summarising, analysing and annotating."],"steps":{"start":"Here is a paragraph from a broadsheet opinion column. What's your first impression of the writer's tone?","teach":"Model annotating a challenging article: circle unfamiliar words and work out meanings from roots and context, underline the main claim, mark shifts in tone, and note questions in the margin. Summarise each paragraph in five words. Read a key paragraph aloud with expression that shows the tone.","practise":"The \"Annotate it\" sheet.","check":"Ask: where does the writer's tone change, and how can you tell? Which annotation helped you most?"},"use":[],"home":"Annotate an article or a page of a book with a pencil: questions, key words and reactions.","vocab":"annotate, interrogate, tone, context, word root, summarise, analyse","understand":"How did annotating change what you understood?","lookFor":"Gives a specific example where a question or note in the margin led to a clearer or deeper understanding."},
    {"id":"lesson-fourth-synthesising-information-from-different-sources","level":"Fourth","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 4-14a","LIT 4-15a"],"title":"Synthesising information from different sources","intention":"We are learning to find, sort and summarise essential information from several sources, and synthesise it in our own words.","criteria":["I can find, select and sort essential information from a variety of sources.","I can summarise key information from more than one source in my own words.","I can make notes that synthesise key information from different sources.","I can use my notes to create a new text that shows understanding of the topic."],"steps":{"start":"If three sources each give a different figure for the same thing, what do you do?","teach":"Give three short sources on one question (an official report summary, a news article and an opinion blog). Sort essential from interesting-but-not-needed information. Build a synthesis table by theme, not by source. Write a summary paragraph whose sentences each combine at least two sources, and say how you dealt with any disagreement.","practise":"The \"Three sources\" sheet.","check":"Ask: which sentence in your summary draws on more than one source? How did you handle the sources that disagreed?"},"use":[],"home":"Research a question you care about using three different kinds of source, and summarise what you found.","vocab":"essential, synthesise, theme, summarise, source, reliable, own words","understand":"Two sources disagree on a figure. How do you decide what to write?","lookFor":"Checks which is more credible and up to date, and may report both and say why they differ."},
    {"id":"lesson-fourth-close-reading-detailed-analysis-and-evaluation","level":"Fourth","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 4-16a","ENG 4-17a"],"title":"Close reading: detailed analysis and evaluation","intention":"We are learning to state purpose and main ideas precisely, make accurate inferences, compare texts, and give detailed evaluative answers.","criteria":["I can state the purpose, audience and main ideas of texts clearly, with justification.","I can make accurate inferences with justification, in my own words.","I can compare and contrast the content, style and language of different texts with supporting detail.","I can respond in detail to close reading questions, and evaluate the effect of word choice, sentence structure, punctuation, grammar and imagery."],"steps":{"start":"\"Explain how the writer's word choice conveys their attitude.\" What does a full-mark answer need?","teach":"Unpick question types: understanding (own words), analysis (quote, technique, effect), evaluation (how effective, for whom). Model a detailed analysis answer on imagery, showing how to explore connotations. Practise an own-words answer that doesn't lift phrases. Compare how two writers present the same subject.","practise":"The \"Close reading in depth\" sheet.","check":"Ask an analysis question and an evaluation question on a new paragraph. Listen for connotations, not just a technique name."},"use":[],"home":"Choose a headline and explore the connotations of its key word with someone at home.","vocab":"connotation, imagery, analysis, evaluation, inference, own words, attitude, tone","understand":"What does exploring connotations add to an analysis answer?","lookFor":"Explains that connotations show the associations a word carries, which reveal the writer's attitude or the effect on the reader."},
    {"id":"lesson-fourth-bias-persuasion-and-credibility-in-what-i-read","level":"Fourth","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 4-18a"],"title":"Bias, persuasion and credibility in what I read","intention":"We are learning to recognise persuasion and bias, comment on the techniques used, and judge the credibility of sources.","criteria":["I can recognise persuasion and bias.","I can identify and comment on techniques used to influence my opinion, such as emotive language, statistics and hyperbole.","I can make evaluative comments on the relevance, reliability and credibility of sources, with justification."],"steps":{"start":"Two headlines about the same event: \"Council slashes park budget\" and \"Council saves £2m for schools\". What's going on?","teach":"Compare two articles on the same story from sources with different viewpoints. Mark bias: loaded words, what each chooses to include or leave out, whose voices are quoted, and how statistics are framed. Evaluate credibility with a checklist (author, purpose, evidence, date, corroboration). Write an informed view that recognises bias in both.","practise":"The \"Spot the slant\" sheet.","check":"Ask: what is each article's bias, and how do you know? Which is more credible on the facts, and why?"},"use":[],"home":"Compare how two different news sites report the same story.","vocab":"bias, slant, loaded language, framing, credibility, corroborate, persuasion, hyperbole","understand":"Can an article be biased without saying anything false?","lookFor":"Explains yes: through what it chooses to include or leave out, whose voices it quotes, and loaded words."},
    {"id":"lesson-fourth-critical-response-to-literature-structure-theme-and-style","level":"Fourth","subject":"Literacy","strand":"Reading: understanding stories","codes":["ENG 4-19a"],"title":"Critical response to literature: structure, theme and style","intention":"We are learning to evaluate the effectiveness of structure, characterisation and setting, explain how the theme is developed, and evaluate the writer's style with terminology.","criteria":["I can evaluate the effectiveness of structure, characterisation and setting with relevant reference to the text.","I can show how the writer's theme is developed and relate it to my own and others' experiences.","I can make evaluative comments on the writer's style and features of the genre, with detailed reference to the text and appropriate terminology."],"steps":{"start":"What's a key moment in a book or film you know well? Why did the writer put it exactly there?","teach":"Work on a short story, novel or play the pupil is studying. Trace the theme through three key moments, with quotations. Evaluate one structural choice (a flashback, a twist, the ending) and one stylistic choice (narrative voice, imagery, dialogue), using terms such as foreshadowing and juxtaposition. Plan a critical paragraph: point, evidence, analysis, evaluation and link to theme.","practise":"The \"Critical response planner\" sheet, with any text the pupil is studying.","check":"Ask: how does this moment develop the theme? How effective is the ending, and why?"},"use":[],"home":"Talk about how a series or film builds its theme across episodes.","vocab":"theme, structure, characterisation, setting, foreshadowing, juxtaposition, narrative voice, evaluate, terminology","understand":"Why is 'the writer uses imagery' not enough in a critical essay?","lookFor":"Explains that you need the example, its effect, and how it develops the theme or how effective it is."},
    {"id":"lesson-fourth-independent-spelling-accuracy","level":"Fourth","subject":"Literacy","strand":"Spelling","codes":["LIT 4-21a"],"title":"Independent spelling accuracy","intention":"We are learning to use strategies and resources independently to make sure our spelling, including specialist vocabulary, is accurate.","criteria":["I can use a range of strategies and resources independently to spell accurately.","I can spell specialist vocabulary from all my subjects accurately.","I can proofread my own extended writing for spelling and correct it."],"steps":{"start":"Which words do you get wrong most often? Look back through recent writing: is there a pattern?","teach":"Build a personal error log from the pupil's own writing and sort errors by type: homophones, double letters, suffix rules, unstressed vowels, specialist words. Choose a strategy for each type. Practise proofreading in a separate pass for spelling only, reading backwards sentence by sentence. Use a dictionary to confirm meanings of easily confused pairs (affect and effect, practice and practise).","practise":"The \"My spelling log\" sheet, with a piece of the pupil's recent writing.","check":"Give a short proofreading passage with specialist words and homophones. Ask the pupil to correct it and explain two corrections."},"use":[],"home":"Keep your error log going: add any word you get wrong, with the strategy that will fix it.","vocab":"proofread, homophone, suffix, unstressed vowel, specialist vocabulary, error log, strategy","understand":"Why proofread for spelling in a separate pass?","lookFor":"Explains that when you read for meaning your brain fills in what you expect, so a separate slow pass catches errors you'd miss."},
    {"id":"lesson-fourth-sentences-and-punctuation-for-effect","level":"Fourth","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 4-22a"],"title":"Sentences and punctuation for effect","intention":"We are learning to use a variety of accurate sentence structures and punctuation to clarify meaning and enhance our writing.","criteria":["I can write grammatically accurate sentences.","I can use a variety of punctuation accurately, including semicolons, colons, dashes, brackets and ellipses.","I can use a variety of sentence structures for effect, including minor sentences, lists and repetition.","I can structure my writing with linking phrases and topic sentences to signpost a clear line of thought."],"steps":{"start":"\"Silence.\" Is that a sentence? Why might a writer use it?","teach":"Look at sentence types in a model text: a long complex sentence building detail, a short sentence for impact, a minor sentence, a list for accumulation. Practise semicolons between related clauses and in complex lists, a dash for an aside or a sharp turn, and a colon to introduce an explanation. Revise a flat paragraph to use three deliberate sentence choices, and explain each one's effect.","practise":"The \"Punctuation for effect\" sheet.","check":"Ask the pupil to write a paragraph using a semicolon, a dash and a minor sentence, and explain the effect of each."},"use":[],"home":"Find a sentence in a book that uses punctuation for effect and copy it into a notebook with a note on why it works.","vocab":"semicolon, colon, dash, parenthesis, ellipsis, minor sentence, complex sentence, accumulation, effect","understand":"When is a semicolon better than a full stop?","lookFor":"When two complete clauses are closely related and the writer wants to show that link, not separate them."},
    {"id":"lesson-fourth-independent-editing-and-justifying-layout","level":"Fourth","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 4-23a","LIT 4-24a"],"title":"Independent editing, and justifying layout","intention":"We are learning to review and edit our writing independently, and to justify our choices of layout and presentation.","criteria":["I can review and edit my writing independently so it is clear, accurate and meets its purpose.","I can improve content, language and structure, not just correct errors.","I can choose layout and presentation features, including in digital texts, and justify them in terms of their impact on the reader."],"steps":{"start":"What is the difference between proofreading and editing?","teach":"Edit a first draft at three levels: structure (is the order the strongest? does each paragraph earn its place?), language (precise vocabulary, varied sentences, cut padding) and accuracy. Keep a record of the changes and why. Then design the same content as a web page and as a printed leaflet, and justify each layout choice by its effect on the reader.","practise":"The \"Edit like an editor\" sheet, with a draft of the pupil's own.","check":"Ask: what was your biggest structural change, and why? Justify one layout choice by its impact on the reader."},"use":[],"home":"Edit a piece of your homework for structure before handing it in, and note what you changed.","vocab":"edit, revise, structure, precise, padding, layout, presentation, justify, impact","understand":"Why edit structure before proofreading?","lookFor":"Explains that structural changes move or remove whole sections, so fixing small errors first can be wasted effort."},
    {"id":"lesson-fourth-responsible-use-of-sources-referencing-and-synthesising","level":"Fourth","subject":"Literacy","strand":"Writing: creating texts","codes":["LIT 4-25a","LIT 4-26a"],"title":"Responsible use of sources: referencing and synthesising","intention":"We are learning to use notes and sources to develop ideas, use sources responsibly, and reference them appropriately.","criteria":["I can use notes and other sources to generate ideas and support new texts.","I can make responsible use of sources, acknowledging and referencing them appropriately.","I can select relevant ideas and essential detail, and organise them into a structured line of thought.","I can use varied and appropriate vocabulary to communicate effectively."],"steps":{"start":"What's the difference between using a source and copying it? Where's the line?","teach":"Discuss plagiarism and why referencing matters (credit, credibility, letting readers check). Practise paraphrasing, quoting and summarising one source, and write a simple reference (author or organisation, title, date, web address and date accessed). Plan a short report from notes on several sources, organising by argument, not by source. Discuss responsible use of AI tools and search results: check them against original sources.","practise":"The \"Using sources well\" sheet.","check":"Ask: which ideas came from your sources, and how does the reader know? Show me a reference you've written."},"use":[],"home":"Write a short report for a school subject and add a reference list at the end.","vocab":"plagiarism, reference, paraphrase, quote, summarise, acknowledge, synthesise, credible","understand":"Why reference sources even when you've put the ideas in your own words?","lookFor":"Explains that the ideas still belong to someone else; referencing gives credit, adds credibility, and lets readers check."},
    {"id":"lesson-fourth-writing-reports-information-with-evidence","level":"Fourth","subject":"Literacy","strand":"Writing: creating texts","codes":["LIT 4-28a","ENG 4-27a"],"title":"Writing reports: information with evidence","intention":"We are learning to convey information, explain processes or concepts with substantiating evidence, and synthesise ideas in a report.","criteria":["I can convey information, describe events and explain processes or concepts with substantiating evidence.","I can synthesise ideas or opinions in different ways.","I can use a style and format well suited to my purpose and audience.","I can structure writing effectively with linking phrases and topic sentences.","I can engage or influence the reader through language, style and tone to create particular effects."],"steps":{"start":"What makes a report trustworthy? Think of a good one you've read.","teach":"Read a model report and label its features: a clear purpose, sections with headings, topic sentences, evidence (data, quotation, example) for each claim, and an objective tone. Plan a report on an issue in the pupil's school or community: what's happening, why, and what could be done, with evidence for each section. Write the introduction and one section together.","practise":"The \"Report planner\" sheet: plan, then write the report.","check":"Ask: where is your strongest evidence? How did you keep the tone objective?"},"use":[],"home":"Write a report on something you could improve at home or in your community, with evidence.","vocab":"report, objective, evidence, substantiate, synthesise, topic sentence, heading, formal","understand":"How is a report's tone different from a persuasive article's?","lookFor":"Explains a report is objective and lets evidence lead, while a persuasive article argues one side with emotive language."},
    {"id":"lesson-fourth-discursive-and-argumentative-essays","level":"Fourth","subject":"Literacy","strand":"Writing: creating texts","codes":["LIT 4-29a"],"title":"Discursive and argumentative essays","intention":"We are learning to argue, evaluate and explore issues within a convincing line of thought, with relevant evidence.","criteria":["I can present ideas or sustain a point of view with essential detail and supporting evidence.","I can convey a clear line of thought with effective linking phrases and topic sentences.","I can write an effective introduction and conclusion.","I can use language to create effects or influence the reader, such as word choice, emotive language and rhetorical devices."],"steps":{"start":"Is it better to be balanced or persuasive? When would you choose each?","teach":"Compare a discursive essay (both sides, then a judgement) with a persuasive one (one side, answering objections). Plan a discursive essay on a real issue: introduction setting out the debate, alternating paragraphs for and against with evidence, and a conclusion that weighs them and reaches a justified view. Practise linking phrases that show a line of thought: 'However', 'Furthermore', 'Admittedly…, yet'.","practise":"The \"Weigh it up\" sheet: plan, then write the essay.","check":"Ask: where does your line of thought turn? How does your conclusion weigh both sides rather than just repeat them?"},"use":[],"home":"Discuss a real issue at home and write down the strongest point on each side.","vocab":"discursive, argumentative, line of thought, counter-argument, evidence, evaluate, conclusion, linking phrase","understand":"What makes a conclusion more than a summary?","lookFor":"Explains that it weighs the arguments and reaches a justified judgement, showing which side is stronger and why."},
    {"id":"lesson-fourth-reflective-personal-writing","level":"Fourth","subject":"Literacy","strand":"Writing: creating texts","codes":["ENG 4-30a"],"title":"Reflective personal writing","intention":"We are learning to create a convincing impression of a personal experience and reflect on our response to changing circumstances.","criteria":["I can recount events convincingly, clearly establishing the context and setting.","I can convey my feelings and reactions, and reflect on them with a sense of involvement.","I can engage the reader through language, style and tone."],"steps":{"start":"What's an experience that changed how you see something? What were you like before, and after?","teach":"Read a model reflective essay and find how the writer moves between narrating events and reflecting on them, and how the reflection deepens. Plan an essay around a turning point: the before, the moment itself, and what changed. Write the turning point in slow motion with sensory detail, then a reflective paragraph that goes beyond 'I learned a lesson'.","practise":"The \"Looking back\" sheet: plan, then write.","check":"Ask: where does your reflection go deeper than a simple lesson? How did your feelings change through the experience?"},"use":[],"home":"Talk to a grown-up about an experience you both remember and compare how you each saw it.","vocab":"reflective, personal, turning point, involvement, insight, sensory detail, tone","understand":"What's the difference between recounting and reflecting?","lookFor":"Explains that recounting says what happened, while reflecting explores what it meant and how the writer's thinking changed."},
    {"id":"lesson-fourth-creative-writing-mood-dialogue-and-narrative-structure","level":"Fourth","subject":"Literacy","strand":"Writing: creating texts","codes":["ENG 4-31a"],"title":"Creative writing: mood, dialogue and narrative structure","intention":"We are learning to use the conventions of a genre successfully, create mood and atmosphere, and write convincing relationships and dialogue.","criteria":["I can use the conventions of my chosen genre effectively.","I can create an appropriate mood or atmosphere.","I can create convincing relationships, actions and dialogue for my characters.","I can use narrative structure and devices to engage the reader and achieve particular effects."],"steps":{"start":"Read two lines of dialogue. What do they tell you about the relationship, without saying it?","teach":"Experiment with structure: start in the middle of the action, or use a flashback or a shift in point of view. Build atmosphere through setting, weather, pace and sentence length. Write dialogue with subtext, where characters don't say exactly what they mean, and set it out correctly. Plan a story around one change in a relationship.","practise":"The \"Story craft\" sheet: plan the structure, then write a scene with dialogue.","check":"Ask: what is the subtext in your dialogue? Which narrative device did you choose, and what effect does it have?"},"use":[],"home":"Listen to a conversation in a film or a play and notice what the characters don't say.","vocab":"genre, convention, mood, atmosphere, subtext, dialogue, flashback, point of view, narrative device","understand":"What is subtext, and why does it make dialogue convincing?","lookFor":"Explains that subtext is what characters mean but don't say; real people rarely say exactly what they feel."},
    {"id":"lesson-england-year-1-grammar-plurals-un-and-capital-letters","england":true,"level":"First","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 1-22a"],"title":"Year 1 grammar: plurals, un- and capital letters","intention":"We are learning to add -s or -es for more than one, use un- to change a word's meaning, and use capital letters for names and I.","criteria":["I can add -s or -es to make a plural.","I can add un- to make a word mean not, or undo something.","I can use a capital letter for names, days of the week and the word I."],"steps":{"start":"Hold up one pencil, then two. One pencil, two…? One box, two…? Listen: which needs an extra beat?","teach":"Sort words into -s and -es by clapping the beats: cats, foxes, dogs, wishes. Then add un- to kind, happy and tie, and act them out. Write a sentence about yourself with I and a friend's name: point to every capital letter.","practise":"The three Year 1 grammar sets on PopSpell.","check":"Write the plural of bus, cat and dish, and one sentence using I, a name and a day of the week."},"use":["eg-y1-plurals","eg-y1-un","eg-y1-capitals"],"home":"Spot plurals on a walk (cars, buses, trees) and say whether they need -s or -es.","vocab":"plural, singular, prefix, capital letter, sentence","understand":"Why does box need -es but cat only -s?","lookFor":"Hears the extra beat (boxes), or knows -es comes after s, x, z, sh and ch.","cfe":{"title":"Plurals, the prefix un- and capital letters","level":"First","codes":["LIT 1-21a","LIT 1-22a"],"criteria":["I can use my knowledge of phonics and spelling strategies to spell words, including adding -s or -es.","I can write independently, punctuating most sentences accurately with a capital letter and a full stop."]}},
    {"id":"lesson-england-year-2-grammar-apostrophes-suffixes-and-sentence-types","england":true,"level":"First","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 1-22a"],"title":"Year 2 grammar: apostrophes, suffixes and sentence types","intention":"We are learning to use apostrophes, suffixes and the four kinds of sentence.","criteria":["I can use an apostrophe for missing letters (can't) and to show one owner (the girl's book).","I can add -ness, -ful, -less, -er, -est and -ly.","I can tell a statement, question, exclamation and command apart.","I can use commas in a list."],"steps":{"start":"Say \"do not\" quickly. What do we write? Where do the missing letters go?","teach":"Write can't, I'm and it's, then cover the apostrophe and say which letters are missing. Show the girl's book against two girls. Build words with suffixes: care, careful, careless; kind, kindness, kindly. Read four sentences in different voices: statement, question, exclamation (What a…!), command.","practise":"The Year 2 grammar sets on PopSpell.","check":"Write one of each kind of sentence, using a list with commas in one of them."},"use":["eg-y2-apostrophes","eg-y2-suffixes","eg-y2-sentence-types","eg-y2-commas-tense"],"home":"Find apostrophes in a book or on a cereal box: is it missing letters or belonging?","vocab":"apostrophe, suffix, statement, question, exclamation, command, comma","understand":"Write \"do not\" and \"they are\" the short way. Where does the apostrophe go, and why there?","lookFor":"Puts the apostrophe where letters are missed out in new words, and explains it; doesn't add apostrophes to ordinary plurals.","cfe":{"title":"Sentence types, suffixes and apostrophes","level":"First","codes":["LIT 1-21a","LIT 1-22a"],"criteria":["I can punctuate most sentences accurately, using a capital letter, full stop, question mark or exclamation mark.","I can use phonics and spelling strategies when spelling familiar and unfamiliar words, including words with suffixes.","I can start sentences in a variety of ways to engage the reader."]}},
    {"id":"lesson-england-year-3-grammar-a-or-an-prefixes-and-words-for-time-and-cause","england":true,"level":"First","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 1-22a"],"title":"Year 3 grammar: a or an, prefixes, and words for time and cause","intention":"We are learning to choose a or an, use prefixes, and use conjunctions, adverbs and prepositions to say when and why.","criteria":["I can choose a or an.","I can use prefixes such as super-, anti- and auto-.","I can use words like when, before, because and during to show time and cause.","I can punctuate direct speech with inverted commas."],"steps":{"start":"Say: a apple, an apple. Which sounds right, and why?","teach":"Sort words by their first letter: a rock, an open box. Build prefixed words (supermarket, anti-clockwise, autograph). Tell a short story of your day using before, after, because and during. Write one line of speech with inverted commas around the words said.","practise":"The Year 3 grammar sets on PopSpell.","check":"Write two sentences about your weekend using before and because, and one with speech marks."},"use":["eg-y3-a-an","eg-y3-prefixes","eg-y3-time-cause","eg-y3-perfect-speech"],"home":"Retell a favourite film using then, after, because and during.","vocab":"conjunction, preposition, adverb, prefix, inverted commas, direct speech","understand":"Why do we say an apple but a banana?","lookFor":"Explains an goes before a vowel sound.","cfe":{"title":"Linking ideas: a or an, prefixes, and words for time and cause","level":"First","codes":["LIT 1-21a","LIT 1-22a"],"criteria":["I can link sentences using common conjunctions, for example, and, because, but or so.","I can start sentences in a variety of ways to engage the reader.","I can use spelling strategies when spelling unfamiliar words, including words with prefixes."]}},
    {"id":"lesson-england-year-4-grammar-fronted-adverbials-possessive-apostrophes-and-standard-english","england":true,"level":"Second","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 2-22a"],"title":"Year 4 grammar: fronted adverbials, possessive apostrophes and Standard English","intention":"We are learning to start sentences with fronted adverbials, show plural possession, and use Standard English verbs.","criteria":["I can start a sentence with a fronted adverbial and a comma.","I can tell girl's from girls'.","I can use we were and I did in Standard English."],"steps":{"start":"Change \"I heard the bad news later that day\" so it starts with when.","teach":"Move adverbials to the front and add the comma: After lunch, we played. Show the dog's bone against the dogs' bones, and children's toys. Spot and fix: \"we was late\", \"I done it\".","practise":"The Year 4 grammar sets on PopSpell.","check":"Write three sentences that start with a fronted adverbial, one using a plural possessive."},"use":["eg-y4-fronted","eg-y4-possessive","eg-y4-standard"],"home":"Write a recount of the day with every sentence starting a different way.","vocab":"fronted adverbial, comma, possession, plural, Standard English","understand":"Start a sentence of your own with \"After lunch\" or \"Without a sound\". Where does the comma go, and how does it help the reader?","lookFor":"Writes a new fronted adverbial with a comma after it, and explains that the comma shows where the opening ends.","cfe":{"title":"Varying sentence openings, apostrophes and accurate grammar","level":"Second","codes":["LIT 2-22a"],"criteria":["I can use sentences of different lengths and types and vary my sentence openings.","I can use a range of punctuation, including commas and apostrophes.","I can write most sentences in a grammatically accurate way."]}},
    {"id":"lesson-england-year-5-grammar-relative-clauses-possibility-and-parenthesis","england":true,"level":"Second","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 2-22a"],"title":"Year 5 grammar: relative clauses, possibility and parenthesis","intention":"We are learning to add information with relative clauses and parenthesis, and show how likely something is.","criteria":["I can add a relative clause with who, which, where, when, whose or that.","I can use modal verbs and adverbs to show how likely something is.","I can use brackets, dashes or commas for parenthesis."],"steps":{"start":"\"The girl won the race.\" Add who she is without starting a new sentence.","teach":"Build sentences with relative clauses for people (who), things (which), places (where) and owners (whose). Put a weather forecast on a scale: will, should, might, could. Add extra information to a sentence three ways: brackets, dashes and commas.","practise":"The Year 5 grammar sets on PopSpell.","check":"Write a sentence with a relative clause, one with a modal verb and one with parenthesis."},"use":["eg-y5-relative","eg-y5-possibility","eg-y5-parenthesis","eg-y5-verb-suffixes"],"home":"Write a weather forecast for tomorrow using might, will and perhaps.","vocab":"relative clause, relative pronoun, modal verb, parenthesis, bracket, dash","understand":"What does the relative clause add to this sentence?","lookFor":"Explains it gives extra information about the noun.","cfe":{"title":"Adding information to sentences: clauses, possibility and brackets","level":"Second","codes":["LIT 2-22a"],"criteria":["I can use sentences of different lengths and types.","I can link sentences using a range of conjunctions.","I can write most sentences in a grammatically accurate way, using a range of punctuation."]}},
    {"id":"lesson-england-year-6-grammar-passive-formal-language-and-punctuation-between-clauses","england":true,"level":"Second","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 2-22a"],"title":"Year 6 grammar: passive, formal language and punctuation between clauses","intention":"We are learning to use the passive, formal language and the subjunctive, and semi-colons, colons and dashes.","criteria":["I can turn an active sentence into the passive.","I can choose formal words and use the subjunctive (If I were…).","I can use a semi-colon, colon or dash between clauses, and a hyphen to avoid ambiguity."],"steps":{"start":"\"I broke the window.\" How could you say it without saying who did it?","teach":"Flip active sentences into the passive and notice what comes first. Swap informal words for formal ones (find out: discover, ask for: request). Join two clauses with a semi-colon (It's raining; I'm fed up), introduce a list with a colon, and compare man eating shark with man-eating shark.","practise":"The Year 6 grammar sets on PopSpell.","check":"Write a formal letter opening that uses the passive, the subjunctive and a semi-colon."},"use":["eg-y6-passive","eg-y6-formal","eg-y6-punctuation","eg-y6-synonyms"],"home":"Rewrite a text message to a friend as a formal letter.","vocab":"active, passive, subjunctive, formal, semi-colon, colon, hyphen","understand":"Why might a writer use the passive: \"The window was broken\"?","lookFor":"Explains it hides or doesn't need who did it."},
    {"id":"lesson-england-year-1-common-exception-words","england":true,"level":"First","subject":"Literacy","strand":"Spelling","codes":["LIT 1-21a"],"title":"Year 1 common exception words","intention":"We are learning to read and spell common exception words, noticing the tricky part.","criteria":["I can read the Year 1 common exception words.","I can spot the tricky part of a word.","I can spell some of them from memory."],"steps":{"start":"Read the, said and was from cards. Which part doesn't sound the way it looks?","teach":"For each word, sound out the parts that follow the rules and put a heart over the tricky part (said: s, d are regular; ai is tricky). Say it, spell it aloud, write it, then check it.","practise":"A Year 1 common exception words list on PopSpell, then read the Tricky word sentences.","check":"Read five words from the list, then write three from memory in a short dictated sentence."},"use":["cew-y1-1","cew-y1-2","cew-y1-3","r-tricky"],"home":"Pin three tricky words on the fridge: read them every morning.","vocab":"tricky word, common exception word, sound, letter","understand":"Which part of \"said\" do you have to remember? Now find the tricky part in \"was\".","lookFor":"Finds the tricky part in a second word without being told, and sounds out the rest.","cfe":{"title":"Common words with a tricky part: set 1","level":"First","codes":["LIT 1-21a"],"criteria":["I can spell most commonly used words correctly.","I can use phonics and spelling strategies when spelling familiar and unfamiliar words."]}},
    {"id":"lesson-england-year-2-common-exception-words","england":true,"level":"First","subject":"Literacy","strand":"Spelling","codes":["LIT 1-21a"],"title":"Year 2 common exception words","intention":"We are learning to read and spell the Year 2 common exception words.","criteria":["I can read the Year 2 common exception words.","I can explain which part of a word is tricky.","I can spell them in my writing."],"steps":{"start":"Read because, people and water. Which letters don't make their usual sound?","teach":"Group words that share a pattern (find, kind, mind, behind; old, cold, gold, hold, told). Mark the tricky part of the rest with a heart. Say, cover, write and check.","practise":"A Year 2 common exception words list on PopSpell.","check":"Write a sentence the tutor says that uses three of the words."},"use":["cew-y2-1","cew-y2-2","cew-y2-3","cew-y2-4","cew-y2-5"],"home":"Spot these words in a reading book and read each one twice.","vocab":"common exception word, tricky part, pattern","understand":"How will you remember the tricky part of because?","lookFor":"Uses a strategy: saying it in syllables, a phrase or noticing the tricky part.","cfe":{"title":"Common words with a tricky part: set 2","level":"First","codes":["LIT 1-21a"],"criteria":["I can spell most commonly used words correctly.","I can use phonics and spelling strategies when spelling familiar and unfamiliar words."]}},
    {"id":"lesson-england-years-3-and-4-word-list-roots-prefixes-and-suffixes","england":true,"level":"Second","subject":"Literacy","strand":"Spelling","codes":["LIT 2-21a"],"title":"Years 3 and 4 word list: roots, prefixes and suffixes","intention":"We are learning to spell words from the Years 3 and 4 word list, using syllables, root words and the tricky part.","criteria":["I can break a long word into syllables.","I can find the root word and add prefixes and suffixes.","I can spell words from the Years 3 and 4 list."],"steps":{"start":"Clap the syllables of February, different and library. Which ones do people often miss out?","teach":"Take five words from the list. Say each in syllables, find any root word (accident, accidentally; possess, possession), and underline the tricky part. Use the first two or three letters to check a word in a dictionary.","practise":"The first Years 3 and 4 word lists on PopSpell; carry on through the rest over later lessons.","check":"Spell five words from today in a dictated sentence, then check them with the dictionary."},"use":["wl-y34-1","wl-y34-2"],"home":"Choose three words from the list and write them in a sentence each.","vocab":"syllable, root word, prefix, suffix, dictionary","understand":"Which root word is in disappear? How does that help you spell it?","lookFor":"Finds the root (appear) and adds the prefix without changing it.","cfe":{"title":"Spelling longer words: roots, prefixes and suffixes","level":"Second","codes":["LIT 2-21a"],"criteria":["I can apply my knowledge of spelling patterns, rules and strategies to spell most words correctly."]}},
    {"id":"lesson-england-years-5-and-6-word-list-morphology-and-etymology","england":true,"level":"Second","subject":"Literacy","strand":"Spelling","codes":["LIT 2-21a"],"title":"Years 5 and 6 word list: morphology and etymology","intention":"We are learning to spell words from the Years 5 and 6 word list, using word parts and where words come from.","criteria":["I can use root words, prefixes and suffixes to spell long words.","I can use where a word comes from to help spell it.","I can check a spelling and meaning in a dictionary or thesaurus."],"steps":{"start":"Which letters are doubled in accommodate, embarrass and necessary? How could you remember?","teach":"Take five words from the list. Split them into parts (environment: environ + ment), link related words (criticise, critic), and talk about where they come from (rhythm and rhyme are from Greek). Make a memory trick for the hardest one.","practise":"The first Years 5 and 6 word lists on PopSpell; carry on through the rest over later lessons.","check":"Spell five words from today, then look up one in a dictionary and one in a thesaurus."},"use":["wl-y56-1","wl-y56-2"],"home":"Find two of the words in a newspaper or online article.","vocab":"morphology, etymology, root word, prefix, suffix, thesaurus","understand":"Where does the word come from, and does that help you spell it?","lookFor":"Uses a word family or origin to explain a spelling.","cfe":{"title":"Spelling tricky words: word parts and where words come from","level":"Second","codes":["LIT 2-21a"],"criteria":["I can apply my knowledge of spelling patterns, rules and strategies to spell most words correctly."]}},
    {"id":"lesson-england-joined-handwriting-years-3-and-4","england":true,"level":"First","subject":"Literacy","strand":"Handwriting","codes":["LIT 1-24a"],"title":"Joined handwriting (Years 3 and 4)","intention":"We are learning to join letters with diagonal and horizontal strokes, and keep our writing even.","criteria":["I can join letters with diagonal and horizontal strokes.","I know which letters are best left unjoined.","I keep my letters the same size and my lines parallel."],"steps":{"start":"Write your name your best way. Which letters already join?","teach":"Model a diagonal join (a to n, as in an) and a horizontal join (o to n, as in on). Practise joining pairs, then short words. Talk about letters many schools leave unjoined, such as capitals. Check that ascenders and descenders don't touch.","practise":"Use the letter formation sheet for any letters still formed the wrong way, then copy a short sentence in joined writing.","check":"Copy a sentence in joined writing: are the letters even, the joins smooth, and the lines parallel?"},"use":["handwriting-joins"],"home":"Write a shopping list in joined handwriting.","vocab":"join, diagonal, horizontal, ascender, descender","understand":"Which letters don't join? Why not?","lookFor":"Names the letters their school doesn't join (often capitals and some after letters such as b, g, j, p, x, y).","cfe":{"title":"Joined handwriting","level":"First","codes":["LIT 1-24a"],"criteria":["I can present my writing in a clear and legible way."]}},
    {"id":"lesson-england-writing-legibly-fluently-and-at-speed-years-5-and-6","england":true,"level":"Second","subject":"Literacy","strand":"Handwriting","codes":["LIT 2-24a"],"title":"Writing legibly, fluently and at speed (Years 5 and 6)","intention":"We are learning to write legibly and fluently, getting faster, and choosing the right style for the job.","criteria":["I can write legibly and fluently at a good speed.","I can choose when to join and when to print, such as for labels.","I can choose the right pen or pencil for the task."],"steps":{"start":"Write the alphabet joined as fast as you can while staying neat. Time it.","teach":"Compare a quick note, a neat final copy and a labelled diagram: which style fits each? Practise speed in short bursts, keeping letters legible. Talk about choosing a pen or pencil that suits the task.","practise":"Copy a paragraph in your best joined writing, then write the same in a quick note style.","check":"Time the alphabet again. Is it faster and still easy to read?"},"use":[],"home":"Write a birthday card in your best handwriting.","vocab":"legible, fluent, joined, print, presentation","understand":"When would you use neat print, and when quick joined writing?","lookFor":"Matches style to the task: labels or a final copy vs. notes.","cfe":{"title":"Writing fluently and legibly at speed","level":"Second","codes":["LIT 2-24a"],"criteria":["I can write in a fluent and legible way.","I can make appropriate choices about presentation to engage the reader."]}},
    {"id":"lesson-england-getting-ready-for-the-times-tables-check-year-4","england":true,"level":"Second","subject":"Maths","strand":"Number","codes":["MNU 2-03a"],"title":"Getting ready for the times tables check (Year 4)","intention":"We are learning to recall multiplication facts up to 12 × 12 quickly.","criteria":["I can recall multiplication facts up to 12 × 12.","I can use facts I know to work out ones I'm stuck on.","I can answer within 6 seconds."],"steps":{"start":"Quick-fire: 6 × 4, 7 × 8, 9 × 6, 12 × 3. Which felt hardest?","teach":"Find the facts still to learn (often the 6, 7, 8, 9 and 12 tables). Use derived facts: 6 × 7 is 5 × 7 plus 7; 9 × 8 is 10 × 8 take 8; 12 × 4 is 10 × 4 plus 2 × 4. Show that 3 × 8 and 8 × 3 are the same fact.","practise":"6, 7, 8 and 9 times tables on PopSpell, then the timed times tables check practice: 25 questions, 6 seconds each.","check":"Do the timed practice again. Which facts were missed? They go on the list for next time."},"use":["n-tables-6-9","n-mtc"],"home":"Five minutes of tables a day: in the car, at teatime or before bed.","vocab":"multiply, times table, fact, product, commutative","understand":"You don't know 7 × 8. What fact could help?","lookFor":"Uses a known fact: 7 × 8 is double 7 × 4, or 7 × 7 + 7.","cfe":{"title":"Quick recall of times tables","level":"Second","codes":["MNU 2-03a"],"criteria":["I can use multiplication and division facts to the 10th multiplication table.","I can apply my knowledge of number facts to solve problems."]}},
    {"id":"lesson-england-getting-ready-for-the-phonics-check-year-1","england":true,"level":"First","subject":"Literacy","strand":"Reading: phonics and tricky words","codes":["ENG 1-12a","LIT 1-13a"],"title":"Getting ready for the phonics check (Year 1)","intention":"We are learning to read real and made-up words by saying the sounds and blending them.","criteria":["I can say the sound for each letter and digraph quickly.","I can blend sounds to read real words and alien words.","I can read words with longer vowel sounds, such as ai, ee and igh."],"steps":{"start":"Flash grapheme cards: sh, ch, th, ai, ee, igh, oa, ar. Say the sound as fast as you can.","teach":"Read real words, then alien words that use the same sounds (ship, then shup). Remind them alien words have no meaning, so sound out every grapheme and blend: there's no guessing from a picture or a word they know.","practise":"Sound Switch on PopSpell, then the phonics check practice with you (Pupils → 🔤 Phonics check practice).","check":"Read ten words, a mix of real and alien. Which graphemes caused trouble?"},"use":["g-switch-first","g-switch-build"],"home":"Make up alien names together and read them aloud.","vocab":"sound, grapheme, blend, real word, alien word","understand":"Why can't you guess an alien word?","lookFor":"Explains alien words aren't real, so you have to sound out every part.","cfe":{"title":"Reading real and made-up words","level":"First","codes":["ENG 1-12a","LIT 1-13a"],"criteria":["I can decode unknown words by locating and pronouncing familiar letter patterns and blends.","I can use a range of word recognition strategies independently."]}},
    {"id":"lesson-england-numbers-in-words-years-1-and-2","england":true,"level":"First","subject":"Maths","strand":"Number","codes":["MNU 1-02a"],"title":"Numbers in words (Years 1 and 2)","intention":"We are learning to read and write numbers to 100 in numerals and in words.","criteria":["I can read and write numbers to 20 in words.","I can read and write numbers to 100 in words.","I can match a number in words to its numerals."],"steps":{"start":"Show 14 and fourteen on cards. Which part of the word tells you the ones?","teach":"Build tens words (twenty, thirty… ninety), then add ones with a hyphen: thirty-seven. Point out the tricky ones: eleven, twelve, fifteen, forty (no u).","practise":"Numbers in words on PopSpell.","check":"Write 19, 40 and 63 in words, and read 'seventy-two' as a number."},"use":["en-numbers-words"],"home":"Read numbers on signs, cheques or price tags in words.","vocab":"numeral, digit, tens, ones, hyphen","understand":"Why do we write forty without a u, when we say four?","lookFor":"Notices that forty is spelled differently from four, and checks tricky number words rather than writing them as they sound.","cfe":{"title":"Numbers in words","level":"First","codes":["MNU 1-02a"],"criteria":["I can read, write, order and recite whole numbers to 1000, starting from any number in the sequence.","I can identify the value of each digit in a whole number with three digits."]}},
    {"id":"lesson-england-adding-and-subtracting-two-digit-numbers-in-your-head-year-2","england":true,"level":"First","subject":"Maths","strand":"Number","codes":["MNU 1-03a"],"title":"Adding and subtracting two-digit numbers in your head (Year 2)","intention":"We are learning to add and subtract two-digit numbers in our heads, and to know which calculations can be done in any order.","criteria":["I can add and subtract a two-digit number and ones, and a two-digit number and tens.","I can add two two-digit numbers and three one-digit numbers.","I know adding and multiplying can be done in any order, but taking away and dividing can't."],"steps":{"start":"Quick-fire: 34 + 5, 34 + 50, 6 + 3 + 4. Which was easiest, and why?","teach":"Use a hundred square or bead string: add tens by jumping down a row, ones by moving along. For two two-digit numbers, add tens then ones. For three numbers, find a pair that makes 10 first. Show 3 + 5 = 5 + 3 but 8 − 3 isn't 3 − 8.","practise":"Two-digit numbers on PopSpell.","check":"Ask for 47 + 30, 28 + 35 and 7 + 5 + 3, explaining one method aloud."},"use":["en-add-2digit"],"home":"Add prices or scores in your head in the car or at the shop.","vocab":"tens, ones, add, subtract, any order, commutative","understand":"Is 45 + 30 easier or harder than 45 + 3? Why?","lookFor":"Explains that adding tens changes the tens digit and adding ones changes the ones, and chooses a method on purpose.","cfe":{"title":"Adding and subtracting two-digit numbers mentally","level":"First","codes":["MNU 1-02a","MNU 1-03a"],"criteria":["I can solve addition and subtraction problems with whole numbers.","I can add and subtract multiples of 10 to or from any whole number.","I can show my understanding of the commutative law, for example, 6 + 3 = 3 + 6 or 2 × 4 = 4 × 2."]}},
    {"id":"lesson-england-comparing-measures-and-quicker-or-later-years-1-and-2","england":true,"level":"First","subject":"Maths","strand":"Measurement","codes":["MNU 1-11a","MNU 1-10a"],"title":"Comparing measures, and quicker or later (Years 1 and 2)","intention":"We are learning to compare lengths, masses and capacities using <, > and =, and to use words for time such as quicker and later.","criteria":["I can compare and order lengths, masses and capacities.","I can record a comparison with <, > or =.","I can use quicker, slower, earlier and later."],"steps":{"start":"Hold up two pencils: which is longer? How could we write that with a sign?","teach":"Measure pairs of objects, then record: 23 cm > 15 cm. Show the sign 'eats' the bigger number. Order three containers by how much they hold. Talk about events in the day using earlier and later, and which takes longer.","practise":"Comparing measures on PopSpell.","check":"Give three lengths to order and write with signs, and ask which is quicker: a snail or a horse."},"use":["en-compare-measures"],"home":"Compare two cups or two shoes at home and say which is bigger with a sign.","vocab":"longer, shorter, heavier, lighter, more than, less than, equal, quicker, slower, earlier, later","understand":"Why does 45 cm > 9 cm, even though 9 is a bigger digit than 4?","lookFor":"Compares the whole measure, not one digit, and checks the units are the same before comparing.","cfe":{"title":"Comparing measures, and how long things take","level":"First","codes":["MNU 1-11a","MTH 1-15a","MNU 1-10c"],"criteria":["I can record measurements of length, mass and capacity to the nearest standard unit.","I can use the terms equal to, not equal to, less than and greater than, and the symbols for them.","I can talk about how long tasks take."]}},
    {"id":"lesson-england-three-digit-numbers-in-your-head-year-3","england":true,"level":"First","subject":"Maths","strand":"Number","codes":["MNU 1-03a"],"title":"Three-digit numbers in your head (Year 3)","intention":"We are learning to add and subtract ones, tens and hundreds to a three-digit number in our heads.","criteria":["I can add and subtract ones to a three-digit number.","I can add and subtract tens and hundreds to a three-digit number.","I can say which digit changes and why."],"steps":{"start":"Show 452 with place value cards. What happens if we add 3? 30? 300?","teach":"Model each kind on a place value chart: only the column you add to changes, unless it goes past 9 and carries. Practise crossing a hundred, such as 395 + 10.","practise":"Three-digit numbers on PopSpell.","check":"Ask 527 + 40, 683 − 200 and 395 + 7, and which digit changed each time."},"use":["en-mental-3digit"],"home":"Add 10s and 100s to door numbers or page numbers.","vocab":"hundreds, tens, ones, add, subtract, digit","understand":"What is 296 + 10, and why does more than one digit change?","lookFor":"Explains carrying: the tens go past 9, so the hundreds change too.","cfe":{"title":"Three-digit numbers mentally","level":"First","codes":["MNU 1-02a","MNU 1-03a"],"criteria":["I can add and subtract multiples of 10 or 100 to or from any whole number to 1000.","I can solve addition and subtraction problems with three-digit whole numbers."]}},
    {"id":"lesson-england-pounds-and-pence-adding-and-change-year-3","england":true,"level":"First","subject":"Maths","strand":"Money","codes":["MNU 1-09a"],"title":"Pounds and pence: adding and change (Year 3)","intention":"We are learning to add and subtract amounts of money in pounds and pence, and to give change.","criteria":["I can add two amounts using £ and p.","I can work out change from £5 or £10.","I know £1 is 100p, and can change between pounds and pence."],"steps":{"start":"Lay out £2.35 in coins. How many pence is that?","teach":"Add prices by adding pounds, then pence, regrouping 100p as £1. Find change by counting on from the price to the next pound, then to the note.","practise":"Pounds and pence on PopSpell.","check":"Ask the total of £2.45 and £1.70, and the change from £5."},"use":["en-money-pounds"],"home":"Let your child work out the change at the shop before the cashier does.","vocab":"pounds, pence, total, change, count on","understand":"Why is counting on a good way to find change?","lookFor":"Explains counting up from the price to the amount paid, in friendly steps, and checks by adding the change back.","cfe":{"title":"Pounds and pence: totals and change","level":"First","codes":["MNU 1-09a","MNU 1-09b"],"criteria":["I can record amounts accurately in different ways, for example, 149p = £1·49.","I can use coins and notes to pay for items and give change within £10.","I can calculate the total spent in a shopping situation, and the change."]}},
    {"id":"lesson-england-tenths-and-adding-fractions-with-the-same-denominator-years-3-and-4","england":true,"level":"First","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MNU 1-07a"],"title":"Tenths, and adding fractions with the same denominator (Years 3 and 4)","intention":"We are learning to count in tenths, and to add and subtract fractions with the same denominator.","criteria":["I can count up and down in tenths.","I know tenths come from dividing into 10 equal parts, or dividing by 10.","I can add and subtract fractions with the same denominator, and solve problems with them."],"steps":{"start":"Fold a strip into 10 equal parts. How many tenths is half?","teach":"Count in tenths on a number line from 0 to 1. Add 2/7 + 3/7 with a bar model: the parts are the same size, so add the tops. Take away the same way. Solve a cake or pizza problem.","practise":"Tenths and adding fractions on PopSpell.","check":"Ask 3/8 + 4/8, 9/10 − 3/10 and one tenth of 60."},"use":["en-fractions-add"],"home":"Cut a pizza or a bar of chocolate into equal parts and add the pieces eaten.","vocab":"tenth, numerator, denominator, equal parts, fraction","understand":"Why is 2/7 + 3/7 equal to 5/7 and not 5/14?","lookFor":"Explains that the size of the parts (sevenths) stays the same; only the number of parts changes."},
    {"id":"lesson-england-lines-and-shapes-parallel-perpendicular-and-quadrilaterals-years-3-and-4","england":true,"level":"First","subject":"Maths","strand":"Shape and angles","codes":["MTH 1-16a","MTH 2-16a"],"title":"Lines and shapes: parallel, perpendicular and quadrilaterals (Years 3 and 4)","intention":"We are learning to spot horizontal, vertical, parallel and perpendicular lines, and to sort shapes by their properties.","criteria":["I can find horizontal, vertical, parallel and perpendicular lines.","I can sort quadrilaterals and triangles by their sides and angles.","I can draw 2D shapes and make 3D shapes, and recognise them turned round."],"steps":{"start":"Look round the room: where are lines that never meet? Lines that meet at a right angle?","teach":"Name horizontal and vertical, then parallel and perpendicular, with a right-angle checker. Sort quadrilaterals (square, rectangle, rhombus, parallelogram, trapezium) and triangles (equilateral, isosceles, scalene, right-angled) by their properties. Make a cube and a pyramid from straws or modelling clay, and turn them to show they're the same shape.","practise":"Lines and shapes on PopSpell, then the \"Draw and make shapes\" sheet.","check":"Ask for a shape with one pair of parallel sides, and a triangle with two equal sides."},"use":["en-lines-shapes"],"home":"Spot parallel lines on roads, doors and books.","vocab":"horizontal, vertical, parallel, perpendicular, quadrilateral, trapezium, rhombus, isosceles","understand":"Is a square a kind of rectangle? Explain.","lookFor":"Reasons from properties: a square has four right angles and opposite sides equal, so it fits the rectangle's properties too.","cfe":{"title":"Lines and shapes: sorting by their properties","level":"First","codes":["MTH 1-16a"],"criteria":["I can name, identify and classify a range of simple 2D shapes and 3D objects and recognise them in different orientations and sizes.","I can use mathematical language to describe their properties, including side, face, edge, vertex, base and angle.","I can identify 2D shapes within 3D objects."]}},
    {"id":"lesson-england-angles-rectangles-and-accurate-drawing-years-5-and-6","england":true,"level":"Second","subject":"Maths","strand":"Shape and angles","codes":["MTH 2-17a","MTH 2-16a"],"title":"Angles, rectangles and accurate drawing (Years 5 and 6)","intention":"We are learning to use multiples of 90°, angles on a line and round a point, the properties of rectangles, and to draw shapes accurately.","criteria":["I know a right angle is 90°, and use multiples of 90°.","I can find missing angles on a line and round a point.","I can use the properties of rectangles to find missing lengths and angles.","I can draw 2D shapes with given lengths and angles."],"steps":{"start":"Turn on the spot: quarter, half, three-quarters, whole. How many degrees each time?","teach":"Show 90°, 180°, 270° and 360° as turns. Angles on a straight line add to 180° and round a point to 360°. Use a rectangle's equal opposite sides and right angles to find missing lengths. Draw a rectangle and a triangle with a ruler and protractor to exact measurements.","practise":"Angles and rectangles on PopSpell, then the \"Draw it accurately\" sheet.","check":"Ask the missing angle on a line with 125°, and the short side of a rectangle with perimeter 26 cm and long side 9 cm."},"use":["en-angles-rectangles"],"home":"Look for right angles at home and count how many in a room.","vocab":"right angle, degrees, straight line, perimeter, protractor, rectangle","understand":"A rectangle's perimeter is 30 cm. Can you find its sides without measuring? What else would you need to know?","lookFor":"Explains that half the perimeter gives one long plus one short side, and that one more length is needed to find both.","cfe":{"title":"Angles, rectangles and accurate drawing","level":"Second","codes":["MTH 2-17a","MTH 2-16c","MNU 2-11b"],"criteria":["I can describe and classify angles using acute, obtuse, straight and reflex.","I can measure and draw a range of angles to within 2°, and know supplementary angles add up to 180°.","I can use mathematical instruments to draw 2D shapes.","I can calculate the perimeter of simple straight-sided 2D shapes."]}},
    {"id":"lesson-england-counting-in-steps-and-roman-numerals-years-4-and-5","england":true,"level":"Second","subject":"Maths","strand":"Number","codes":["MNU 2-02a"],"title":"Counting in steps and Roman numerals (Years 4 and 5)","intention":"We are learning to count in steps of 6, 7, 9, 25, 1000 and powers of 10, and to read Roman numerals to 1000.","criteria":["I can count in multiples of 6, 7, 9, 25 and 1000.","I can find 1000 more or less, and count in steps of powers of 10.","I can read Roman numerals to 1000 and years written in them.","I know the Roman system had no zero, and place value changed how we write numbers."],"steps":{"start":"Count in 25s from 0 to 200. Where have you seen 25s before?","teach":"Count forwards and back in each step, spotting patterns. Find 1000 and 10 000 more or less on a place value chart. Read Roman numerals by adding (VI) and subtracting (IV), then years on buildings and films. Talk about how Roman numerals have no zero, and why our system with place value is easier for calculating.","practise":"Counting in steps and Roman numerals on PopSpell.","check":"Ask the next two numbers after 63, 70, 77, and what MCMXCV means."},"use":["en-count-steps","en-roman"],"home":"Look for Roman numerals on clocks, buildings and at the end of TV programmes.","vocab":"multiple, step, thousand, Roman numeral, place value, zero","understand":"Why is our number system easier for adding than Roman numerals?","lookFor":"Explains that place value and zero let us line up columns, while Roman numerals have no place value.","cfe":{"title":"Counting in steps, and Roman numerals","level":"Second","codes":["MNU 2-02a","MTH 2-13a","MTH 1-12a"],"criteria":["I can apply my knowledge of multiples to generate number patterns.","I can add and subtract multiples of 10, 100 and 1000 to and from whole numbers.","I can investigate and share my understanding of a number system used in history, such as Roman numerals."]}},
    {"id":"lesson-england-numbers-to-ten-million-year-6","england":true,"level":"Second","subject":"Maths","strand":"Number","codes":["MNU 2-02a"],"title":"Numbers to ten million (Year 6)","intention":"We are learning to read, write, order and compare numbers up to 10 000 000 and say what each digit is worth.","criteria":["I can read and write numbers up to 10 000 000.","I can order and compare them.","I can say what each digit is worth.","I can solve problems with large numbers."],"steps":{"start":"Read the population of Scotland or England from a news report. How do you say it?","teach":"Use a place value chart with millions, hundred thousands and so on. Group digits in threes to read them. Order numbers by comparing from the left. Solve population and distance problems.","practise":"Numbers to ten million on PopSpell.","check":"Ask the value of the 4 in 6 482 105, and to order three seven-digit numbers."},"use":["en-millions"],"home":"Find big numbers in the news and read them together.","vocab":"million, place value, digit, order, compare","understand":"Which is bigger, 2 999 999 or 3 000 000? How do you know without counting?","lookFor":"Compares from the millions digit first and explains why the first different digit decides.","cfe":{"title":"Very large numbers","level":"Second","codes":["MNU 2-02a"],"criteria":["I can read, write and order whole numbers, starting from any number in the sequence.","I can explain the link between a digit, its place and its value.","I can solve problems involving whole numbers using a range of methods."]}},
    {"id":"lesson-england-multiplication-reasoning-facts-splitting-scaling-and-combinations-years-3-to-6","england":true,"level":"Second","subject":"Maths","strand":"Number","codes":["MNU 2-03a"],"title":"Multiplication reasoning: facts, splitting, scaling and combinations (Years 3 to 6)","intention":"We are learning to use known facts, the distributive law, scaling and combinations to solve multiplication problems.","criteria":["I know what happens when multiplying by 0 and 1, and can multiply three numbers.","I can split a number to multiply, as in 23 × 4 = 20 × 4 + 3 × 4.","I can solve scaling, rate and correspondence problems."],"steps":{"start":"How many outfits can you make with 3 tops and 2 pairs of trousers? Draw them.","teach":"Show × 1 and × 0 with arrays. Multiply three numbers in an easy order. Split a two-digit number to multiply. Scale a recipe up and down, use rates (60 km in 1 hour), and count combinations with a table.","practise":"Multiplication reasoning on PopSpell.","check":"Ask 34 × 6 by splitting, how much flour for 12 people if 4 people need 200 g, and how many sandwich and drink pairs from 4 and 3."},"use":["en-mult-reasoning"],"home":"Double or halve a recipe together.","vocab":"multiply, distributive, scale, rate, combination, correspondence","understand":"Why does 23 × 4 equal 20 × 4 + 3 × 4?","lookFor":"Explains that 23 fours is 20 fours and 3 more fours, perhaps with an array split into two parts.","cfe":{"title":"Multiplication reasoning: facts, splitting and scaling","level":"Second","codes":["MNU 2-03a"],"criteria":["I can use multiplication and division facts to solve problems.","I can interpret and solve multi-step problems using the four operations."]}},
    {"id":"lesson-england-mixed-numbers-and-calculating-with-fractions-years-5-and-6","england":true,"level":"Second","subject":"Maths","strand":"Fractions, decimals and percentages","codes":["MNU 2-07a","MTH 2-07c"],"title":"Mixed numbers and calculating with fractions (Years 5 and 6)","intention":"We are learning to use mixed numbers and improper fractions, and to add, subtract, multiply and divide fractions.","criteria":["I can change between mixed numbers and improper fractions.","I can add and subtract fractions, using equivalent fractions when the denominators are different.","I can multiply fractions by whole numbers and by other fractions, and divide fractions by whole numbers.","I can write a fraction as a division and as a decimal."],"steps":{"start":"Draw 7 quarters. How many wholes is that?","teach":"Use bar models for each step: mixed and improper, then common denominators (1/3 + 1/4 = 4/12 + 3/12). Multiply by a whole number as repeated addition, and fraction by fraction as a part of a part. Divide a fraction by a whole number by sharing. Show 3/8 = 3 ÷ 8 = 0.375.","practise":"Fractions on PopSpell: Year 5, then Year 6.","check":"Ask 2 3/4 as an improper fraction, 1/2 + 1/3, 1/4 × 1/2 and 3/8 as a decimal."},"use":["en-fractions-y5","en-fractions-y6"],"home":"Cook with fractions: half of three quarters of a cup.","vocab":"mixed number, improper fraction, numerator, denominator, equivalent, common denominator","understand":"Why do we need the same denominator before adding 1/3 + 1/4?","lookFor":"Explains that the parts must be the same size to be added, and finds equivalent fractions to make them so."},
    {"id":"lesson-england-imperial-units-area-of-triangles-and-simple-formulae-years-5-and-6","england":true,"level":"Second","subject":"Maths","strand":"Measurement","codes":["MNU 2-11a","MNU 2-11c"],"title":"Imperial units, area of triangles and simple formulae (Years 5 and 6)","intention":"We are learning to use approximate imperial equivalents, convert miles and kilometres, find the area of triangles and parallelograms, and use simple formulae.","criteria":["I know rough equivalents for inches, pounds and pints.","I can convert between miles and kilometres.","I can find the area of triangles and parallelograms.","I can use a simple formula and know when a formula helps."],"steps":{"start":"Your height in feet and inches, or in centimetres: which do you know? Why are there two systems?","teach":"Use 1 inch ≈ 2.5 cm, 1 kg ≈ 2.2 pounds, 1 pint ≈ 570 ml and 5 miles ≈ 8 km. Cut a rectangle diagonally to show a triangle is half: base × height ÷ 2. Cut and slide a parallelogram into a rectangle: base × height. Write formulae in words, then letters, and substitute.","practise":"Imperial units and area and formulae on PopSpell.","check":"Ask the area of a triangle with base 10 cm and height 6 cm, and 25 miles in kilometres."},"use":["en-imperial","en-area-formulae"],"home":"Compare road signs in miles with distances in km on a map.","vocab":"inch, pound, pint, mile, kilometre, base, height, formula","understand":"Why is a triangle's area half of base × height?","lookFor":"Shows two identical triangles make a rectangle (or parallelogram) with the same base and height.","cfe":{"title":"Imperial units, area and simple formulae","level":"Second","codes":["MNU 2-11b","MNU 2-11c","MTH 2-15a"],"criteria":["I can show awareness of imperial units used in everyday life, for example, miles or stones.","I can calculate the area of squares, rectangles and right-angled triangles.","I can solve simple algebraic equations with one variable."]}},
    {"id":"lesson-england-ratio-and-proportion-year-6","england":true,"level":"Second","subject":"Maths","strand":"Fractions, decimals and percentages","codes":[],"title":"Ratio and proportion (Year 6)","intention":"We are learning to solve problems with relative sizes, unequal sharing and similar shapes.","criteria":["I can solve problems where one quantity is a multiple of another.","I can share in a ratio and solve unequal sharing problems.","I can use a scale factor with similar shapes."],"steps":{"start":"For every 2 cups of flour you need 1 egg. How many eggs for 6 cups?","teach":"Use bar models: 'Ali has 3 times as many as Sam' becomes 1 bar and 3 bars. Share in a ratio by counting parts. Enlarge a shape on squared paper by a scale factor and compare the sides.","practise":"Ratio on PopSpell.","check":"Ask to share 35 in the ratio 2 : 5, and the new length when a 4 cm side is enlarged by 3."},"use":["en-ratio"],"home":"Mix squash or paint in a ratio, such as 1 part to 4.","vocab":"ratio, proportion, share, part, scale factor, similar","understand":"If the ratio of red to blue is 2 : 3, what fraction of the beads are red? Why isn't it 2/3?","lookFor":"Explains there are 5 parts altogether, so red is 2/5; the ratio compares parts with each other, not with the whole."},
    {"id":"lesson-england-the-mean-multi-step-problems-and-long-division-years-5-and-6","england":true,"level":"Second","subject":"Maths","strand":"Data and chance","codes":["MNU 2-20a","MNU 2-03a"],"title":"The mean, multi-step problems and long division (Years 5 and 6)","intention":"We are learning to calculate and interpret the mean, solve multi-step problems, and divide by a two-digit number.","criteria":["I can calculate the mean and say what it tells us.","I can solve multi-step problems, choosing the operations and methods.","I can do mental calculations with mixed operations.","I can divide by a two-digit number and interpret remainders."],"steps":{"start":"Three friends have 4, 6 and 8 sweets. How could they share fairly?","teach":"Show the mean as levelling out towers of cubes, then as total ÷ how many. Model multi-step problems with a bar model and say each step. Divide 4-digit numbers by 2-digit numbers, and decide whether to round a remainder up or down in context.","practise":"The mean, and multi-step problems on PopSpell.","check":"Ask the mean of 12, 15 and 9, and how many 52-seat coaches carry 300 people."},"use":["en-mean","en-multistep"],"home":"Work out the mean of the family's ages or the week's temperatures.","vocab":"mean, average, total, remainder, multi-step, operation","understand":"The mean of five scores is 7. Does anyone have to have scored 7? Why?","lookFor":"Explains the mean is the total shared equally, so no single score has to equal it."},
    {"id":"lesson-england-coordinates-plotting-translating-and-reflecting-years-4-to-6","england":true,"level":"Second","subject":"Maths","strand":"Shape and angles","codes":["MTH 2-18a"],"title":"Coordinates: plotting, translating and reflecting (Years 4 to 6)","intention":"We are learning to plot points to complete shapes, describe translations, and reflect shapes in the axes.","criteria":["I can plot points to complete a polygon.","I can describe a translation, such as 3 right and 2 up.","I can draw and translate shapes on a coordinate grid, and reflect them in the axes."],"steps":{"start":"Along the corridor, then up the stairs: which coordinate comes first?","teach":"Plot three corners of a rectangle and find the fourth. Move a shape and describe the translation. Extend the axes to negative numbers and reflect a point in each axis: which number changes sign?","practise":"Coordinates on PopSpell.","check":"Ask where (2, 5) goes after moving 3 right and 4 down, and its reflection in the x-axis."},"use":["en-coordinates"],"home":"Play battleships on squared paper.","vocab":"coordinate, axis, plot, translation, reflection, quadrant","understand":"When you reflect a point in the x-axis, which number changes, and why?","lookFor":"Explains that the point stays the same distance from the axis on the other side, so the second (y) number changes sign.","cfe":{"title":"Coordinates and moving shapes","level":"Second","codes":["MTH 2-18a"],"criteria":["I can describe, plot and record the location of a point in the first quadrant using coordinate notation.","I can identify and illustrate line symmetry, and complete symmetrical patterns."]}},
    {"id":"lesson-england-getting-ready-to-write-cutting-drawing-and-forming-digits-reception-and-year-1","england":true,"level":"Early","subject":"Literacy","strand":"Handwriting","codes":["LIT 0-21a"],"title":"Getting ready to write: cutting, drawing and forming digits (Reception and Year 1)","intention":"We are learning to use scissors and other small tools with care, draw carefully, and form the digits 0 to 9.","criteria":["I can use scissors, a paintbrush and cutlery safely.","I can draw with care and accuracy.","I can form the digits 0 to 9, starting in the right place."],"steps":{"start":"Squeeze and stretch: playdough, pegs and tweezers to warm up your fingers.","teach":"Show how to hold scissors and turn the paper, not the scissors, to cut along a line. Draw carefully, slowly and inside the lines. Model each digit, saying where it starts, and trace it in the air.","practise":"The \"Cut, draw and write numbers\" sheet.","check":"Watch them cut a curved line and write 0 to 9, starting each digit in the right place."},"use":[],"home":"Cut out pictures from a catalogue, and help to set the table with a knife and fork.","vocab":"scissors, cut, draw, careful, digit, start","understand":"Why do we turn the paper, not the scissors, when we cut round a curve?","lookFor":"Explains or shows that turning the paper keeps the cutting hand steady and the line accurate.","cfe":{"title":"Getting ready to write: cutting, drawing and numerals","level":"Early","codes":["LIT 0-21b"],"criteria":["I can use a pencil with increasing control and confidence.","I can form most letters legibly, and know the difference between a letter, a word and a numeral."]}},
    {"id":"lesson-england-the-alphabet-letter-names-and-the-days-of-the-week-year-1","england":true,"level":"First","subject":"Literacy","strand":"Spelling","codes":["LIT 1-21a"],"title":"The alphabet, letter names and the days of the week (Year 1)","intention":"We are learning to name the letters of the alphabet in order, use letter names to talk about spellings, and spell the days of the week.","criteria":["I can name the letters of the alphabet in order.","I can use letter names to tell different spellings of the same sound apart.","I can spell the days of the week."],"steps":{"start":"Sing or say the alphabet. Which letter comes after p? Before k?","teach":"Lay out letter cards in order and play 'what's missing'. Show that rain and play have the same sound spelled a-i and a-y, saying the letter names. Learn the days of the week, noticing the tricky parts (the d in Wednesday) and that each starts with a capital letter.","practise":"The alphabet on PopSpell, then the days of the week list.","check":"Ask what comes before m, which letters spell the sound in 'boat', and to write Monday and Wednesday."},"use":["en-alphabet","y1-days"],"home":"Say the days of the week at breakfast, and find words in a children's dictionary.","vocab":"alphabet, letter name, sound, capital letter, days of the week","understand":"Why do we use letter names, not sounds, when we spell out a word?","lookFor":"Explains that the same sound can be spelled in different ways, and letter names say exactly which letters to write.","cfe":{"title":"The alphabet, letter names and the days of the week","level":"First","codes":["LIT 1-21a","MNU 0-10a"],"criteria":["I can use my knowledge of the alphabet to find words in a dictionary or other reference source.","I can use phonics and spelling strategies when spelling familiar and unfamiliar words.","I can name the days of the week in sequence."]}},
    {"id":"lesson-england-reading-longer-words-and-checking-it-makes-sense-years-1-and-2","england":true,"level":"First","subject":"Literacy","strand":"Reading: phonics and tricky words","codes":["ENG 1-12a","LIT 1-13a"],"title":"Reading longer words, and checking it makes sense (Years 1 and 2)","intention":"We are learning to read longer words by splitting them into parts, and to check that what we read makes sense.","criteria":["I can read words with two or more syllables by splitting them into parts.","I can use the sounds I know to read new words until it's automatic.","I can notice when a sentence doesn't make sense and fix my reading."],"steps":{"start":"Clap the beats: rab-bit, gar-den, sand-wich. How many parts?","teach":"Split long words into syllables, read each part with the sounds you know, then blend the parts. Read a sentence with a mistake in it and ask: does that make sense? Go back and reread the word.","practise":"The \"Longer words\" sheet, then read a decodable story.","check":"Ask them to read five two-syllable words, and to spot and fix the wrong word in a sentence."},"use":["s-d-boat","s-d-puddle"],"home":"When reading together, stop if something doesn't make sense and ask what went wrong.","vocab":"syllable, blend, reread, check, makes sense","understand":"You read 'The dog barked at the cat' as 'The dog bark at the car'. How would you know something was wrong?","lookFor":"Uses meaning to notice the error (cars don't get barked at in the story; it doesn't sound right), then rereads the words carefully.","cfe":{"title":"Reading longer words, and checking it makes sense","level":"First","codes":["ENG 1-12a","LIT 1-13a"],"criteria":["I can decode unknown words by locating and pronouncing familiar letter patterns and blends.","I can use a range of word recognition strategies independently.","I can use context clues to read and understand texts."]}},
    {"id":"lesson-england-traditional-tales-retelling-and-story-language-years-1-and-2","england":true,"level":"First","subject":"Literacy","strand":"Reading: understanding stories","codes":["ENG 1-17a","LIT 1-16a"],"title":"Traditional tales: retelling and story language (Years 1 and 2)","intention":"We are learning to retell traditional tales, notice their story language, and talk about how events link together.","criteria":["I can retell a traditional tale in order.","I can spot story language, such as once upon a time and repeated lines.","I can say what is typical of a traditional tale.","I can say how the events in a story are linked."],"steps":{"start":"Who's that trip-trapping over my bridge? Do you know the story?","teach":"Read the tale on the sheet together. Act it out with puppets, saying the repeated lines. Put the events in order and talk about why each one leads to the next. Compare with another traditional tale: what's the same?","practise":"The \"Three Billy Goats Gruff\" sheet: order the events, story language, and retell it.","check":"Ask them to retell the tale in order using first, next, then and in the end."},"use":[],"home":"Read a different traditional tale at bedtime and compare it with this one.","vocab":"traditional tale, retell, once upon a time, repeat, beginning, middle, end","understand":"Why does the troll let the first two goats go?","lookFor":"Links events: the little goats promise a bigger goat is coming, which leads to the ending.","cfe":{"title":"Traditional tales: retelling and story language","level":"First","codes":["ENG 1-19a","LIT 1-16a"],"criteria":["I can identify the main ideas of a text.","I can offer my own ideas about characters, the writer's use of language, structure and setting.","I can answer literal, inferential and evaluative questions about a text."]}},
    {"id":"lesson-england-words-and-what-they-mean-years-1-to-6","england":true,"level":"First","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 1-16a"],"title":"Words and what they mean (Years 1 to 6)","intention":"We are learning to work out what words mean, talk about favourite words and phrases, and check meanings in a dictionary.","criteria":["I can work out what a word means from the words around it.","I can link a new word to words I already know.","I can talk about words and phrases I like and why.","I can check a word's meaning in a dictionary."],"steps":{"start":"'The giant was colossal.' What might colossal mean? What helped you?","teach":"Read the short text on the sheet. For each new word, look for clues around it, think of a word like it, then check in a dictionary. Collect favourite words and phrases and say what they add.","practise":"The \"Word detective\" sheet.","check":"Ask them to explain two words from the text and how they worked them out."},"use":[],"home":"Pick a 'word of the day' from a book and try to use it at teatime.","vocab":"meaning, clue, context, dictionary, definition, phrase","understand":"How did the sentence help you work out the word's meaning?","lookFor":"Points to a clue in the sentence and explains how it narrows the meaning, then checks it.","cfe":{"title":"Words and what they mean","level":"First","codes":["LIT 1-13a","LIT 1-21a","ENG 1-19a"],"criteria":["I can use context clues to read and understand texts.","I can use my knowledge of the alphabet to find words in a dictionary.","I can comment on the writer's choice of words."]}},
    {"id":"lesson-england-poems-to-learn-say-and-write-year-2","england":true,"level":"First","subject":"Literacy","strand":"Writing: creating texts","codes":["ENG 1-31a"],"title":"Poems to learn, say and write (Year 2)","intention":"We are learning to learn poems by heart and say them with expression, and to write a poem of our own.","criteria":["I can learn a short poem by heart.","I can say it with the right intonation so the meaning is clear.","I can write a short poem of my own."],"steps":{"start":"Say a rhyme you know. How did you remember it?","teach":"Read the poem on the sheet together. Learn it a line at a time, with actions. Practise saying it with expression: loud, quiet, slow, fast. Then write your own poem using the same pattern.","practise":"The \"Poems\" sheet: learn the poem, then write one of your own.","check":"Listen to them say the poem from memory with expression, and read their own poem."},"use":[],"home":"Say the poem together on the way to school until it's learned.","vocab":"poem, rhyme, rhythm, verse, line, expression","understand":"Why did you say that line louder (or more slowly)?","lookFor":"Links how they say it to the meaning or feeling of the line.","cfe":{"title":"Poems to learn, say and write","level":"First","codes":["ENG 1-31a","LIT 1-13a"],"criteria":["I can read aloud a familiar piece of text, adding expression, and show understanding.","I can create my own poem with recognisable features of the genre."]}},
    {"id":"lesson-england-poetry-forms-and-performing-poems-years-3-to-6","england":true,"level":"Second","subject":"Literacy","strand":"Reading: understanding stories","codes":["ENG 2-19a","ENG 2-31a"],"title":"Poetry forms, and performing poems (Years 3 to 6)","intention":"We are learning to recognise different forms of poetry, learn poems by heart, and perform poems and our own writing to an audience.","criteria":["I can recognise some forms of poetry, such as free verse and narrative poetry.","I can learn a wider range of poems by heart.","I can perform a poem or my own writing with intonation, tone, volume and movement so the meaning is clear."],"steps":{"start":"Is a poem always rhyming? What else can make it a poem?","teach":"Compare the two poems on the sheet: one tells a story (narrative), one doesn't rhyme or keep a pattern (free verse). Learn one by heart, then mark the performance: where to pause, get louder or quieter, and gesture. Perform it, then perform a piece of your own writing.","practise":"The \"Perform a poem\" sheet.","check":"Watch the performance and ask: what form is it, and how did your performance show its meaning?"},"use":[],"home":"Perform the poem for the family after tea.","vocab":"free verse, narrative poem, form, perform, intonation, tone, volume","understand":"How is a narrative poem like a story, and how is it different?","lookFor":"Explains it tells a story with characters and events, but uses lines, rhythm and poetic language.","cfe":{"title":"Kinds of poem, and performing poetry","level":"Second","codes":["ENG 2-19a","LIT 2-13a","ENG 2-03a"],"criteria":["I can make relevant comments about the writer's style, use of language and features of the genre.","I can read with fluency, understanding and expression, using appropriate pace and tone.","I can apply verbal and non-verbal techniques when I present to others."]}},
    {"id":"lesson-england-talking-about-my-writing-saying-it-reading-it-aloud-and-improving-it-years-1-and-2","england":true,"level":"First","subject":"Literacy","strand":"Writing: creating texts","codes":["LIT 1-23a","LIT 1-10a"],"title":"Talking about my writing: saying it, reading it aloud and improving it (Years 1 and 2)","intention":"We are learning to say our sentences before we write them, read our writing aloud, and talk about how to improve it.","criteria":["I can say each sentence out loud before I write it.","I can read my writing aloud clearly, with the right intonation.","I can talk about my writing with an adult and make changes."],"steps":{"start":"Tell me one sentence about your weekend. Say it again in the same words.","teach":"Say a sentence, hold it in your head, write it, then read it back. Read your writing aloud to the adult, clearly and with expression. Talk about one thing that's good and one thing to change, then make the change.","practise":"The \"Say it, write it, read it\" sheet.","check":"Ask them to read their writing aloud, and say one change they made and why."},"use":[],"home":"Ask your child to read their homework to you, and say what you liked.","vocab":"say, write, read aloud, check, improve, change","understand":"Why is it useful to say a sentence before you write it?","lookFor":"Explains that it helps them remember the whole sentence and check it makes sense before writing.","cfe":{"title":"Talking about my writing: saying it, reading it aloud and improving it","level":"First","codes":["LIT 1-23a","LIT 1-10a"],"criteria":["I can check my writing to make sure it makes sense.","I can communicate clearly and audibly.","I can share my ideas and information in a logical order."]}},
    {"id":"lesson-england-expanded-noun-phrases-years-2-5-and-6","england":true,"level":"First","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 1-22a"],"title":"Expanded noun phrases (Years 2, 5 and 6)","intention":"We are learning to add words before and after a noun to describe and specify it.","criteria":["I can add adjectives to describe a noun, as in the blue butterfly.","I can add a phrase after the noun, as in the man with a stick.","I can use expanded noun phrases to give lots of information in few words."],"steps":{"start":"Show a picture. 'A dog.' Can you tell me more about it in the same phrase?","teach":"Build noun phrases on a frame: determiner, adjectives, noun, then a phrase after it. Compare 'the house' with 'the old house at the end of the lane'. For older pupils, rewrite a long sentence as one concise noun phrase.","practise":"Expanded noun phrases on PopSpell.","check":"Ask them to expand 'the car' two ways, and say which tells the reader more."},"use":["eg-noun-phrases"],"home":"Describe things in the street with as much detail as you can in one phrase.","vocab":"noun, adjective, noun phrase, expand, describe, specify","understand":"Why might a writer use 'the girl in the red coat' instead of 'the girl'?","lookFor":"Explains it tells the reader which girl, or helps them picture her, without needing another sentence.","cfe":{"title":"Describing words: noun phrases","level":"First","codes":["LIT 1-26a"],"criteria":["I can use relevant and interesting vocabulary as appropriate for the context.","I can include relevant information in my writing."]}},
    {"id":"lesson-england-homophones-years-2-to-6","england":true,"level":"Second","subject":"Literacy","strand":"Spelling","codes":["LIT 2-21a"],"title":"Homophones (Years 2 to 6)","intention":"We are learning to spell homophones and words that are often confused, and choose the right one for the meaning.","criteria":["I can spell common homophones, such as there, their and they're.","I can spell further homophones from the Years 3 and 4 list.","I can tell apart words that are often confused, such as affect and effect."],"steps":{"start":"'I can see the sea.' Which see is which? How do you know?","teach":"Sort homophone pairs into sentences. Make a memory trick for each, such as 'hear' has 'ear' in it, or stationery has e for envelopes. Use each in a sentence of your own.","practise":"Homophones on PopSpell: the set for the pupil's year.","check":"Dictate three sentences with homophones in them and check the choice."},"use":["eg-homophones-y2","eg-homophones-y34","eg-homophones-y56"],"home":"Spot homophones on signs and menus, and check they're right.","vocab":"homophone, sound the same, spelled differently, meaning","understand":"How will you remember which 'there' to use?","lookFor":"Gives a reliable memory trick linked to meaning (here, there and where are places; their has 'heir', owning).","cfe":{"title":"Homophones: words that sound the same","level":"Second","codes":["LIT 2-21a"],"criteria":["I can apply my knowledge of spelling patterns, rules and strategies to spell most words correctly."]}},
    {"id":"lesson-england-myths-legends-and-themes-across-books-years-3-to-6","england":true,"level":"Second","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 2-16a","ENG 2-19a"],"title":"Myths, legends and themes across books (Years 3 to 6)","intention":"We are learning to read myths and legends, retell them, and identify and compare themes and conventions across books.","criteria":["I can retell a myth or legend in my own words.","I can spot the conventions of myths and legends.","I can identify themes, such as courage or greed, and compare them across books.","I can read a wide range of books, including stories from other cultures."],"steps":{"start":"What's the difference between a myth and a legend? Have you heard of any?","teach":"Read the myth on the sheet. Retell it aloud. Note its conventions: gods or magic, an explanation of something in nature. Talk about its theme, then compare it with another story the pupil knows that has the same theme.","practise":"The \"Myths and themes\" sheet.","check":"Ask them to name the theme, give evidence, and compare it with another book."},"use":[],"home":"Read a myth or legend from another culture together.","vocab":"myth, legend, theme, convention, compare, culture","understand":"What lesson or theme does this myth share with another story you know?","lookFor":"Names a theme and backs it with evidence from both stories.","cfe":{"title":"Myths, legends and themes","level":"Second","codes":["ENG 2-19a","LIT 2-16a"],"criteria":["I can make relevant comments about structure, characterisation and setting, with reference to the text.","I can relate the writer's theme to my own and others' experiences.","I can respond to literal, inferential and evaluative questions about a text."]}},
    {"id":"lesson-england-asking-questions-and-checking-understanding-as-i-read-years-3-to-6","england":true,"level":"Second","subject":"Literacy","strand":"Reading: understanding stories","codes":["LIT 2-16a","LIT 2-13a"],"title":"Asking questions and checking understanding as I read (Years 3 to 6)","intention":"We are learning to ask questions as we read, check the text makes sense, and discuss our understanding.","criteria":["I can ask questions before, during and after reading to help me understand.","I can check the text makes sense and explain words in context.","I can take part in discussion about books, taking turns and listening."],"steps":{"start":"Look at a title. What questions do you have before you read?","teach":"Read the text on the sheet in parts. Before: what do you expect? During: stop and ask a question, and check you understand. After: what's still puzzling? Discuss your answers, taking turns.","practise":"The \"Questions as I read\" sheet.","check":"Ask for one question from before, during and after reading, and how they found the answers."},"use":[],"home":"When reading together, each ask one question about the story.","vocab":"question, predict, check, understand, discuss, context","understand":"Which of your questions helped you most, and why?","lookFor":"Explains how a question focused their reading or sorted out a misunderstanding.","cfe":{"title":"Asking questions and checking understanding as I read","level":"Second","codes":["LIT 2-16a","LIT 2-13a"],"criteria":["I can create different types of questions to show my understanding of a text.","I can respond to literal, inferential and evaluative questions.","I can apply reading strategies such as predicting, clarifying and summarising."]}},
    {"id":"lesson-england-planning-from-a-model-rehearsing-aloud-and-improving-years-3-and-4","england":true,"level":"Second","subject":"Literacy","strand":"Writing: creating texts","codes":["LIT 2-23a","LIT 2-26a"],"title":"Planning from a model, rehearsing aloud and improving (Years 3 and 4)","intention":"We are learning to plan by studying a model text, rehearse sentences aloud, and improve our writing, including using pronouns for clarity.","criteria":["I can discuss a model text to learn from its structure and vocabulary.","I can say my sentences aloud before I write them, including dialogue.","I can improve my writing, choosing nouns or pronouns for clarity.","I can read my writing aloud with the right intonation."],"steps":{"start":"Read a short paragraph. What did the writer do that you could borrow?","teach":"Discuss the model on the sheet: structure, vocabulary, sentence types. Plan your own version. Say each sentence aloud before writing it. Then improve it: is it clear who 'he' or 'she' is? Read the final version aloud.","practise":"Nouns or pronouns on PopSpell, then the \"Learn from a model\" sheet.","check":"Listen to them read their writing aloud and ask what they changed and why."},"use":["eg-pronouns"],"home":"Read a favourite author's paragraph and talk about the words they chose.","vocab":"model, structure, rehearse, pronoun, clarity, improve","understand":"When is it better to use the name instead of 'he' or 'she'?","lookFor":"Explains that a name is clearer when a pronoun could mean more than one person.","cfe":{"title":"Learning from a model, rehearsing aloud and improving","level":"Second","codes":["LIT 2-23a","LIT 2-26a"],"criteria":["I can organise information in a logical way.","I can write most sentences in a grammatically accurate way.","I can review and correct my writing to make sure it makes sense, is technically accurate and meets its purpose."]}},
    {"id":"lesson-england-editing-and-proofreading-tense-the-perfect-form-and-effect-years-5-and-6","england":true,"level":"Second","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":["LIT 2-23a"],"title":"Editing and proofreading: tense, the perfect form and effect (Years 5 and 6)","intention":"We are learning to edit our writing for consistent tense and the perfect form, proofread for errors, and judge how effective it is.","criteria":["I can keep the tense consistent throughout a piece of writing.","I can use the perfect form of verbs to show time and cause.","I can proofread for spelling and punctuation errors.","I can assess how effective my own and others' writing is."],"steps":{"start":"Read: 'Yesterday I go to the park and played football.' What's wrong?","teach":"Edit the paragraph on the sheet in three passes: tense, then spelling and punctuation, then effect (does it do what the writer wanted?). Use the perfect form to show what had happened first. Then edit a piece of your own writing the same way.","practise":"Tense and the perfect form on PopSpell, then the \"Edit it\" sheet.","check":"Ask them to edit a paragraph and explain each change."},"use":["eg-tense-perfect"],"home":"Proofread a shopping list or a birthday card together.","vocab":"tense, perfect form, proofread, edit, effective","understand":"Why did the writer use 'had started' and not 'started'?","lookFor":"Explains the past perfect shows that one event happened before another.","cfe":{"title":"Editing and proofreading","level":"Second","codes":["LIT 2-23a","LIT 2-21a"],"criteria":["I can review and correct my writing to make sure it makes sense, is technically accurate and meets its purpose.","I can write most sentences in a grammatically accurate way.","I can apply my knowledge of spelling patterns, rules and strategies to spell most words correctly."]}},
    {"id":"lesson-england-powers-roots-indices-and-standard-form-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Number","codes":[],"title":"Powers, roots, indices and standard form (Years 10 and 11)","intention":"We are learning to calculate with powers and roots, use the laws of indices, and calculate with numbers in standard form.","criteria":["I can calculate with roots, and with integer indices, including zero and negative indices.","I can use the laws of indices to simplify expressions involving sums, products and powers.","I can calculate with numbers in standard form A × 10ⁿ, where 1 ≤ A < 10 and n is an integer.","I can estimate powers and roots of any given positive number, and calculate with fractional indices (higher)."],"steps":{"start":"Which is bigger, 2¹⁰ or 10³? How can you tell without a calculator?","teach":"Build the laws from what a power means: 2³ × 2⁴ is seven 2s multiplied, so add the indices; dividing subtracts them; (2³)² = 2⁶. Halve down the pattern 2³, 2², 2¹, 2⁰, 2⁻¹ to show that 2⁰ = 1 and 2⁻¹ = ½. Use the laws in algebra: x⁵ × x³ = x⁸ and (3a²)³ = 27a⁶. Write 45 000 and 0.0062 in standard form, then multiply and divide in standard form by dealing with the numbers and the powers of 10 separately, adjusting the answer if needed. Higher: 8^⅔ is (∛8)² = 4, and √50 is just over 7, as 7² = 49.","practise":"The \"Powers, roots and standard form\" sheet.","check":"Ask for 5⁰, 4⁻², (2 × 10³) × (6 × 10⁴) in standard form, and y⁷ ÷ y² simplified."},"use":[],"home":"Find very large and very small numbers in science or the news (the distance to the Sun, the width of a hair) and write them in standard form.","vocab":"power, index, indices, root, reciprocal, standard form, estimate","understand":"Why is 2⁰ equal to 1, not 0?","lookFor":"Uses the pattern of halving (2², 2¹, 2⁰) or the division law (2³ ÷ 2³ = 2⁰, and anything divided by itself is 1)."},
    {"id":"lesson-england-exact-calculation-fractions-surds-and-recurring-decimals-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Fractions, decimals and percentages","codes":[],"title":"Exact calculation: fractions, surds, π and recurring decimals (Years 10 and 11)","intention":"We are learning to give exact answers using fractions, surds and multiples of π, and to change between recurring decimals and fractions.","criteria":["I can calculate exactly with fractions and multiples of π.","I can calculate exactly with surds, simplify surd expressions involving squares, and rationalise denominators (higher).","I can change recurring decimals into their corresponding fractions and vice versa (higher)."],"steps":{"start":"A circle has a radius of 3 cm. What is its area, exactly, without a calculator?","teach":"Show why 9π cm² is more accurate than 28.27 cm², and keep answers as fractions: ⅔ of ⅗ is ⅖. Higher: a surd is a root that isn't a whole number. Simplify using square factors: √12 = √(4 × 3) = √4 × √3 = 2√3; then √3 × √3 = 3, so 6/√3 = 6√3/3 = 2√3. Divide 7 by 11 to get 0.636363…, then go back the other way: if x = 0.4545…, then 100x = 45.4545…, so 99x = 45 and x = 45/99 = 5/11.","practise":"The \"Exact answers\" sheet.","check":"Ask for the exact circumference of a circle with diameter 8, √50 simplified, and 0.777… as a fraction."},"use":[],"home":"Use a calculator's fraction or exact mode to check some answers, and talk about when an exact answer matters.","vocab":"exact, surd, rationalise, multiple of π, recurring decimal, terminating decimal","understand":"Why is 6π cm a better answer than 18.8 cm when you're asked for an exact length?","lookFor":"Explains that 18.8 is rounded, so it's slightly wrong, while 6π is exactly right and can be rounded later if needed."},
    {"id":"lesson-england-limits-of-accuracy-rounding-truncating-and-bounds-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Number","codes":[],"title":"Limits of accuracy: rounding, truncating and bounds (Years 10 and 11)","intention":"We are learning to say how accurate a measurement is, and to find the largest and smallest values a calculation could give.","criteria":["I can apply and interpret limits of accuracy when rounding or truncating.","I can write an error interval using inequality notation.","I can use upper and lower bounds in calculations (higher)."],"steps":{"start":"A length is 7 cm to the nearest centimetre. What could it actually be?","teach":"Show 6.5 ≤ l < 7.5 on a number line: half a unit either side, with the upper value not included. Compare truncating, which just cuts digits off: a number truncated to 7 could be anything from 7 up to (but not including) 8. Higher: ask which values make an answer as big as possible. For a perimeter, add the upper bounds; for a speed (distance ÷ time), divide the upper bound of the distance by the lower bound of the time.","practise":"The \"How accurate?\" sheet.","check":"A mass is 4.3 kg to 1 decimal place: write its error interval. A rectangle is 8 cm by 5 cm, both to the nearest centimetre: find the upper bound of its area."},"use":[],"home":"Look at a food label. If the pack says 500 g, what range of masses might it really hold?","vocab":"limit of accuracy, error interval, round, truncate, upper bound, lower bound","understand":"To get the smallest possible answer to a ÷ b, which bounds of a and b do you use? Why?","lookFor":"Explains that dividing the smallest a by the largest b gives the smallest answer, because a bigger divisor makes the answer smaller."},
    {"id":"lesson-england-factorising-quadratics-and-algebraic-fractions-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Patterns and missing numbers","codes":[],"title":"Factorising quadratics and algebraic fractions (Years 10 and 11)","intention":"We are learning to factorise quadratic expressions and to simplify expressions, including algebraic fractions.","criteria":["I can simplify and manipulate algebraic expressions, including those involving surds and algebraic fractions (higher).","I can factorise quadratic expressions of the form x² + bx + c, including the difference of two squares.","I can factorise quadratic expressions of the form ax² + bx + c (higher)."],"steps":{"start":"Expand (x + 3)(x + 5). Now work backwards: what multiplies out to x² + 8x + 15?","teach":"Expand with a grid, then reverse it: for x² + bx + c, find two numbers that multiply to c and add to b, so x² + 7x + 12 = (x + 3)(x + 4) and x² − 2x − 15 = (x − 5)(x + 3). Show the difference of two squares: x² − 49 = (x + 7)(x − 7). Higher: for 2x² + 7x + 3, split the middle term: 2x² + 6x + x + 3 = 2x(x + 3) + 1(x + 3) = (2x + 1)(x + 3). Simplify an algebraic fraction by factorising and then cancelling: (x² − 9)/(x + 3) = x − 3.","practise":"The \"Factorise it\" sheet.","check":"Ask them to factorise x² + 5x + 6 and x² − 16 (and 3x² + 10x + 8, higher), checking each by expanding."},"use":[],"home":"Make up a quadratic by expanding two brackets, and challenge someone at home to factorise it.","vocab":"expand, factorise, quadratic, coefficient, difference of two squares, algebraic fraction","understand":"How do you know (x + 3)(x + 4) is right for x² + 7x + 12, and not (x + 2)(x + 6)?","lookFor":"Checks by expanding: both pairs multiply to 12, but only 3 and 4 add to 7, the middle coefficient."},
    {"id":"lesson-england-identities-algebraic-proof-and-functions-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Patterns and missing numbers","codes":[],"title":"Identities, algebraic proof and functions (Years 10 and 11)","intention":"We are learning the difference between an equation and an identity, to use algebra to prove things, and to think of expressions as functions.","criteria":["I know the difference between an equation and an identity.","I can argue mathematically to show algebraic expressions are equivalent, and use algebra to support and construct arguments and proofs.","I can interpret simple expressions as functions with inputs and outputs.","I can interpret the reverse process as the inverse function, and the succession of two functions as a composite function (higher)."],"steps":{"start":"Is 3(x + 2) = 3x + 6 true for every value of x? Is 3x + 2 = 11?","teach":"Sort statements into equations (true for some values) and identities (true for every value, written with ≡). Prove that the sum of three consecutive whole numbers is a multiple of 3: n + (n + 1) + (n + 2) = 3n + 3 = 3(n + 1). Use 2n for an even number and 2n + 1 for an odd one. Show a function as a machine: f(x) = 2x + 3, so f(4) = 11. Higher: run the machine backwards for the inverse, f⁻¹(x) = (x − 3)/2, and join machines for a composite: if g(x) = x², then fg(x) = 2x² + 3 but gf(x) = (2x + 3)².","practise":"The \"Prove it\" sheet.","check":"Is (x + 1)² ≡ x² + 1? Why? Prove that the sum of two odd numbers is even."},"use":[],"home":"Try a number trick (think of a number, double it, add 6, halve it, take away the number you started with) and prove with algebra why the answer is always 3.","vocab":"equation, identity, proof, consecutive, function, input, output, inverse, composite","understand":"Why don't five examples that work prove that something is always true?","lookFor":"Explains that examples only show it works for those numbers; algebra (using n) shows it for every number, and one counter-example disproves it."},
    {"id":"lesson-england-straight-line-graphs-y-mx-c-parallel-and-perpendicular-lines-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Patterns and missing numbers","codes":[],"title":"Straight-line graphs: y = mx + c, parallel and perpendicular lines (Years 10 and 11)","intention":"We are learning to use y = mx + c to find and compare straight lines, and to read a gradient as a rate of change.","criteria":["I can use the form y = mx + c to identify parallel lines, and perpendicular lines (higher).","I can find the equation of the line through two given points, or through one point with a given gradient.","I can interpret the gradient of a straight line graph as a rate of change.","I can recognise and use the equation of a circle with centre at the origin, and find the equation of a tangent to a circle at a given point (higher)."],"steps":{"start":"Which of these lines are parallel: y = 3x + 1, y = 2x + 3, y = 3x − 4? How do you know?","teach":"Gradient = change in y ÷ change in x. For the line through (1, 5) and (3, 9), m = 4 ÷ 2 = 2; substitute a point to find c: 5 = 2 × 1 + c, so c = 3 and y = 2x + 3. Parallel lines have the same gradient. On a graph of a taxi fare, the gradient is the cost per mile and the intercept is the fixed charge. Higher: perpendicular gradients multiply to −1 (2 and −½). x² + y² = 25 is a circle of radius 5; the tangent at (3, 4) is perpendicular to the radius, whose gradient is 4/3, so the tangent's gradient is −¾ and its equation is y − 4 = −¾(x − 3).","practise":"The \"Lines and gradients\" sheet.","check":"Ask for the equation of the line through (0, −1) and (2, 7), and the gradient of a line perpendicular to it (higher)."},"use":[],"home":"Find a real straight-line relationship (a phone plan, a taxi fare) and say what its gradient and intercept mean.","vocab":"gradient, intercept, parallel, perpendicular, rate of change, tangent, radius","understand":"On a graph of a phone bill against minutes used, what do the gradient and the intercept mean?","lookFor":"Explains the gradient is the cost per minute (the rate of change) and the intercept is the fixed charge when no minutes are used."},
    {"id":"lesson-england-quadratics-roots-turning-points-and-solving-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Patterns and missing numbers","codes":[],"title":"Quadratics: roots, turning points and solving (Years 10 and 11)","intention":"We are learning to solve quadratic equations and to link their solutions to the graph.","criteria":["I can solve quadratic equations algebraically by factorising, and find approximate solutions using a graph.","I can identify and interpret roots, intercepts and turning points of quadratic functions graphically, and deduce roots algebraically.","I can solve quadratic equations by completing the square and by using the quadratic formula, and deduce turning points by completing the square (higher).","I know the quadratic formula: the solutions of ax² + bx + c = 0 are x = (−b ± √(b² − 4ac)) / 2a."],"steps":{"start":"If a × b = 0, what can you say about a or b?","teach":"Factorise and use the zero product: x² − 5x + 6 = 0 gives (x − 2)(x − 3) = 0, so x = 2 or x = 3. Sketch y = x² − 5x + 6: the roots are where it crosses the x-axis, the y-intercept is 6, and the turning point is halfway between the roots, at x = 2.5. Higher: complete the square, x² − 6x + 2 = (x − 3)² − 7, so the turning point is (3, −7) and x = 3 ± √7. When it won't factorise, use the formula: 2x² + 3x − 4 = 0 gives x = (−3 ± √41)/4, so x ≈ 0.85 or x ≈ −2.35.","practise":"The \"Solve the quadratic\" sheet.","check":"Solve x² + x − 12 = 0. Where does y = x² + x − 12 cross each axis?"},"use":[],"home":"Throw a ball and sketch its path. Where would the roots and the turning point be, and what do they mean?","vocab":"quadratic, root, solution, intercept, turning point, factorise, completing the square, quadratic formula","understand":"Why do we rearrange a quadratic to equal 0 before factorising?","lookFor":"Explains that only when the product equals 0 can we say one of the brackets must be 0."},
    {"id":"lesson-england-simultaneous-equations-and-inequalities-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Patterns and missing numbers","codes":[],"title":"Simultaneous equations and inequalities (Years 10 and 11)","intention":"We are learning to form and solve simultaneous equations and inequalities, and to show the solutions.","criteria":["I can solve two simultaneous equations in two variables (linear/linear) algebraically, and find approximate solutions using a graph.","I can translate simple situations into an equation or two simultaneous equations, solve them and interpret the solution.","I can solve linear inequalities in one variable and represent the solution set on a number line.","I can solve linear/quadratic simultaneous equations, linear inequalities in two variables and quadratic inequalities in one variable, using set notation and a graph (higher)."],"steps":{"start":"Two coffees and a cake cost £8. One coffee and a cake cost £5.50. How much is a coffee?","teach":"Write the start problem as 2c + k = 8 and c + k = 5.5, then subtract to remove k: c = 2.5 and k = 3. Solve 3x + 2y = 16 and x − 2y = 0 by adding: 4x = 16, so x = 4 and y = 2. Draw both lines: the solution is where they cross. Solve 3x − 5 < 10 like an equation, x < 5, and show it with an open circle on a number line; turn the sign round when multiplying or dividing by a negative. Higher: substitute y = x + 1 into x² + y² = 13 to find where a line meets a circle; solve x² < 9 as −3 < x < 3, written {x : −3 < x < 3}.","practise":"The \"Two unknowns\" sheet.","check":"Solve 2x + y = 11 and x − y = 1. Solve 4 − 2x ≥ 10 and show it on a number line."},"use":[],"home":"Find a \"two prices\" puzzle on a café menu and set it up as simultaneous equations.","vocab":"simultaneous, eliminate, substitute, inequality, solution set, set notation, region","understand":"What does the point where two straight lines cross tell you about their equations?","lookFor":"Explains that it's the one pair of x and y values that makes both equations true at once."},
    {"id":"lesson-england-sequences-quadratic-geometric-and-the-nth-term-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Patterns and missing numbers","codes":[],"title":"Sequences: quadratic, geometric and the nth term (Years 10 and 11)","intention":"We are learning to recognise different kinds of sequence and to find a rule for the nth term.","criteria":["I can deduce expressions to calculate the nth term of linear sequences, and of quadratic sequences (higher).","I can recognise and use sequences of triangular, square and cube numbers, simple arithmetic progressions, Fibonacci type sequences, quadratic sequences, and simple geometric progressions.","I can use geometric progressions where the common ratio is a surd, and other sequences (higher)."],"steps":{"start":"What comes next, and why: 1, 4, 9, 16…; 2, 6, 18, 54…; 1, 1, 2, 3, 5…?","teach":"Sort sequences by type: arithmetic (add the same each time), geometric (multiply by the same ratio), Fibonacci type (add the two before), square, cube and triangular numbers, and quadratic (the second differences are the same). The nth term of 5, 8, 11, 14 goes up in 3s, so it's 3n + 2. Higher: for 3, 9, 19, 33, 51 the second difference is 4, so it starts 2n²; take 2n² away (2, 8, 18, 32, 50) to leave 1 each time, so the nth term is 2n² + 1.","practise":"The \"Sequence detective\" sheet.","check":"Find the nth term of 7, 11, 15, 19. Is 2, 6, 12, 20, 30 arithmetic, geometric or quadratic? Find its nth term (higher)."},"use":[],"home":"Look for growing patterns in tiles, stacks of cans or bricks, and predict the 10th one.","vocab":"sequence, term, nth term, arithmetic, geometric, common ratio, Fibonacci, quadratic, second difference","understand":"How can you tell whether a sequence is arithmetic, geometric or quadratic?","lookFor":"Arithmetic: the differences are the same. Geometric: you multiply by the same ratio. Quadratic: the second differences are the same."},
    {"id":"lesson-england-graphs-of-functions-and-their-transformations-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Patterns and missing numbers","codes":[],"title":"Graphs of functions and their transformations (Years 10 and 11)","intention":"We are learning to recognise and sketch the shapes of important graphs, and to translate and reflect them.","criteria":["I can recognise, sketch and interpret graphs of linear functions, quadratic functions, simple cubic functions, and the reciprocal function y = 1/x with x ≠ 0.","I can recognise, sketch and interpret graphs of the exponential function y = kˣ for positive values of k, and the trigonometric functions y = sin x, y = cos x and y = tan x for angles of any size (higher).","I can sketch translations and reflections of the graph of a given function (higher)."],"steps":{"start":"Match y = 2x + 1, y = x², y = x³ and y = 1/x to four sketches. What gave each one away?","teach":"Make a graph gallery. For each family, plot a few points and describe the shape: a straight line, a ∪-shaped parabola, an S-shaped cubic, a reciprocal graph in two parts that never touches the axes. Higher: exponential growth that never reaches the x-axis, and sine and cosine waves repeating every 360°. y = f(x) + a moves a graph up a; y = f(x + a) moves it left a; y = −f(x) reflects it in the x-axis; y = f(−x) reflects it in the y-axis. Test each rule on y = x².","practise":"The \"Graph gallery\" sheet.","check":"Sketch y = x² and y = x² − 4 on the same axes. What happens to y = 1/x at x = 0, and why?"},"use":[],"home":"Spot graph shapes in real life: the path of a ball, a cup of tea cooling, the tide going in and out.","vocab":"linear, quadratic, cubic, reciprocal, exponential, asymptote, translation, reflection","understand":"Why does the graph of y = 1/x never touch the x-axis?","lookFor":"Explains that 1 divided by any number can never be 0, though it gets closer to 0 as x gets bigger."},
    {"id":"lesson-england-real-life-graphs-gradients-areas-and-rates-of-change-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Patterns and missing numbers","codes":[],"title":"Real-life graphs: gradients, areas and rates of change (Years 10 and 11)","intention":"We are learning to use graphs of real situations, including distance-time and velocity-time graphs, to find and interpret rates of change.","criteria":["I can plot and interpret graphs, including reciprocal graphs and graphs of non-standard functions in real contexts, to find approximate solutions to problems such as simple kinematic problems involving distance, speed and acceleration.","I can calculate or estimate gradients of graphs and areas under graphs, and interpret them in cases such as distance-time and velocity-time graphs (higher).","I can interpret the gradient at a point on a curve as the instantaneous rate of change, and apply average and instantaneous rates of change (higher).","I can use the kinematics formulae v = u + at, s = ut + ½at² and v² = u² + 2as when they're given."],"steps":{"start":"On a distance-time graph, what does a flat line mean? A steeper line?","teach":"On a distance-time graph, the gradient is the speed. On a velocity-time graph, the gradient is the acceleration and the area under the graph is the distance travelled: split it into triangles and rectangles. Higher: for a curve, draw a tangent and find its gradient for the rate of change at that instant; a chord between two points gives the average rate over that time. Use v = u + at: a car at 10 m/s accelerating at 2 m/s² for 5 seconds reaches 20 m/s.","practise":"The \"Graphs in motion\" sheet.","check":"A cyclist speeds up steadily from rest to 8 m/s in 4 seconds, then rides at 8 m/s for 6 seconds. What is the acceleration, and how far do they go?"},"use":[],"home":"Sketch a distance-time graph of a journey to school, showing the stops.","vocab":"gradient, rate of change, velocity, acceleration, area under a graph, tangent, chord","understand":"On a velocity-time graph, why does the area underneath give the distance travelled?","lookFor":"Explains that distance = speed × time, which is the area of a rectangle on the graph, so the area under any part adds up the distance."},
    {"id":"lesson-england-growth-decay-compound-interest-and-iteration-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Fractions, decimals and percentages","codes":[],"title":"Growth, decay, compound interest and iteration (Years 10 and 11)","intention":"We are learning to set up and solve problems where an amount grows or shrinks by the same percentage each time, and to use iteration.","criteria":["I can set up, solve and interpret the answers in growth and decay problems, including compound interest.","I can use the formula for compound interest: total accrued = P(1 + r/100)ⁿ.","I can work with general iterative processes, and find approximate solutions to equations numerically using iteration (higher)."],"steps":{"start":"£100 earns 10% interest each year, added on at the end of the year. Is it £120 after 2 years?","teach":"Use multipliers: an increase of 4% is × 1.04, and a decrease of 15% is × 0.85. Compound interest on £2000 at 3% for 5 years is 2000 × 1.03⁵ = £2318.55; compare it with simple interest (£300). A £12 000 car that loses 20% of its value a year is worth 12 000 × 0.8³ = £6144 after 3 years. Work backwards by dividing by the multiplier. Higher: iterate xₙ₊₁ = ∛(5 − 2xₙ) from x₀ = 1, putting each answer back in, to home in on a solution of x³ + 2x − 5 = 0.","practise":"The \"Growing and shrinking\" sheet.","check":"A town of 5000 people grows by 2% a year. Write an expression for its population after n years, and work it out for 3 years."},"use":[],"home":"Compare two savings accounts: which pays more over 5 years, and why?","vocab":"multiplier, compound interest, simple interest, depreciation, growth, decay, iteration","understand":"Why isn't a 10% rise followed by a 10% fall back to where you started?","lookFor":"Explains the fall is 10% of a bigger amount, so it takes off more: × 1.1 × 0.9 = × 0.99, a 1% loss."},
    {"id":"lesson-england-proportion-compound-units-and-fractions-in-ratio-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Fractions, decimals and percentages","codes":[],"title":"Proportion, compound units and fractions in ratio (Years 10 and 11)","intention":"We are learning to use direct and inverse proportion, convert compound units, and use fractions in ratio problems.","criteria":["I understand that X is inversely proportional to Y is equivalent to X is proportional to 1/Y, and I can interpret equations that describe direct and inverse proportion (and construct them, higher).","I can convert between related compound units (speed, rates of pay, prices, density, pressure) in numerical and algebraic contexts.","I can identify and work with fractions in ratio problems."],"steps":{"start":"4 painters take 6 days to paint a house. How long would 8 painters take? What are you assuming?","teach":"Direct proportion: y = kx, so doubling x doubles y. Inverse proportion: y = k/x, so doubling x halves y. Higher: if y ∝ x² and y = 50 when x = 5, then k = 2 and y = 2x². Convert 72 km/h to metres per second: 72 000 m ÷ 3600 s = 20 m/s. Density = mass ÷ volume and pressure = force ÷ area. Fractions in ratio: if boys : girls = 3 : 5, then the boys are ⅜ of the class; if ⅖ of the beads are red, then red : not red = 2 : 3.","practise":"The \"Proportion and units\" sheet.","check":"y is inversely proportional to x, and y = 6 when x = 4. Find y when x = 3. Convert 15 m/s to km/h."},"use":[],"home":"Scale a recipe up or down, and talk about what would be in inverse proportion if more people shared the cooking.","vocab":"direct proportion, inverse proportion, constant of proportionality, compound unit, density, pressure, ratio","understand":"If y is inversely proportional to x, what happens to y when x is multiplied by 3? Why?","lookFor":"Explains y is divided by 3, because xy stays the same (the constant k)."},
    {"id":"lesson-england-similarity-and-enlargement-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Shape and angles","codes":[],"title":"Similarity and enlargement (Years 10 and 11)","intention":"We are learning to use scale factors, including fractional and negative ones, and to compare the lengths, areas and volumes of similar shapes.","criteria":["I can compare lengths, areas and volumes using ratio notation and scale factors, and make links to similarity, including trigonometric ratios.","I can apply the concepts of congruence and similarity, including the relationships between lengths in similar figures, and between areas and volumes (higher).","I can interpret and use fractional scale factors for enlargements, and negative scale factors (higher)."],"steps":{"start":"A photo is enlarged so that every length doubles. Does its area double too?","teach":"Check two shapes are similar by comparing corresponding sides. If lengths are multiplied by k, areas are multiplied by k² and volumes by k³: two similar jugs 10 cm and 15 cm tall have k = 1.5, so the larger holds 1.5³ = 3.375 times as much. Enlarge a triangle by a scale factor of ½ from a centre: each point ends up half as far from the centre. Higher: a negative scale factor takes each point through the centre to the other side, turning the shape upside down. Similar right-angled triangles have the same ratios of sides, which is why sin, cos and tan work.","practise":"The \"Similar shapes\" sheet.","check":"Two similar cylinders have radii of 3 cm and 6 cm. The small one has a volume of 40 cm³. What is the volume of the large one?"},"use":[],"home":"Compare a model car or toy with the real thing: what's the scale, and how many times bigger is the real one's surface area?","vocab":"similar, congruent, scale factor, enlargement, centre of enlargement, corresponding, area factor, volume factor","understand":"If the lengths are doubled, why is the volume multiplied by 8 and not 2?","lookFor":"Explains the volume grows in three directions, so it's multiplied by 2 × 2 × 2."},
    {"id":"lesson-england-vectors-and-combined-transformations-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Shape and angles","codes":[],"title":"Vectors and combined transformations (Years 10 and 11)","intention":"We are learning to describe translations with vectors, calculate with vectors, and describe combined transformations.","criteria":["I can describe translations as 2D vectors.","I can apply addition and subtraction of vectors, multiplication of vectors by a scalar, and diagrammatic and column representations of vectors.","I can use vectors to construct geometric arguments and proofs (higher).","I can describe the changes and invariance achieved by combinations of rotations, reflections and translations (higher)."],"steps":{"start":"Move a counter 3 squares right and 2 down. How could you write that move?","teach":"Write a translation as a column vector, with the move across on top and the move up or down below. Add vectors nose to tail, or by adding the tops and the bottoms; 2a is twice as long as a in the same direction, and −a points the opposite way. In parallelogram OABC with OA = a and OC = c, OB = a + c and AC = c − a. Higher: if M is the midpoint of AB, then OM = a + ½(b − a) = ½(a + b); two vectors are parallel when one is a multiple of the other. Reflecting in the x-axis and then the y-axis is the same as a rotation of 180° about the origin: which point doesn't move (is invariant)?","practise":"The \"Vectors\" sheet.","check":"With a = (2, 5) and b = (−3, 1) as column vectors, find a + b and 2a − b."},"use":[],"home":"Give directions round the house as vectors (steps forward and across), then add them up to find the shortcut.","vocab":"vector, column vector, scalar, resultant, parallel, midpoint, translation, invariant","understand":"How can you tell from two vectors that two lines are parallel?","lookFor":"Explains that one vector is a multiple of the other, so they point in the same (or opposite) direction."},
    {"id":"lesson-england-circles-parts-arc-lengths-and-sectors-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Shape and angles","codes":[],"title":"Circles: parts, arc lengths and sectors (Years 10 and 11)","intention":"We are learning the parts of a circle and how to calculate arc lengths, angles and areas of sectors.","criteria":["I can identify and apply circle definitions and properties, including: centre, radius, chord, diameter, circumference, tangent, arc, sector and segment.","I know the formulae: circumference of a circle = 2πr = πd, and area of a circle = πr².","I can calculate arc lengths, angles and areas of sectors of circles."],"steps":{"start":"What fraction of a circle is a sector with an angle of 90°? Of 120°?","teach":"Label a circle: centre, radius, diameter, chord, tangent, arc, sector and segment, and say how a segment differs from a sector. Arc length = θ/360 × 2πr and sector area = θ/360 × πr². For r = 6 cm and θ = 60°, the arc is 2π cm (about 6.28 cm) and the area is 6π cm² (about 18.85 cm²). Work backwards: a sector of radius 10 cm with an area of 25π cm² is 25π ÷ 100π = ¼ of the circle, so its angle is 90°.","practise":"The \"Arcs and sectors\" sheet.","check":"Find the perimeter of a sector with radius 9 cm and angle 40°, exactly and to 1 decimal place."},"use":[],"home":"Look at a slice of pizza or cake: estimate its angle and work out the length of its crust.","vocab":"radius, diameter, chord, tangent, arc, sector, segment, circumference, π","understand":"Why do we multiply by θ/360 to find an arc length?","lookFor":"Explains the sector is that fraction of the whole circle, so its arc is that fraction of the circumference."},
    {"id":"lesson-england-circle-theorems-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Shape and angles","codes":[],"title":"Circle theorems (Years 10 and 11)","intention":"We are learning the standard circle theorems, and using them to find angles and to prove results.","criteria":["I can apply the standard circle theorems concerning angles, radii, tangents and chords (higher).","I can prove the standard circle theorems, and use them to prove related results (higher)."],"steps":{"start":"Draw a triangle with its corners on a circle and one side along a diameter. Measure the angle opposite the diameter. What do you notice?","teach":"Teach each theorem with a sketch and an example: the angle in a semicircle is 90°; the angle at the centre is twice the angle at the circumference; angles in the same segment are equal; opposite angles of a cyclic quadrilateral add up to 180°; a tangent is perpendicular to the radius; the two tangents from a point are equal; the perpendicular from the centre to a chord bisects the chord; the angle between a tangent and a chord equals the angle in the alternate segment. Prove the angle at the centre theorem using the isosceles triangles made by radii. Always give the reason in words.","practise":"The \"Circle theorems\" sheet.","check":"In a cyclic quadrilateral, one angle is 68°. What is the opposite angle, and what is the reason?"},"use":[],"home":"Teach one theorem to someone at home with a drawing, and explain why it's true.","vocab":"theorem, cyclic quadrilateral, circumference, semicircle, tangent, chord, bisect, alternate segment, proof","understand":"Why is the angle in a semicircle always 90°?","lookFor":"Links it to the angle at the centre: the diameter makes a straight angle of 180° at the centre, and the angle at the circumference is half of that."},
    {"id":"lesson-england-3d-shapes-plans-elevations-surface-area-and-volume-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Measurement","codes":[],"title":"3D shapes: plans, elevations, surface area and volume (Years 10 and 11)","intention":"We are learning to draw and read plans and elevations, and to calculate surface areas and volumes of spheres, pyramids, cones and composite solids.","criteria":["I can construct and interpret plans and elevations of 3D shapes.","I can calculate surface areas and volumes of spheres, pyramids, cones and composite solids.","I can use the formulae for a sphere and a cone when they're given, and I know that the volume of a prism = area of cross section × length."],"steps":{"start":"Look at a cereal box from the front, the side and above. Sketch each view.","teach":"Draw the plan (from above), the front elevation and the side elevation of a shape made from cubes. Volume of a prism = area of cross section × length; a pyramid or cone holds a third of the prism or cylinder that fits around it. Use the given formulae: for a sphere, volume = 4/3πr³ and surface area = 4πr²; for a cone, volume = 1/3πr²h and curved surface area = πrl. Work out a composite solid, such as a cone on a hemisphere, part by part, counting only the outside surfaces.","practise":"The \"Solid shapes\" sheet.","check":"Find the volume of a cone with radius 3 cm and height 4 cm, and its curved surface area (its slant height is 5 cm), in terms of π."},"use":[],"home":"Find a cone, a sphere and a pyramid at home (an ice-cream cone, a ball, a tent) and estimate their volumes.","vocab":"plan, elevation, prism, pyramid, cone, sphere, hemisphere, slant height, surface area, volume, composite","understand":"Why is the volume of a cone a third of the cylinder that fits around it?","lookFor":"Explains or shows (by filling with sand or water, or comparing a pyramid with a prism) that three cones fill the cylinder."},
    {"id":"lesson-england-pythagoras-trigonometry-and-bearings-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Shape and angles","codes":[],"title":"Pythagoras, trigonometry and bearings (Years 10 and 11)","intention":"We are learning to find lengths and angles in right-angled triangles with Pythagoras' Theorem and trigonometry, including with bearings.","criteria":["I can apply Pythagoras' Theorem and trigonometric ratios to find angles and lengths in right-angled triangles in two dimensional figures, and in three dimensional figures (higher).","I know the formulae a² + b² = c², sin θ = opposite/hypotenuse, cos θ = adjacent/hypotenuse and tan θ = opposite/adjacent.","I know the exact values of sin θ and cos θ for θ = 0°, 30°, 45°, 60° and 90°, and of tan θ for θ = 0°, 30°, 45° and 60°.","I can interpret and use bearings."],"steps":{"start":"A 5 m ladder leans against a wall with its foot 3 m from the wall. How high up the wall does it reach?","teach":"Label the hypotenuse, and the opposite and adjacent sides from the angle, then choose sin, cos or tan. Find a side: x = 10 sin 35° ≈ 5.74; find an angle: tan θ = 7/4, so θ ≈ 60.3°. Get the exact values from two triangles: half an equilateral triangle with sides 2 (sin 30° = ½, cos 30° = √3/2, tan 60° = √3) and a right-angled isosceles triangle with sides 1, 1 and √2 (sin 45° = cos 45° = 1/√2). Bearings are measured clockwise from north, with three figures: a ship sails 8 km east (090°) then 6 km south (180°); it's 10 km from the start, and the bearing back to the start is 307°.","practise":"The \"Right-angled triangles\" sheet.","check":"Without a calculator, find the side opposite a 30° angle when the hypotenuse is 12 cm. The bearing of B from A is 065°: what is the bearing of A from B?"},"use":[],"home":"Use a compass app to find the bearing of a landmark from home, and estimate how far away it is.","vocab":"hypotenuse, opposite, adjacent, sine, cosine, tangent, Pythagoras' Theorem, exact value, bearing","understand":"How do you decide whether to use Pythagoras' Theorem or trigonometry?","lookFor":"Pythagoras when it's only sides (two known, find the third); trigonometry when an angle is known or wanted."},
    {"id":"lesson-england-the-sine-rule-cosine-rule-and-area-of-any-triangle-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Shape and angles","codes":[],"title":"The sine rule, cosine rule and area of any triangle (Years 10 and 11)","intention":"We are learning to find sides, angles and areas in triangles that don't have a right angle.","criteria":["I know and can apply the sine rule, a/sin A = b/sin B = c/sin C, to find unknown lengths and angles (higher).","I know and can apply the cosine rule, a² = b² + c² − 2bc cos A, to find unknown lengths and angles (higher).","I know and can apply Area = ½ab sin C to calculate the area, sides or angles of any triangle (higher)."],"steps":{"start":"Can you use sin, cos and tan as usual in a triangle with no right angle? Why not?","teach":"Label each side with the small letter of the angle opposite it. Use the sine rule when you know a side and the angle opposite it: with a = 8, A = 40° and B = 65°, b = 8 sin 65° ÷ sin 40° ≈ 11.3. Use the cosine rule with two sides and the angle between them (for the third side), or with all three sides (for an angle): with b = 5, c = 7 and A = 60°, a² = 25 + 49 − 70 cos 60° = 39, so a ≈ 6.24. The area of that triangle is ½ × 5 × 7 × sin 60° ≈ 15.2.","practise":"The \"Any triangle\" sheet.","check":"A triangle has sides of 6 cm and 9 cm with an angle of 50° between them. Find the third side and the area."},"use":[],"home":"Measure two sides of a triangular object (a sandwich, a road sign) and the angle between them, and work out its area.","vocab":"sine rule, cosine rule, included angle, opposite, area of a triangle","understand":"How do you choose between the sine rule and the cosine rule?","lookFor":"Sine rule when you know a side and the angle opposite it; cosine rule when you know two sides and the angle between them, or all three sides."},
    {"id":"lesson-england-probability-exhaustive-events-models-and-predictions-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Data and chance","codes":[],"title":"Probability: exhaustive events, models and predictions (Years 10 and 11)","intention":"We are learning to use the fact that probabilities add up to 1, and to use probability models and experiments to predict outcomes.","criteria":["I can apply the property that the probabilities of an exhaustive set of mutually exclusive events sum to one.","I can use a probability model to predict the outcomes of future experiments.","I understand that empirical unbiased samples tend towards theoretical probability distributions, with increasing sample size."],"steps":{"start":"A spinner lands on red with probability 0.3 and blue with probability 0.45. It can also land on green. What is the probability of green?","teach":"Mutually exclusive events can't happen at the same time, and an exhaustive set covers every possible outcome, so their probabilities add up to 1. Solve a table with a missing probability (x and 2x). Predict: if P(six) = ⅙, expect about 50 sixes in 300 rolls. Roll a dice 10, 50 and 100 times (or pool results): the relative frequency settles closer to the theoretical probability as the number of trials grows, so a bigger sample gives a better estimate.","practise":"The \"Predict and test\" sheet.","check":"The probabilities of a bus being early, on time or late are 0.1, x and 0.35. Find x, and how many of 200 buses you'd expect to be late."},"use":[],"home":"Flip a coin 20 times, then 100 times. Which relative frequency of heads is closer to 0.5?","vocab":"mutually exclusive, exhaustive, probability model, relative frequency, expected frequency, theoretical probability, sample size","understand":"Why is a relative frequency from 500 trials a better estimate than one from 20?","lookFor":"Explains that with more trials, chance variations even out, so the relative frequency settles near the true probability."},
    {"id":"lesson-england-combined-events-listing-tree-diagrams-and-conditional-probability-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Data and chance","codes":[],"title":"Combined events: listing, tree diagrams and conditional probability (Years 10 and 11)","intention":"We are learning to list outcomes systematically and to find the probabilities of combined events.","criteria":["I can calculate the probability of independent and dependent combined events, including using tree diagrams and other representations, and know the underlying assumptions.","I can apply systematic listing strategies, including use of the product rule for counting (higher).","I can calculate and interpret conditional probabilities through representation using expected frequencies with two-way tables, tree diagrams and Venn diagrams (higher).","I know that P(A or B) = P(A) + P(B) − P(A and B), and P(A and B) = P(A given B)P(B)."],"steps":{"start":"How many different outfits can you make from 3 tops and 4 pairs of trousers?","teach":"List outcomes systematically (keep one choice fixed while the other changes) and use the product rule: 3 × 4 = 12. Draw a tree diagram for taking two counters from a bag of 4 red and 6 blue: with replacement, the second branches stay 4/10 and 6/10 (independent); without replacement, they change to 3/9 and 6/9, or 4/9 and 5/9 (dependent). Multiply along the branches and add between them. Higher: use a two-way table or Venn diagram of expected frequencies for conditional probability: of 100 pupils, 40 play football and 25 of those also swim, so P(swims given plays football) = 25/40.","practise":"The \"Combined events\" sheet.","check":"Two counters are taken without replacement from a bag with 3 red and 2 green. Find P(both red) and P(one of each colour)."},"use":[],"home":"Work out how many PINs a 4-digit lock can have, and explain why the product rule works.","vocab":"independent, dependent, tree diagram, with replacement, without replacement, product rule, conditional probability, Venn diagram, two-way table","understand":"Why do the probabilities on the second branches change when you don't replace the first counter?","lookFor":"Explains there's one fewer counter in the bag, and one fewer of the colour taken, so the second pick depends on the first."},
    {"id":"lesson-england-samples-time-series-and-scatter-graphs-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Data and chance","codes":[],"title":"Samples, time series and scatter graphs (Years 10 and 11)","intention":"We are learning to draw conclusions about a population from a sample, read time series, and use scatter graphs carefully.","criteria":["I can infer properties of populations or distributions from a sample, whilst knowing the limitations of sampling.","I can interpret and construct tables and line graphs for time series data.","I can apply statistics to describe a population.","I can use and interpret scatter graphs, recognise correlation and know that it does not indicate causation, draw estimated lines of best fit, make predictions, and interpolate and extrapolate trends whilst knowing the dangers of so doing."],"steps":{"start":"Ice-cream sales and cases of sunburn both go up in summer. Does ice cream cause sunburn?","teach":"Talk about samples: random, big enough, and free from bias (asking people at a gym about exercise isn't fair). Estimate for a population from a sample: if 12 of 60 sampled pupils walk to school, about ⅕ of 900 pupils, 180, do. Plot a time series, such as sales each quarter for two years, and describe the trend and the pattern that repeats. Plot a scatter graph, describe the correlation, draw a line of best fit by eye and use it to predict. Predicting inside the data (interpolating) is safer than beyond it (extrapolating).","practise":"The \"Data and samples\" sheet.","check":"Why might a line of best fit for the ages and heights of children aged 5 to 12 give a silly prediction for a 40-year-old?"},"use":[],"home":"Find a news story that says one thing causes another. Is there evidence of cause, or only a correlation?","vocab":"population, sample, bias, random, time series, trend, correlation, causation, line of best fit, interpolate, extrapolate","understand":"Two things are strongly correlated. Does one cause the other? How could you tell?","lookFor":"Explains that correlation doesn't prove cause: a third factor (such as hot weather) may cause both, and only an experiment or a clear mechanism would show cause."},
    {"id":"lesson-england-histograms-cumulative-frequency-and-box-plots-years-10-and-11","england":true,"level":"Fourth","subject":"Maths","strand":"Data and chance","codes":[],"title":"Histograms, cumulative frequency and box plots (Years 10 and 11)","intention":"We are learning to compare distributions using averages, spread, and diagrams such as histograms, cumulative frequency graphs and box plots.","criteria":["I can interpret, analyse and compare the distributions of data sets through appropriate graphical representation involving discrete, continuous and grouped data, including box plots (higher).","I can use appropriate measures of central tendency, including the modal class, and of spread, including quartiles and inter-quartile range (higher).","I can construct and interpret histograms with equal and unequal class intervals and cumulative frequency graphs, and know their appropriate use (higher)."],"steps":{"start":"Two classes both have a mean test score of 60%. Did they do equally well?","teach":"Group continuous data in a table, find the modal class, and estimate the mean using midpoints. Higher: draw a cumulative frequency graph (plotting at the upper end of each class), then read off the median, the quartiles and the interquartile range. Draw box plots and compare two of them: compare an average and a spread, in context. For unequal class widths, plot frequency density = frequency ÷ class width, so the area of each bar shows its frequency.","practise":"The \"Distributions\" sheet.","check":"A histogram bar for 20 < t ≤ 30 has a frequency density of 1.8. How many values are in that class?"},"use":[],"home":"Time how long it takes people at home to do a puzzle, and compare the times with a box plot.","vocab":"frequency, class width, frequency density, histogram, cumulative frequency, median, quartile, interquartile range, box plot, modal class","understand":"Why do we compare an average and a spread, not just the averages?","lookFor":"Explains that two sets can have the same average but be very different: the spread (range or interquartile range) shows how consistent the data is."},
    {"id":"lesson-england-shakespeare-language-character-and-context-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Reading: understanding stories","codes":[],"title":"Shakespeare: language, character and context (Years 10 and 11)","intention":"We are learning to read Shakespeare with understanding, exploring how characters and events are shaped and how the play's context informs our reading.","criteria":["I can read and appreciate the depth and power of the English literary heritage, including a play by Shakespeare.","I can explore aspects of plot, characterisation, events and settings, the relationships between them and their effects.","I can draw on knowledge of the purpose, audience for and context of the writing, including its social, historical and cultural context and the literary tradition to which it belongs, to inform evaluation."],"steps":{"start":"Shakespeare's audiences often stood for hours. What would a play need to do to hold their attention?","teach":"Read a short scene from the play being studied aloud, sharing the parts. Put a few lines into modern English, then talk about what's lost: rhythm, imagery, double meanings. Follow one character through the scene: what they say, what they do, and how others react. Add one piece of context (beliefs about kings, fate or the place of women at the time, or the conventions of tragedy or comedy) and ask how it changes what the scene meant to an audience then, and means now.","practise":"The \"Shakespeare scene study\" sheet, on a scene from the play being studied.","check":"Ask for a quotation that shows the character's state of mind, what one word in it suggests, and how an audience at the time might have reacted."},"use":[],"home":"Watch a filmed performance of the same scene. What did the actors and director do to make it clear?","vocab":"soliloquy, aside, dramatic irony, iambic pentameter, imagery, context, characterisation, tragedy, comedy","understand":"How might an audience in Shakespeare's time have seen this moment differently from us?","lookFor":"Links a specific belief or convention of the time to a specific moment, and explains how it changes the meaning or effect."},
    {"id":"lesson-england-poetry-analysing-and-comparing-poems-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Reading: understanding stories","codes":[],"title":"Poetry: analysing and comparing poems (Years 10 and 11)","intention":"We are learning to analyse how poets use language, form and structure, and to compare two poems critically.","criteria":["I can analyse a writer's choice of vocabulary, form, grammatical and structural features, and evaluate their effectiveness and impact.","I can make critical comparisons, referring to the contexts, themes, characterisation, style and literary quality of texts.","I can re-read literature as a basis for making comparisons.","I can explain how vocabulary, grammar, form and structure contribute to effectiveness and impact, using linguistic and literary terminology accurately."],"steps":{"start":"Read the two poems on the sheet once each. Which one stays with you, and why?","teach":"Re-read each poem with a question in mind: what is it about, and what is it really about? Pick out a word or image and explore what it suggests, then look at form and structure: rhyme, rhythm, stanza shape, line breaks and how the poem moves (a turn, a contrast, a change of time). Model a comparison paragraph that links the poems with a point, a quotation from each, analysis of the methods and a judgement about their effect.","practise":"The \"Two poems\" sheet.","check":"Ask for one way the poems are alike and one way they differ, with a quotation from each and a comment on a method."},"use":[],"home":"Choose a poem you like (a song lyric counts) and explain one technique and its effect to someone at home.","vocab":"imagery, metaphor, simile, personification, rhyme, rhythm, stanza, enjambment, caesura, tone, volta","understand":"Why did the poet end the line there, and not a word later?","lookFor":"Explains the effect of the line break or structure on meaning or emphasis, using a term such as enjambment or caesura."},
    {"id":"lesson-england-summary-and-synthesis-across-two-non-fiction-texts-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Reading: understanding stories","codes":[],"title":"Summary and synthesis across two non-fiction texts (Years 10 and 11)","intention":"We are learning to read for a purpose, summarise and synthesise information from two texts, and judge how useful they are.","criteria":["I can read in different ways for different purposes, summarising and synthesising ideas and information, and evaluating their usefulness for particular purposes.","I can identify the main theme or themes, summarise ideas and information from a single text, and synthesise from more than one text.","I can understand and critically evaluate texts."],"steps":{"start":"Skim both texts on the sheet in one minute. What are they both about?","teach":"Show three ways of reading: skimming for the gist, scanning for a detail, and close reading for meaning. Sort true and false statements about one text, finding the evidence each time. Then synthesise: pick out what the two writers say about the same thing, and write about the differences in your own words, with a short quotation or detail from each and an inference about what the difference shows. Finish by judging how useful each text would be for a given purpose.","practise":"The \"Two journeys\" sheet.","check":"Ask for one difference between the writers' experiences, with evidence from both, and which text is more useful for finding out what rail travel felt like then."},"use":[],"home":"Read two reviews of the same film, game or product and summarise how they differ.","vocab":"skim, scan, summary, synthesis, inference, source, usefulness, reliability","understand":"What's the difference between summarising and synthesising?","lookFor":"Explains that a summary gives the key points of one text, while synthesis brings points from two texts together, comparing them in their own words."},
    {"id":"lesson-england-evidence-inference-and-bias-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Reading: understanding stories","codes":[],"title":"Evidence, inference and bias (Years 10 and 11)","intention":"We are learning to tell supported claims from unsupported ones, spot bias and the misuse of evidence, and back up our own inferences.","criteria":["I can distinguish between statements that are supported by evidence and those that are not, and identify bias and misuse of evidence.","I can seek evidence in the text to support a point of view, including justifying inferences with evidence.","I can identify and interpret themes, ideas and information, and recognise the possibility of different responses to a text."],"steps":{"start":"\"Everyone knows that…\" Why might a writer start a sentence like that?","teach":"Read the opinion piece on the sheet. Highlight claims in two colours: supported by evidence, or not. Look at how evidence is used: is the sample big and fair, does it prove what the writer says it proves? Find bias: one-sided language, attacks on people rather than their arguments, missing views. Make an inference about the writer and justify it with a quotation. Then argue the opposite reading: why might another reader find the piece convincing?","practise":"The \"Weighing the evidence\" sheet.","check":"Ask for one claim with no evidence, one way evidence is misused, and an inference about the writer backed by a quotation."},"use":[],"home":"Find an advert or opinion piece and check one of its claims: what evidence is there?","vocab":"claim, evidence, inference, bias, sample, generalisation, fact, opinion, counter-argument","understand":"The writer gives a statistic. Does that make the argument reliable?","lookFor":"Questions where the figure comes from, the sample size and who was asked, and whether it really shows what the writer claims."},
    {"id":"lesson-england-whole-novels-themes-characters-and-a-personal-response-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Reading: understanding stories","codes":[],"title":"Whole novels: themes, characters and a personal response (Years 10 and 11)","intention":"We are learning to trace themes and characters through a whole novel, and to make an informed personal response while weighing up other readings.","criteria":["I can identify and interpret themes, ideas and information.","I can make an informed personal response, recognising that other responses to a text are possible and evaluating these.","I can choose and read books independently for challenge, interest and enjoyment.","I can explore aspects of plot, characterisation, events and settings, the relationships between them and their effects."],"steps":{"start":"In one sentence, what is the novel you're reading really about? Is that its plot or its theme?","teach":"Separate plot (what happens) from theme (the big ideas). Track one theme through the novel: three key moments from the beginning, middle and end, with a quotation and what it suggests. Track how one character changes and why, and link the change to a setting or event. Then form a personal response (what you think the writer is saying) and test it against another reading: what would someone who disagrees say, and how strong is their case?","practise":"The \"Theme tracker\" sheet, on the novel being read.","check":"Ask how a theme develops across the novel, with two moments as evidence, and for a different interpretation and their view of it."},"use":[],"home":"Keep a reading log of a book chosen for interest, and recommend it (or not) to someone at home.","vocab":"theme, motif, plot, characterisation, setting, interpretation, personal response, development","understand":"What would someone who disagrees with your reading say, and are they right?","lookFor":"States a different interpretation fairly, with evidence, and weighs it against their own rather than dismissing it."},
    {"id":"lesson-england-descriptive-and-narrative-writing-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Writing: creating texts","codes":[],"title":"Descriptive and narrative writing (Years 10 and 11)","intention":"We are learning to write imaginative descriptions and stories at length, shaping them for effect.","criteria":["I can write accurately, fluently, effectively and at length for pleasure and information.","I can adapt my writing for a wide range of purposes and audiences, including to describe and to narrate.","I can use language imaginatively and creatively, maintain a consistent point of view, and keep coherence and consistency across a text.","I can create emotional impact."],"steps":{"start":"Describe this room in one sentence that makes it sound threatening, then in one that makes it sound safe.","teach":"Plan before writing: purpose, audience and viewpoint. For a description, zoom in and out, move through time, and use all the senses, with one strong image rather than a list of adjectives. For a story, keep to one or two characters and a short time span, and build to a turning point; start late and end with an echo of the opening. Vary sentence lengths for effect and keep the tense and viewpoint consistent. Write the opening and read it aloud.","practise":"The \"Describe and narrate\" sheet.","check":"Ask them to point to one choice in their opening (a word, a sentence length, a structure) and say what effect they wanted."},"use":[],"home":"Write a short description of the same place at two different times of day.","vocab":"narrative, descriptive, viewpoint, structure, imagery, senses, tension, cyclical structure, coherence","understand":"What did you want the reader to feel at the end of your opening, and how did you do it?","lookFor":"Names an intended effect and points to specific choices (a word, an image, a sentence length, the structure) that create it."},
    {"id":"lesson-england-writing-to-argue-and-persuade-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Writing: creating texts","codes":[],"title":"Writing to argue and persuade (Years 10 and 11)","intention":"We are learning to plan and write a convincing argument, choosing evidence and rhetorical devices to suit the audience.","criteria":["I can select, and use judiciously, vocabulary, grammar, form, and structural and organisational features, including rhetorical devices, to reflect audience, purpose and context, using Standard English where appropriate.","I can select and organise ideas, facts and key points, and cite evidence, details and quotation effectively and pertinently for support and emphasis.","I can use language creatively and persuasively, including rhetorical devices such as rhetorical questions, antithesis and parenthesis."],"steps":{"start":"\"Young people should be allowed to vote at 16.\" Agree or disagree in one sentence, then give your best reason.","teach":"Name rhetorical devices from examples on the sheet: rhetorical question, antithesis, parenthesis, list of three, direct address, statistics and anecdote. Plan an argument: a clear view, three points in a deliberate order, each with evidence, a counter-argument dealt with fairly, and a strong ending. Choose the form (letter, article, speech) and register for the audience. Use devices on purpose, not as a checklist: one well-placed rhetorical question beats five.","practise":"The \"Make the argument\" sheet.","check":"Ask them to read their opening and name the devices they used and why they suit the audience."},"use":[],"home":"Write a short letter to a local paper about something that matters in your area.","vocab":"argument, counter-argument, rebuttal, rhetorical question, antithesis, parenthesis, anecdote, register, Standard English","understand":"Why include a counter-argument when you want people to agree with you?","lookFor":"Explains that answering the other side fairly makes the writer seem reasonable and the argument stronger, and deals with doubts before readers raise them."},
    {"id":"lesson-england-writing-from-notes-and-information-provided-by-others-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Writing: creating texts","codes":[],"title":"Writing from notes and information provided by others (Years 10 and 11)","intention":"We are learning to make notes, draft and write a formal letter from key points someone else has given us.","criteria":["I can make notes, draft and write, including using information provided by others, such as writing a letter from key points provided.","I can adapt my writing to explain, instruct, and give and respond to information.","I can use information provided by others to write in different forms, maintaining coherence and consistency across a text."],"steps":{"start":"You have ten facts and room for five. How do you choose?","teach":"Read the key points on the sheet and decide the purpose and audience of the letter. Select the points that serve the purpose, put them in a logical order, and group them into paragraphs. Model turning a note into a sentence (\"85 of 120 would come\" becomes \"Over two thirds of our members have said they would come\"). Use the conventions of a formal letter, Standard English, and a clear request at the end.","practise":"The \"From key points to a letter\" sheet.","check":"Ask why they left out a point, and how their final paragraph makes the request clear."},"use":[],"home":"Take notes from a news report or podcast and use them to write a short summary for someone who missed it.","vocab":"notes, draft, key points, formal letter, purpose, audience, paragraph, Standard English","understand":"Why didn't you use every key point you were given?","lookFor":"Explains that they chose the points that best served the purpose and audience, and left out ones that were weaker or off the point."},
    {"id":"lesson-england-revising-editing-and-proof-reading-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":[],"title":"Revising, editing and proof-reading (Years 10 and 11)","intention":"We are learning to revise our writing for impact, restructure and improve it, and proof-read it for accuracy.","criteria":["I can revise, edit and proof-read my writing.","I can reflect on whether my draft achieves the intended impact.","I can restructure my writing, and amend its grammar and vocabulary to improve coherence, consistency, clarity and overall effectiveness.","I can pay attention to the accuracy and effectiveness of grammar, punctuation and spelling."],"steps":{"start":"What is the difference between revising, editing and proof-reading?","teach":"Work through the draft on the sheet in three passes. Revise: does it achieve its purpose for its audience, and is anything in the wrong place? Edit: improve the order, the links between sentences and the vocabulary, and keep the tense and voice consistent. Proof-read: read slowly, aloud or backwards sentence by sentence, for spelling, punctuation and grammar errors. Then use the same three passes on a piece of the pupil's own writing.","practise":"The \"Edit for impact\" sheet.","check":"Ask them to explain three changes: one for impact, one for clarity and one for accuracy."},"use":[],"home":"Proof-read a message or post before sending it, reading it aloud first.","vocab":"revise, edit, proof-read, coherence, consistency, clarity, tense, homophone","understand":"Why do we check whether a piece achieves its purpose before we correct the spelling?","lookFor":"Explains that big changes (order, content) may remove or rewrite sentences, so it's better to fix those first and proof-read last."},
    {"id":"lesson-england-grammar-and-vocabulary-for-effect-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Writing: sentences and punctuation","codes":[],"title":"Grammar and vocabulary for effect (Years 10 and 11)","intention":"We are learning to analyse how grammar and vocabulary create effects, and to use them on purpose in our own writing.","criteria":["I can consolidate and build on my knowledge of grammar and vocabulary.","I can study the effectiveness and impact of grammar and vocabulary in the texts I read.","I can draw on new vocabulary and grammatical constructions from my reading and listening, and use these consciously in my writing and speech to achieve particular effects.","I can use linguistic and literary terminology accurately and confidently in discussing reading, writing and spoken language."],"steps":{"start":"\"He waited. Nothing. Then the handle turned.\" Why are the sentences so short?","teach":"Look at grammatical choices in short extracts: short and minor sentences for tension, the passive voice to hide who did something, a fronted subordinate clause to delay the main point, an expanded noun phrase to build an image, modal verbs for certainty or possibility, fronted adverbials to control pace. Name each with the right term, then explain its effect in context. Rewrite a plain sentence three ways for three effects, and borrow one construction from a book being read.","practise":"The \"Grammar for effect\" sheet.","check":"Ask them to name a feature in a sentence from their reading, using the right term, and explain its effect."},"use":[],"home":"Collect three sentences from your reading that you admire, and say what grammar makes them work.","vocab":"clause, subordinate clause, minor sentence, passive voice, modal verb, noun phrase, adverbial, terminology","understand":"Why might a report say \"Mistakes were made\" instead of \"The manager made mistakes\"?","lookFor":"Explains the passive voice can leave out who did it, to hide or avoid blame, or because it's unknown or unimportant."},
    {"id":"lesson-england-spoken-and-written-language-registers-and-standard-english-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Listening and talking","codes":[],"title":"Spoken and written language, registers and Standard English (Years 10 and 11)","intention":"We are learning how spoken and written language differ, how register changes with context, and when Standard English is needed.","criteria":["I can analyse some of the differences between spoken and written language, including differences associated with formal and informal registers, and between Standard English and other varieties of English.","I can use Standard English when the context and audience require it.","I can express ideas using Standard English whenever and wherever appropriate."],"steps":{"start":"How would you tell a friend you'll be late? How would you tell an employer?","teach":"Read the transcript on the sheet aloud. Name features of spontaneous speech: fillers, false starts, repetition, pauses, the present tense used for past events, and quoting with \"I was like\". Separate these from features of a regional or social variety (\"me and my mate was\", \"ain't\"), which follow their own regular rules. Talk about register: formal and informal, and who decides. Rewrite the account in written Standard English and discuss what changes and what's lost.","practise":"The \"Spoken, written and Standard English\" sheet.","check":"Ask for two differences between the spoken and written versions, and a context where Standard English is needed and one where it isn't."},"use":[],"home":"Listen to how people speak in two different places (at home and on the radio, say) and note the differences.","vocab":"register, formal, informal, Standard English, dialect, variety, transcript, filler, false start","understand":"Is a dialect form such as \"we was\" wrong?","lookFor":"Explains it's correct in its own variety but not Standard English, and that the context and audience decide which to use."},
    {"id":"lesson-england-formal-presentations-and-debates-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Listening and talking","codes":[],"title":"Formal presentations and debates (Years 10 and 11)","intention":"We are learning to plan and give a formal presentation or debate speech, and to respond to questions and feedback.","criteria":["I can speak confidently, audibly and effectively.","I can plan for different purposes and audiences, selecting and organising information and ideas effectively and persuasively for formal spoken presentations and debates.","I can make presentations and speeches.","I can listen and respond appropriately to questions and feedback."],"steps":{"start":"Think of a speaker you've enjoyed listening to. What did they do that worked?","teach":"Choose a topic, purpose and audience. Plan on the sheet: a hook, three points with evidence, a counter-argument for a debate, and an ending with a call to action. Rehearse with cue cards rather than a script, working on volume, pace, pauses, eye contact and Standard English. Predict three questions and prepare short answers. Give the talk, take questions, then note the feedback and how to act on it.","practise":"The \"Speech planner\" sheet.","check":"After the talk, ask a question they didn't expect, and see how they answer it."},"use":[],"home":"Give a two-minute talk to someone at home on a subject you know well, then ask them for one question.","vocab":"presentation, debate, audience, purpose, hook, cue card, pace, emphasis, rebuttal, Standard English","understand":"How did you change your talk for your audience?","lookFor":"Gives specific choices (vocabulary, examples, register, length, visual aids) and why they suit that audience."},
    {"id":"lesson-england-group-discussion-leading-listening-and-challenging-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Listening and talking","codes":[],"title":"Group discussion: leading, listening and challenging (Years 10 and 11)","intention":"We are learning to work effectively in a group: leading and managing discussion, building on what others say, and challenging courteously.","criteria":["I can work effectively in groups of different sizes and take on required roles, including leading and managing discussions, involving others productively, reviewing and summarising, and contributing to meeting goals and deadlines.","I can listen to and build on the contributions of others, ask questions to clarify and inform, and challenge courteously when necessary.","I can listen and respond in a variety of different contexts, both formal and informal, and evaluate content, viewpoints, evidence and aspects of presentation."],"steps":{"start":"What makes a group discussion go badly? What makes one go well?","teach":"Read the short discussion on the sheet aloud, taking parts. Find where the chair keeps the group on task, involves a quiet member, and summarises; where someone builds on an idea, asks a question to clarify, or challenges courteously; and where someone doesn't. Then hold a real discussion (the tutor and pupil, or with family), with the pupil in the chair, using the roles and phrases on the sheet, and a time limit and a goal.","practise":"The \"Leading a discussion\" sheet.","check":"Ask them to summarise where the discussion reached, and to name one point they challenged and how."},"use":[],"home":"Chair a short family decision (what to eat, where to go) so that everyone is heard and you reach an answer in five minutes.","vocab":"chair, summarise, build on, clarify, challenge, courteous, consensus, goal, deadline","understand":"How can you disagree with someone without shutting the discussion down?","lookFor":"Acknowledges the other person's point, then gives a reason or evidence for their view, and keeps it about the idea, not the person."},
    {"id":"lesson-england-performing-scripts-and-poetry-years-10-and-11","england":true,"level":"Fourth","subject":"Literacy","strand":"Listening and talking","codes":[],"title":"Performing scripts and poetry (Years 10 and 11)","intention":"We are learning to improvise, rehearse and perform scripts and poems, and to talk about how performance choices change meaning.","criteria":["I can improvise, rehearse and perform play scripts and poetry in order to generate language and discuss language use and meaning.","I can use role, intonation, tone, volume, mood, silence, stillness and action to add impact."],"steps":{"start":"Say \"You could have said\" three ways: hurt, angry, joking. What changes?","teach":"Read the script on the sheet together, then improvise what happened just before it to find out who the characters are. Mark up the script: words to stress, pauses, silences, volume, tone and movement. Perform it twice with different choices (is Jo angry or heartbroken?) and talk about how the meaning changes. Do the same with a poem being studied, deciding where the silences and the stillness should go.","practise":"The \"Perform it\" sheet.","check":"Ask them to explain one performance choice and how it changed the meaning of a line."},"use":[],"home":"Perform a short poem or speech for someone at home, then ask what they understood from it.","vocab":"intonation, tone, volume, pace, pause, silence, stillness, gesture, improvise, subtext","understand":"What did the silence in your performance say that words couldn't?","lookFor":"Explains a specific pause or silence and the feeling or meaning (tension, hurt, hesitation) it showed the audience."}
  ];
  const LEVELS = ["Early", "First", "Second", "Third", "Fourth"];
  return {
    all: () => lessons.slice(),
    get: id => lessons.find(l => l.id === id) || null,
    // Lessons that use a piece of PopSpell work, for suggesting them when a pupil finds it hard
    forWork: id => lessons.filter(l => l.use.includes(id)),
    // Lessons for an area and CfE level, in teaching order (England's own lessons come last)
    forArea: (subject, level) => lessons.filter(l => l.subject === subject && (!level || l.level === level)),
    LEVELS,
    MINUTES: { start: 5, teach: 10, practise: 10, check: 5 }
  };
})();
